quests[1428] = { id = 1428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortwährende Gefahr", description = "Freut mich zu sehen, dass Euer Hass auf die Fischmenschen mit meinem wächst.\n\nSucht mehr von ihnen am Strand entlang, und wenn Ihr genug vom Gefecht habt, kommt zu mir zurück. Dann sprechen wir über eine Belohnung für Eure Ausdauer.", sourceObjective = "Tötet 10 Marschentintenspucker, 10 Marschenfleischfresser und 10 Marschenorakel und kehrt dann zu Katar in den Sümpfen des Elends zurück.", progress = "Erst wenn das Meer und all seine Kinder verstummt sind, werde ich zufrieden sein... besonders diese abstoßenden Fischmenschen.", completion = "Gut gemacht, {class}. Ich möchte mehr von ihrem Blut sehen. Mögen alle Fischmenschen verschwinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[1429] = { id = 1429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verbannte der Atal'ai", description = "Während Ihr den Gefahren des Tränenteichs getrotzt habt, kehrte einer meiner Späher mit einer in Blut und auf getrocknetem Fleisch geschriebenen Rolle zurück. Es scheint sich um ein Urteil gegen einen der Priester des Stammes der Atal'ai zu handeln.\n\nDer Priester wurde zu etwas Schlimmerem als dem Tod bei den Atal'ai verurteilt.\n\nEr wurde ins Hinterland zu den Trollen der Bleichborken verbannt.\n\nIch bündle diese Artefakte. Ihr müsst den Verbannten suchen und ihren wahren Verwendungszweck herausfinden. Kommt wieder zu mir, wenn Eure Reise beendet ist.", sourceObjective = "Bringt das Artefaktbündel der Atal'ai zu dem Verbannten der Atal'ai ins Hinterland.", progress = "Ihr seid tapfer, hierher zu kommen. Tapfer oder töricht...", completion = "Bringt Ihr mir die Beschwörungsartefakte der Atal'ai?\n\nIch sehe, dass Jammal'an der Prophet die Schüler der Kammer des Blutes zu ihrem gewählten Schicksal führen wird. Ob Hakkar wohl zum Tempel zurückgekehrt ist? Hat sich ihr Schicksal erfüllt?", sourceObjectiveStatus = "unverified-source-field" }
quests[1430] = { id = 1430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frischfleisch", description = "Bei meinen Kunden besteht eine enorme Nachfrage nach dem saftigen Geschmack von Kriecherfleisch; besonders nach dem Fleisch der monströsen Kriecher.\n\nWenn Ihr vorhabt, zur Küste zu reisen, könnte es sich lohnen, wenn Ihr mir einige ihrer Beine bringt, damit ich sie nach Orgrimmar transportieren lassen kann.\n\nDie Küste liegt östlich von hier. Ihr solltet keine Probleme haben, die Kreaturen zu finden, die an den Stränden und im Meer umherhuschen.", sourceObjective = "Bringt 10 monströse Kriecherbeine zu Dar in den Sümpfen des Elends.", progress = "Ich habe ein Fässlein Wein, das auf Euren Erfolg wartet, {name}. Es ist nur recht und billig, dass ich meine Ware prüfe, bevor ich sie zu den Kunden liefern lasse.", completion = "Ah, das müsste perfekt sein. Ich kann es kaum erwarten, sie zu kosten, wenn sie perfekt über einem offenen Feuer zubereitet wurden. Ihr solltet eine Kostprobe mit auf Eure Reisen nehmen. Es ist wirklich köstlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[1431] = { id = 1431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianzbeziehungen", description = "Seid still, {name}, und lasst mich Euch etwas Wichtiges über unser Volk sagen, das nicht auf der Hand liegt.\n\nWir sind ein stolzes Volk und der Krieg gegen die Menschen hat selbst Thralls große Geduld auf die Probe gestellt. Wisst Ihr, unser Kriegshäuptling ist weise und umsichtig und sein Volk kommt stets an erster Stelle. Letztendlich ist er ein Diplomat und hat in seiner Zeit bei den Menschen viel von ihrer Art gelernt.\n\nWenn die Geschichte, die ich begonnen habe, Euer Interesse weckt, dann geht zu Keldran beim westlichen Ausgang der Stadt. Dort steht seine Hütte.", sourceObjective = "Sprecht mit Keldran in Orgrimmar.", completion = "Putanni, Edler {class}. Ich bin Keldran, Student der Magie... und anderer mystischer Künste.\n\nDie Angelegenheit, in der Craven Euch hergeschickt hat, erfordert ein klein wenig mehr Feinsinnigkeit als bisher erforderlich war, aber das bedeutet nicht, dass Ihr unserer Sache nicht dienlich sein könnt.\n\nBitte macht es Euch bequem, dann sage ich Euch, warum der Kriegshäuptling meine Unterstützung braucht... und Eure.\n\nEs fängt mit Äußerlichkeiten an, {name}. Wie die Horde sich selbst sieht. Wie unsere Verbündeten uns sehen. Und am wichtigsten, wie unsere Feinde uns sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1432] = { id = 1432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianzbeziehungen", description = "Wenn die Allianz immer tiefer nach Kalimdor vorstößt, könnten falsche Schlussfolgerungen über mögliche Bündnisse der Horde mit der Brennenden Legion gezogen werden. Dazu darf es der Kriegshäuptling nicht kommen lassen. Und mit seinem Segen übernehme ich die Aufsicht darüber, dass alle Missverständnisse ausgeräumt werden.\n\nIch habe Agenten in der Gegend von Desolace am Geistwandlerposten nördlich des großen Kodofriedhofs. Wenn Ihr vom Verbrannten Tal im Steinkrallengebirge aus südwärts geht, solltet Ihr dort vorbeikommen. Wenn Ihr eintrefft, sucht Takata Stahlklinge auf.", sourceObjective = "Sprecht mit Takata Stahlklinge in Desolace.", completion = "Seid gegrüßt, {class}. Ihr bringt Neuigkeiten aus Orgrimmar, das ist gut.\n\nDie Dämonenbrut beherrscht dieses Gebiet noch schlimmer als der Geruch von Zentaurendung. Die Pferdemenschen beanspruchen dieses Land für sich, aber es gibt eindeutig Einflüsse außerhalb ihrer Kontrolle, die sie zerschmettern, hält man sie nicht im Zaum.\n\nEs freut mich nicht, dass wir die Zentauren indirekt unterstützen, aber es dient dem Wohl der Horde, daher erfülle ich meine Pflicht gegenüber dem Kriegshäuptling, auch wenn es bedeutet, dass ich den Hexenmeistern in der Horde helfen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[1433] = { id = 1433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianzbeziehungen", description = "Die Brennende Klinge verfolgt eigene Ziele; doch wisst, dass sie bis ins Mark böse sind und ihr Geist verderbt wurde. Sie zu vernichten ist die einzige Möglichkeit, ihnen Einhalt zu gebieten.\n\nKeldran schickte Maurin mit mir, weil er die Klinge und die Arglist ihrer Hexenmeister kennt.\n\nEr leitet unsere Verschwörungen gegen die Klinge, während ich mich um die anderen dämonischen Bedrohungen in Desolace kümmere.\n\nSprecht mit ihm und er wird Euch in seine Pläne einweihen.", sourceObjective = "Sprecht mit Maurin Knochenspalter in Desolace.", completion = "Ah, ja. Hilfe von denen, die dem Kriegshäuptling loyal sind, ist immer willkommen.\n\nMein Name ist Maurin. Ich bin hier auf Geheiß von Keldran und dem jungen Kriegshäuptling Thrall. Es ist mein Wunsch, dem jungen Anführer gegen das Böse beizustehen, das seine Regentschaft zu stören droht.\n\nKommt, kommt näher, {class}. Ich erkläre Euch meinen Plan, wie man die Eiterbeule Burning Blade beseitigen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[1434] = { id = 1434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschmutzt durch Satyrn", description = "Eine Dämonenplage geschieht nicht ohne andere Einflüsse - etwas anderes ermöglicht dem Bösen, Fuß zu fassen.\n\nEs mag mit einem schwachen Geist beginnen, einer unnötigen Gier nach Macht, möglicherweise Rachedurst oder der Verlockung nach höchster Gerechtigkeit. Wenn der Schmerz uns übermannt, dann nutzt uns das Böse aus - das Böse wie die Satyrn.\n\nBande wurden zwischen ihnen und der Brennenden Klinge geknüpft und Thrall hätte sie getötet. Sucht sie nordöstlich von hier und kommt zu mir zurück, wenn Ihr sie zurückgeschlagen habt.", sourceObjective = "Besiegt 7 Schurken der Zornsäer, 7 Teufelsanbeter der Zornsäer, 7 Verräter der Zornsäer sowie 7 Höllenrufer der Zornsäer und kehrt zu Takata Stahlklinge in Desolace zurück.", completion = "Ihr habt Eure Sache gut gemacht, {class}. Ihr habt Ehre und Entschlossenheit gezeigt.\n\nWenn Eure Kampagne in Desolace beendet ist, wird der Kriegshäuptling erfahren, dass ihr uns bei unseren Aktionen hier unterstützt und geholfen habt, dass sein Wille geschehe.\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[1435] = { id = 1435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennender Geist", description = "Für diese abscheulichen Kreaturen, die ihrem Lehen aus so egoistischen Gründen den Rücken kehren, ist der Tod höchst wünschenswert. Doch wenn man es mit denen zu tun hat, die sich der Dunkelheit verschrieben haben, reicht der Tod allein nicht aus.\n\nNehmt diesen Edelstein. Wenn einer der Brennenden Klinge dem Tode nahe ist, aktiviert seine Magie. Der Zauber wird den verderbten Geist aus seinem Opfer herausziehen und einen damit erfüllten Edelstein hinterlassen.\n\nBringt mir diese erfüllten Edelsteine, damit ich sie angemessen entsorgen kann.\n\nGeht jetzt, und möge Euch der Tod meiden.", sourceObjective = "Bringt den brennenden Edelstein und 15 erfüllte brennende Edelsteine nach Desolace zu Maurin Knochenspalter.", progress = "Ich habe versucht, die Magie so einfach wie möglich zu machen. Es sollte ein Kinderspiel sein, den Geist Eures Opfers aus seiner verletzten Hülle herauszuziehen. Verlasst Euch aber nicht darauf, dass die Macht des Edelsteins Eure Gegner ganz tötet. Ihr dürft den Edelstein erst aktivieren, wenn sie dem Tode nahe sind, sonst ist er wirkungslos.", completion = "Ah, Ihr seid erfolgreich zurückgekehrt. Das ist gut. Gebt mir die Edelsteine und ich verwahre sie an einem sicheren Ort...\n\nMeine Aufgaben für Euch sind abgeschlossen, {class}. Sprecht mit Takata, wenn Ihr erholt seid. Er hat vielleicht andere Aufgaben für Euch oder bittet Euch nach Orgrimmar zurückzukehren, um Keldran von den Fortschritten hier in Desolace zu informieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[1436] = { id = 1436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allianzbeziehungen", description = "Der Kampf läuft gut, {name}. Vielleicht lässt uns der Kriegshäuptling, bevor die Jahreszeiten wechseln, in unsere Heimat zurückkehren, wenn der Kampf gegen die Dämonen und ihre Unterlinge weiterhin so gute Fortschritte macht.\n\nKehrt zu Keldran zurück und lasst ihn wissen, was wir getan haben. Ich bin sicher, er belohnt Euch für Eure Taten hier. Seine Sache ist ihm wichtig und es wird ihn mit Stolz erfüllen, wenn er weiß, dass der Kriegshäuptling seine Sorgen respektiert.", sourceObjective = "Sprecht mit Keldran in Orgrimmar.", completion = "Ihr seid mehr als erfolgreich aus Desolace zurückgekehrt, {name}. Danke.\n\nDanke für Eure Bemühungen, Eure Zeit und Euer Verständnis für meine Bitte. Thrall versteht und wünscht Frieden zwischen der Horde und der Allianz, und wenn wir Maßnahmen ergreifen, um unser Erscheinungsbild zu verbessern, werden wir keine weitere sinnlose Gewalt provozieren.\n\nIch stehe in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[1437] = { id = 1437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vahlarriels Suche", description = "Ich bin Vahlarriel, {name}. Ich kam her, um mich nach dem Befinden zweier vermisster Adliger einer Kaufmannsfamilie aus Darnassus zu erkundigen - Haus Malem. Der Vater des Hauses fürchtet das Schlimmste. Ich soll tun, was ich kann, um seine vermissten Kinder zu finden. Ich habe noch nicht mit der Suche nach Tyranis und Dalinda begonnen, hoffe aber, ich werde mich nicht lange hier aufhalten.\n\nZuletzt hörte man, dass sie vor wenigen Wochen durch das Steinkrallengebirge gekommen sein sollen.\n\nFalls Ihr ihren Wagen findet, sucht mich bitte unverzüglich auf.", sourceObjective = "Sucht und findet den Wagen von Tyranis und Dalinda Malem in Desolace.", completion = "Als Ihr in den Überresten des Wagens sucht, stellt Ihr fest, dass er mit Zauber und mit Waffen angegriffen wurde. Es scheint ein ungleicher und schneller Kampf gewesen zu sein; Blut ist keines zu sehen, auch keine Toten.\n\nWer immer den Wagen angegriffen hat, war tüchtig und schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[1438] = { id = 1438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vahlarriels Suche", description = "Sucht Dalinda und Tyranis, wenn Ihr könnt, und berichtet mir von Euren Funden. Beginnt Eure Suche in dieser Festung. Ich setze mich sofort mit meinen Vorgesetzten in Darnassus in Verbindung und informiere sie über die Situation.\n\n{name}, ich möchte Euch noch etwas wissen lassen. Meine Vorgesetzten haben Besorgnis wegen Tyranis und seinen Motiven für diese Reise geäußert. Es ist ihnen wichtiger, dass Dalinda gefunden und wohlbehalten zurückgebracht wird. Tyranis soll... überprüft werden, ehe man ihn nach Hause bringt.", sourceObjective = "Sucht Dalinda Malem in Desolace.", completion = "Elune sei Dank, endlich kommt jemand zu Hilfe. Bitte, {class}, ich brauche Eure Hilfe. Mein Bruder Tyranis und ich wurden von den Burning Blade gefangen genommen und hierher gebracht. Ich glaube, sie wollen mich ihren Dämonenmeistern opfern!\n\n Ich weiß, es war ein Fehler, nach Desolace zu kommen, aber Tyranis entwickelte jüngst ein Interesse an allem Arkanen - gegen den Wunsch unserer eigenen Leute. Er beschloss, diese Reise zu machen, als er von der Dämonenplage des Landes erfuhr.\n\nIch fürchte das Schlimmste für ihn.", sourceObjectiveStatus = "unverified-source-field" }
quests[1439] = { id = 1439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Tyranis", description = "Wir wurden hierher gebracht, nachdem die Orcs alle unsere Wachen und Diener abgeschlachtet hatten. Oh, was haben sie ihnen Schreckliches angetan! Ich dachte, sie würden uns auf der Stelle töten, doch dann wurde deutlich, dass sie andere Pläne hatten.\n\nTyranis versuchte, mit ihnen zu reden. Ich glaube, er wollte sie mit seinem arkanen Wissen beeindrucken...Ich bin nicht sicher, warum.\n\nBitte, ich kann hier nicht weg, bevor ich weiß, was meinem Bruder zugestoßen ist. Sucht ihn und kommt zu mir, wenn Ihr sein Schicksal kennt.", sourceObjective = "Sucht Tyranis Malem in Desolace.", progress = "Ich fürchte, Tyranis wird versuchen, die Geheimnisse der Burning Blade zu erlernen und sich ihnen anschließen, wenn sie ihn lassen - er hat stets die Macht bewundert, die Magie allen bringt, die sich von ihr verführen lassen.\n\nIch bin nicht sicher, ob ich zu meiner Familie zurückkehren und ihnen sagen kann, dass Tyranis' Geist mit solchen Gefahren spielt. Bei meinesgleichen ist es ein schreckliches Verbrechen, so etwas zu suchen, aber das zu werden, wovor wir uns schützen möchten, das ist verständlich.", completion = "Das ist schrecklich! Aber ich denke, es war notwendig. Hättet Ihr es nicht getan, dann gewiss einer meines Volkes. Ich nehme an, ich sollte Euch danken... bitte verzeiht mir, wenn es unaufrichtig wirkt. Es war nicht böse gemeint.\n\nDa ich das Schicksal meines Bruders nun kenne, scheint es mir an der Zeit zu fliehen. Wenn Ihr noch gewillt seid, nehme ich Eure Hilfe an, um von diesem schrecklichen Ort zu fliehen.\n\nSolltet Ihr bereit sein, können wir uns in Sicherheit bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1440] = { id = 1440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Vahlarriel", description = "Also ist die Zeit gekommen? Ich weiß Eure Bemühungen zu schätzen, und wenn auch die Situation dafür nicht geeignet ist, lasst mich Euch jetzt für alles danken, was Ihr für mich und meine Familie getan habt. Wenn Ihr bereit seid, hier hält mich nichts mehr - wir können aufbrechen, falls es Euch passend erscheint.", sourceObjective = "Begleitet Dalinda Malem aus der Festung Donneraxt und kehrt zu Vahlarriel Dämonenjäger nach Desolace zurück.", completion = "Danke, {name}. Dalinda hat es wohlbehalten zur Nijelspitze geschafft und in besserer Verfassung, als ich es für möglich gehalten hätte. Allein, dass sie aus eigener Kraft hier eintraf, war ein gutes Zeichen. Ich hoffe, es geht Euch gut.\n\nEs schmerzt mich zu wissen, dass weder Tyranis noch Dalinda zurückgekehrt sind, aber mit der Schande von Tyranis' Entscheidungen muss sie leben. Damit muss sie sich auseinander setzen, wenn sie nach Darnassus zurückkehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1442] = { id = 1442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach dem Koredelstein", description = "Seid gegrüßt, {name}. Was kann ich für einen tun, der dem heiligen Weg folgt?\n\nAh ja, Stillbrunn, der Schmied... das war vor langer Zeit. Ich erinnere mich gut an ihn, doch ich habe seinen Namen schon eine ganze Weile nicht mehr gehört.\n\nEr schien mir nie ein habgieriger Mann zu sein, daher kann ich nur davon ausgehen, dass sein Wunsch nach einem Koredelstein edle Motive hat.\n\nWenn Ihr wirklich so einen Edelstein möchtet, dann müsst Ihr in den Nordwesten des Eschentals. Dort findet Ihr die Tiefschwarze Grotte mit einigen alten Ruinen. Die Naga, die diese Edelsteine noch immer benutzen, sind dort unten. Geht nicht allein, {class}.", sourceObjective = "Bringt einen Koredelstein zu Thundris Windwirker in Dunkelküste.", progress = "Bei einem, der nicht dem heiligen Weg folgt, wäre ich nicht so vertrauensselig, wenn er nach einem Kor-Edelstein fragen würde. Aber ich traue Euresgleichen fast mehr als meiner Art. Ich beurteile nicht Euren ganzen Orden nach den Taten eines gefallenen Mitglieds.", completion = "Das ist wahrhaftig der Edelstein, den Stilwell begehrt, doch ehe ich zulassen kann, dass Ihr ihn zu ihm bringt, muss er von Verderbnis geläutert werden - die Frauen der Naga stärken die Edelsteine mit Macht, das stimmt, aber mit ihrer eigenen bösen Macht.\n\nLasst Stilwell wissen, dass die Macht unversehrt ist und bei jedem Ritual, das er durchführen möchte, funktionieren sollte.\n\nIch hoffe nur, Ihr wisst, was Ihr tut, {class}, es ist kein einfacher Gegenstand, den Ihr da besitzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1444] = { id = 1444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Fel'Zerul", description = "Jammal'an der Prophet verbannte mich aus dem Tempel von Atal'Hakkar. Einst empfand ich den Hohepriester als würdigen Anführer.\n\nSein unerschütterlicher Glaube an seine Prophezeiung wird den Untergang der Atal'ai herbeiführen. Wenn es nicht schon geschehen ist.\n\nAls ich meiner Besorgnis Ausdruck verlieh, hieß man mich einen Ungläubigen und verstieß mich aus dem Tempel.\n\nDie Artefakte, die Ihr zu mir brachtet, sind harmlos. Aber wenn Jammal'an die richtige Fetischverzauberung für das Beschwörungsritual gefunden hat, droht der Welt große Gefahr...", sourceObjective = "Kehrt zu Fel'Zerul in Steinard zurück.", completion = "Es ist eine Weile her, seit wir miteinander sprachen, {class}. Ich hoffe, Eure Reise war erfolgreich.\n\nWelches Wissen habt Ihr von dem verbannten Atal'ai im Hinterland erlernt?", sourceObjectiveStatus = "unverified-source-field" }
quests[1445] = { id = 1445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel von Atal'Hakkar", description = "Also sprach er von Jammal'ans Prophezeiung?\n\nDer spirituelle Anführer der Atal'ai glaubt, wenn Hakkar aus dem Nether nach Azeroth zurückkehrt, wird der Gott dem Stamm der Atal'ai Unsterblichkeit gewähren.\n\nTörichte Arglist, um den Jüngsten Tag schneller herbeizuführen, wenn Ihr mich fragt.\n\nDoch Ihr sagt, der Verbannte sprach von verzauberten Fetischen? Das erfüllt mich mit großer Sorge. Wenn sie wahrhaftig der Schlüssel zu dem Ritual der Atal'ai sind, das dieses Durcheinander verursachte, müssen wir die Mächte verstehen, die in ihnen wohnen.\n\nBegebt Euch in den Tempel und werdet dieser Fetische habhaft!", sourceObjective = "Sammelt 20 Fetische von Hakkar und bringt sie zu Fel'Zerul in Steinard.", progress = "Wenn die Fetische der Atal'ai die Macht besitzen, Hakkar zu beschwören und Jammal'ans Prophezeiung zu erfüllen, müssen wir sie haben. Die Horde muss solche Mächte verstehen!", completion = "Tapferer {class}, Ihr habt Euch als ein großer Held der Horde erwiesen.\n\nWir müssen uns unverzüglich um diese Fetischsammlung von Hakkar kümmern!", sourceObjectiveStatus = "unverified-source-field" }
quests[1446] = { id = 1446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jammal'an der Prophet", description = "Meine Bleichborkenbegleiter mögen keine Fremden in ihrer Nähe.\n\nIch? Ich habe keine Heimat mehr. Mein Volk, der große Stamm der Atal'ai aus den Sümpfen des Elends, hat mich verbannt.\n\nJammal'an, unser spiritueller Anführer, hatte eine, wie wir uns ausdrücken, Prophezeiung. Er glaubt, die Beschwörung des Gottes Hakkar bringt den Atal'ai Unsterblichkeit.\n\nIch jedoch drängte auf Vorsicht. Wenn die Prophezeiung nun nichts weiter als Manipulation war?\n\nIch will Rache für meine Verbannung. Bringt mir Jammal'ans Kopf. Vielleicht ist mein Volk dann frei.", sourceObjective = "Der Verbannte der Atal'ai im Hinterland möchte den Kopf von Jammal'an.", progress = "Sobald Jammal'an nicht mehr ist, habe ich die Chance, zu meinem Volk zurückzukehren.\n\nMit Jammal'an als ihrem spirituellen Anführer ist der Untergang der Atal'ai gewiss.", completion = "Jammal'ans blindes Vertrauen in falsche Visionen führte mein Volk in die ewige Verdammnis.\n\nIch danke Euch, {class}, dass Ihr meine Verbannung gerächt habt. Ich trauere um mein Volk. Jetzt habe ich keine Heimat mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[1447] = { id = 1447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Diplomat", description = "Hm, Ihr seid offenkundig nicht <einer/eine> der Klügsten Eures Handwerks, <der/die> je nach Sturmwind kam, aber <einer/eine> der Dümmsten, wenn Ihr nicht wieder fortgeht.\n\nHabt Ihr meine Freunde getroffen?", sourceObjective = "Besiegt Dashel Steinfaust in Sturmwind.", completion = "Es gibt also einen Grund, dass Ihr zu mir kommt. Was ist Euer Begehr?", sourceObjectiveStatus = "unverified-source-field" }
quests[1448] = { id = 1448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach dem Tempel", description = "Es gab eine Zeit, da war ich jung und voller Kraft, wie Ihr, {class}.\n\nDoch jetzt bin ich alt und vermag die Welt nicht mehr zu erforschen wie einst. Ach, was habe ich nicht alles gesehen!\n\nAber ein Geheimnis entzog sich mir stets. Als meinen letzten Auftrag schickte mich die Forscherliga auf die Suche nach dem Tempel von Atal'Hakkar. Er sollte Gerüchten zufolge in den Sümpfen des Elends liegen.\n\nMeines gebrechlichen Zustands wegen reiste ich auf einem Greif durch die Lüfte, fand den Tempel aber nie.\n\nHelft Ihr einem alten Zwerg? Vielleicht habt Ihr zu Fuß mehr Glück.", sourceObjective = "Brohann Fassbauch in Sturmwind möchte, dass Ihr den Tempel von Atal'Hakkar sucht.", completion = "Der Tempel von Atal'Hakkar ist im Tränenteich versunken? Und vom grünen Drachenschwarm umzingelt?\n\nEine erstaunliche Entdeckung, {class}. Aber offenkundig ist etwas furchtbar schief gegangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1449] = { id = 1449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Hinterland", description = "Wie ich schon früher sagte, versuchte ich selbst, den Tempel aus der Luft zu finden. Ganz allein war ich freilich nicht.\n\nIch reiste zu dem berühmten Greifenhorst beim Nistgipfel im Hinterland. Dort versicherte ich mich der Hilfe eines ihrer besten Piloten. Der Pilot fiel von seinem Reittier in den Sumpf...\n\nDen Namen des armen Burschen habe ich im Alter vergessen. Der Meister des Horsts kennt ihn zweifellos noch.\n\nBegebt Euch dorthin und sucht nach Falstad Wildhammer.\n\nWir müssen herausfinden, was dem Piloten zugestoßen ist.", sourceObjective = "Sprecht mit dem obersten Than, Falstad Wildhammer, am Nistgipfel im Hinterland.", completion = "Was wollt Ihr, Jüngelchen? Seht Ihr denn nicht, dass ich mich hier um Probleme kümmern muss? Wer hat schon Zeit, hier rumzustehen und mit einer Quasselstrippe von {race} zu plaudern?\n\nEs kommen Trolle aus dem Unterholz! Fasst Euch kurz.", sourceObjectiveStatus = "unverified-source-field" }
quests[1450] = { id = 1450, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Greifenmeister Krallenaxt", description = "Ihr seid also nur ein <besserer Botenjunge/besseres Botenmädchen> für einen alten Tattergreis der Forscherliga, hm?\n\nHört mir gut zu, {class}. Ich habe keine Ahnung, mit wem Euer alter Kumpel da unten in Azeroth rumgeflogen ist. Seh ich etwa wie der Greifenmeister Krallenaxt aus? Ja?\n\nWenn Ihr Euch für die Flugpläne interessiert, warum fragt Ihr dann nicht den Greifenmeister? Wenn Ihr noch länger untätig hier herumhängt, werde ich Euch richtige Arbeit geben.\n\nUnd jetzt trollt Euch.", sourceObjective = "Sprecht mit Greifenmeister Krallenaxt im Horst beim Nistgipfel.", completion = "Ah, ja. Natürlich erinnere ich mich, wie ich einen meiner Greifenreiter ausschickte, um Brohann Caskbelly zu helfen.\n\nIch hatte immer schon eine Schwäche für die Forscherliga. Mein Vater half sogar bei der ersten Ausgrabung mit, die Uldaman fand.\n\nIch schickte damals den Greifenreiter mit Brohann, den ich für den besten hielt. Der Bursche hörte auf den Namen Rhapsody Shindigger.\n\nWas war der für ein Greifenreiter! Jedenfalls bis ...", sourceObjectiveStatus = "unverified-source-field" }
quests[1451] = { id = 1451, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhapsodie Kniegräber", description = "Rhapsodie fand Gefallen am Schnaps. Versteht mich nicht falsch - alle Zwerge hier im Horst wissen ein gutes Bier zur passenden Stunde zu schätzen.\n\nAber der alte Kniegräber brauchte den Fusel wie ein Greif den Himmel. Und das war echt ein Jammer. Niemand konnte so fliegen wie Rhapsodie.\n\nDie ersten Probleme gab es, als er mit Eurem Freund Brohann von dieser Mission zurückkehrte. Danach ging es rapide bergab. Musste ihn rauswerfen.\n\nZuletzt hörte ich, er habe östlich von hier eine Brauerei eröffnet...", sourceObjective = "Sucht Rhapsodie Kniegräber im Hinterland.", completion = "Hicks!\n\nIch seh Euch gerade an, aber Ihr hüpft immerzu auf und ab. Das macht mich ganz schwindelig. Hoho!\n\nHicks!\n\nBoah! Habt Ihr das gespürt? Die Erde bebt. Ich muss was trinken.\n\nHicks!", sourceObjectiveStatus = "unverified-source-field" }
quests[1452] = { id = 1452, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhapsodies Kalimdor-Cocktail", description = "Hicks!\n\nDieser irre Narr Brohann schickt Euch also? Wir haben ein tolles Abenteuer zusammen erlebt... Hicks!\n\nWenn ich Euch erzählen soll, was da unten im Sumpf passiert ist, brauch ich was Ordentliches zu trinken. Das war echt kein schöner Anblick. Hicks!\n\nIch sag Euch was... bringt mir, was ich brauche, um einen Kalimdor-Cocktail zu mixen, dann erzähl ich Euch davon.\n\nMan braucht dazu den Muskelmagen eines Roc aus Tanaris... etwas Groddoc- und Eisenfellleber aus Feralas...\n\nEin schöner kräftiger Kalimdor-Cocktail... dann kann ich plaudern!", sourceObjective = "Rhapsodie Kniegräber im Hinterland möchte, dass Ihr ihm 3 Muskelmägen eines Roc, 3 Groddoclebern und 3 Eisenfelllebern bringt.", progress = "Schon mal ein Rhapsody-Malzbier getrunken? Eines meiner besten Gebräue, wenn ich das so sagen darf. Hicks!\n\nAber wenn ich den Schrecken dieses Fluges über... hicks... den Sumpf noch mal durchleben soll, brauch ich was deutlich Stärkeres. Hicks!\n\nIhr habt wohl nicht zufällig die Muskelmägen und Lebern gefunden, die meinem Kalimdor-Cocktail den richtigen Pfiff geben?\n\nHicks!", completion = "Wie ich sehe, habt Ihr mir mühelos beschafft, was ich brauche! War bestimmt nicht leicht für Euch im fernen Kalimdor.\n\nDauert nur einen Moment, bis ich aus den Muskelmägen und Lebern extrahiert habe, was ich brauche. Hicks!\n\nDann kann ich mir einen starken Drink brauen und Euch endlich erzählen, was Ihr wissen wollt.\n\nHicks!\n\nWenn ich nur an den ollen Sumpf denke, krieg ich 'ne Gänsehaut.\n\nHicks!\n\nIch werd den Drink schnell zusammenrühren.", sourceObjectiveStatus = "unverified-source-field" }
quests[1453] = { id = 1453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschäfte der Wiederholer in Desolace", description = "Es gibt Arbeit in Desolace, {name}. Das ist ein grässlicher Ort, beschmutzt von Zentauren und anderer Unbill. Aber wenn Ihr eine Woche ehrlicher Arbeit sucht, dann geht dorthin, besucht Kreldig Ungor und sagt ihm, ich hab Euch geschickt.\n\nIhr findet ihn an der Nijelspitze - dem gemütlichen kleinen Lager in den Bergen des nördlichen Desolace. Haltet Euch einfach ostwärts, wenn Ihr vom Steinkrallengebirge kommt. Man übersieht es leicht, also seid wachsam.", sourceObjective = "Sprecht mit Kreldig Ungor in Desolace.", completion = "Schön zu sehen, dass die Wiederbeschaffer nicht knapp an Arbeit oder Abenteurern sind, die ihnen aushelfen wollen.\n\nIch bin Kreldig, {name}. Es war eine kluge Entscheidung, den Wiederbeschaffern zu helfen. Heutzutage braucht jeder irgendetwas: Die Leute verlieren ein Familienerbstück, einen magischen Gegenstand oder einen geliebten Menschen. Es ist schon recht erstaunlich. Aber wenn die Wiederbeschaffer in der Gegend sind, gibt es keinen Grund, warum nicht jeder für einen angemessenen Preis wiederbekommen sollte, was er verloren hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[1454] = { id = 1454, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karnitols Schiffbruch", description = "Seid gegrüßt, <mein Freund/meine Freundin>. Nehmt doch Platz...\n\nMein erster Auftrag betrifft den Magier Karnitol - eine Art Edelmann in Sturmwind. Offenbar wurde sein Schiff vor der nordwestlichen Küste von Desolace von Meeresriesen angegriffen. Er und seine Gefolgsleute versuchten, eine seiner wertvolleren Truhen an Land zu bringen, aber als die Meeresriesen in Schwärmen angriffen, beschloss er, sie aufzugeben und sich und seine Gefolgsleute in Sicherheit zu teleportieren.\n\nEr möchte, dass wir die Truhe samt ihrem Inhalt finden und zu ihm nach Sturmwind bringen.", sourceObjective = "Sucht Karnitols Truhe in Desolace.", completion = "Ihr bemerkt, dass die Truhe keine Wasserschäden genommen hat.\n\nAls Zweites bemerkt Ihr, dass der Deckel aufgebrochen wurde. Eventuelle magische Fallen, die der Sicherung dienten, wurden längst ausgelöst - das erkennt man an den Brandspuren an den Kanten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1455] = { id = 1455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karnitols Schiffbruch", description = "Ihr überlegt eine Weile, was die Kiste aufgebrochen haben könnte, und bemerkt an den Seiten und am Deckel lange, tiefe Kratzer, die belegen, dass sich etwas anderes als ein Mensch oder Riese dafür interessierte. Solche Spuren scheinen nicht von einem Dolch oder Schwert verursacht worden zu sein.\n\nIhr werft einen Blick in die Truhe und stellt fest, dass sie leer ist.\n\nDa Ihr nicht wisst, was Ihr sonst tun sollt, klappt Ihr die Truhe zu und rüstet zum Aufbruch. Kreldig wird enttäuscht sein.", sourceObjective = "Kehrt zu Kreldig Ungor in Desolace zurück.", completion = "Willkommen in der Nijelspitze, {name}. Sagt mir, was Ihr gefunden habt.\n\nWas!? Nichts? Ich fürchte, eine leere Truhe bringt uns keinen Lohn ein.\n\nErzählt mir mehr von diesen Spuren, die Ihr gesehen habt... diesen Rillen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1456] = { id = 1456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karnitols Schiffbruch", description = "Faszinierend.\n\nVielleicht besteht ja doch noch Hoffnung.\n\nAn derselben Küste, aber viel weiter nördlich, nahe der Insel Ranazjar, liegen Ruinen der Nachtelfen auf dem Grund des Meeres. Ein Stamm von Naga, die Zackenkämme, sind dort zu Hause. Das dürfte unsere beste Chance sein.\n\nWenn ein Kundschaftertrupp sich so weit in den Süden wagte, müssen sie sehr mächtig sein. Wenn Ihr Kanitols Habseligkeiten finden wollt, würde ich mit den mächtigeren Naga anfangen: den Gezeitenjägern oder den Meerhexen.", sourceObjective = "Sucht Karnitols Ranzen und bringt ihn zu Kreldig Ungor in Desolace zurück.", progress = "Nicht, dass ich Nijel zu nahe treten wollte, wer immer das sein mag, aber dieses Lager ist nicht das bequemste, in dem ich je eine Nacht verbrachte, {name}.", completion = "Das ist toll, {name}! Ihr habt Karnitols Habseligkeiten gefunden!\n\nDiese elenden Naga machen ständig Ärger. Ich würde lieber mein Leben lang Krieg gegen die Horde führen als gegen ihre Art anzutreten. Ihr habt den Wiederholern einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1457] = { id = 1457, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karnitols Schiffbruch", description = "Bringt Karnitols Sachen zu Roetten in Eisenschmiede, er wird Euch die gute Arbeit wohl vergelten.\n\nHaha, wenn Ihr nicht aufpasst, wird er so zufrieden sein, dass er Euch bittet, als Festangestellter bei uns zu bleiben.\n\nWieder einmal gut gemacht, {name}.\n\nSeid auf dem Rückweg vorsichtig und lasst Euch nicht zu viel Zeit - Karnitol ist nicht der Geduldigste, aber dennoch höchst großzügig.", sourceObjective = "Bringt Karnitols Ranzen zu Roetten Steinhammer in Eisenschmiede.", progress = "Das Geschäft blüht, {name}, und ich habe nicht viel Zeit für Fragen. Wenn Ihr etwas von den Wiederholern wollt, rückt heraus damit. Wenn nicht, muss ich Euch bitten, mit einem meiner Handlanger zu sprechen. Sie sind durchaus imstande, sich um alles hier zu kümmern.", completion = "Ah, die Karnitol-Angelegenheit in Desolace. Exzellent!\n\nDie Truhe wurde also zerstört, aber die Gegenstände sind alle da, hm? Tja, das soll er selbst nachprüfen. Ein Gutes hat das Geschäft, das ich hier betreibe: Wenn er nicht zufrieden ist, kann ich ihm sagen, er soll in den Wind schießen! Die Leute erwarten von uns, dass wir ihr Zeug finden ... und nicht, dass alles in perfektem Zustand ist, wenn sie es zurückerhalten.\n\nGute Arbeit, {name}. Dann wollen wir Euch mal Euren Lohn geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[1458] = { id = 1458, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzien für die Wiederholer AG", description = "Zu meinen Pflichten hier gehört, Reagenzien für Linkstatsch zu beschaffen, einen Gnomenmagier in Kharanos. Roetten glaubt, das sei ein Kinderspiel, da wir ohnehin schon hier draußen sind. Ihm ist es gleich, dass wir auch so schon unterbesetzt sind.\n\nDie ersten paar Gegenstände auf seiner Liste sollten leicht zu beschaffen sein, und für alle, die mir helfen, springt eine satte Belohnung raus.\n\nIch brauche einige Hörner und Klauen von den Satyrn der Zornsäer östlich von hier. Bringt sie mir, dann nehmen wir uns den Rest der Liste vor.", sourceObjective = "Bringt 10 Zornsäerklauen und 10 Zornsäerhörner zu Kreldig Ungor in Desolace.", progress = "Abscheuliche Kreaturen, die Satyrn. Man sagt, sie seien irgendwie mit den Nachtelfen verwandt, doch das glaube ich nicht.\n\nIch glaube, das liegt nur an dem einen Elfen, der sie vor Jahren überredete, in den Krieg zu ziehen. Das hat die Welt für immer verändert. Heute ist sie viel gefährlicher und Furcht erregender.", completion = "Gut, gut, {name}. Ich bin nicht sicher, ob die Qualität ausreicht, aber wenn Leftwitch eine bestimmte Art wollte, hätte er es genauer sagen müssen, ehe er die Wiederholer losschickte.\n\nGehen wir zum nächsten Gegenstand auf der Liste, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[1459] = { id = 1459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzien für die Wiederholer AG", description = "Als Nächstes steht auf Linkstatschs Liste... mal sehen... hmm. Oh, da haben wir es.\n\nRecht einfach, aber mit sehr expliziten Anweisungen. Er braucht Gift von den Skorpashi und Bälge von Kodos. Im Kleingedruckten steht, beide müssen von bestimmten Kreaturen sein: Das Gift soll von irgendeinem Skorpashi stammen und der Balg muss von einem gealterten Kodo sein, aber keinem sterbenden oder uralten.\n\nMagier, ich sage Euch, was die so alles wollen... abartig.", sourceObjective = "Bringt 7 Phiolen Skorpashigift und 3 Bälge von gealterten Kodos zu Kreldig Ungor in Desolace.", progress = "Entschuldigt, dass ich Euch nicht sagen konnte, wo man Kodos oder Skorpashi findet. Ich kenne mich in der Gegend nicht gut aus und hatte keine Zeit, sie zu erkunden.", completion = "Eure Hilfe hier ist unschätzbar, {name}. Durch Euch muss ich nur die halbe Zeit in Desolace verbringen. Mit Eurer Hilfe bin ich im Handumdrehen wieder in Ironforge und wärme mir die Füße.\n\nWenn wir die Liste abgehakt haben und ich wieder zu Hause bin, schaut mal rein, ich spendiere Euch ein Bier.\n\nAber bis dahin sollten wir die restlichen Reagenzien sammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1462] = { id = 1462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdsapta", sourceObjective = "Sprecht mit Seherin Rabenfeder wegen eines weiteren Erdsaptas.", completion = "Nehmt dies und vergesst nicht, es ist heilig.", sourceObjectiveStatus = "unverified-source-field" }
quests[1463] = { id = 1463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdsapta", sourceObjective = "Sprecht mit Canaga Erdenrufer wegen eines weiteren Erdsaptas.", completion = "Ich gebe Euch voller Vertrauen einen. Ihr habt Euren Wert schon einmal bewiesen, doch ich finde, künftig solltet Ihr vorsichtiger sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1464] = { id = 1464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuersapta", sourceObjective = "Sprecht mit Telf Joolam wegen eines weiteren Feuersaptas.", completion = "Möge Feuer in Eurem Herzen brennen, {name}.\n\nDie Elemente erwarten Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[1465] = { id = 1465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vahlarriels Suche", description = "Als Ihr Eure Suche nach dem Wagen fortsetzt, findet Ihr nicht nur einen Anhänger, sondern auch Fußspuren, die in Richtung Süden führen. In der Ferne seht Ihr Rauch von einem großen Fort aufsteigen. Der Rauch stammt von einem Lagerfeuer, nicht von brennenden Gebäuden. Euer Instinkt sagt Euch, dass die Malems, wenn sie noch leben, in diese Richtung gebracht wurden.\n\nIhr seid der Ansicht, dass Vahlarriel an der Nijelspitze nicht nur den Anhänger sehen sollte, den Ihr gefunden habt, sondern auch von den Lebenszeichen im Süden wissen sollte.", sourceObjective = "Kehrt mit Malems Anhänger zu Vahlarriel Dämonenjäger in Desolace zurück.", completion = "Zum Auswachsen! Dieses ganze Fiasko!\n\nDie beiden waren gewarnt, wie gefährlich es sein würde, hierher zu kommen. Nun werden sie vermisst... oder Schlimmeres.\n\nIhr sagt, Ihr habt Spuren zu einem Fort in der Nähe gesehen? Das dürfte unsere beste Chance sein.\n\nSchenkt man den Einheimischen Glauben, wimmelt es in dieser Festung von Orcs der Burning Blade, die sich dämonischen Mächten verschrieben haben. Sie teilen vielleicht nicht die meisten Ansichten der Horde, sind aber böse und töten ohne Umschweife, wenn sie jemanden beim Spionieren erwischen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1466] = { id = 1466, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzien für die Wiederholer AG", description = "Das ist der letzte Gegenstand und ganz ehrlich, er ist nicht schön. Ich gehe auch davon aus, dass Ihr dafür etwas länger braucht als für die anderen Gegenstände.\n\nDoch genug der Warnungen, fangen wir an. Linkstatsch sagt, er braucht Folgendes: zehn Gehirne, entweder von Manafressern, Magierjägern oder Leyjägern, zehn Netherflügel von einer Nethermaid, -schwester oder -zauberin. Und... zehn Phiolen Verdammniswächterblut von einem Hauptmann oder Lord der Verdammniswächter.\n\nGanz einfach, hm? Tja... ich hätte Verständnis dafür, wenn Ihr dies ausschlagen wollt.", sourceObjective = "Bringt 10 Teufelshundgehirne, 10 Netherflügel und 10 Phiolen Verdammniswächterblut zu Kreldig Ungor in Desolace.", progress = "Ich wusste nicht einmal, dass es diese Dämonenwesen in Desolace gibt. Zuletzt hörte ich, dass das Land weitgehend den Zentauren gehört, nachdem die Nachtelfen vor Jahren zusammengepackt haben und abgezogen sind.\n\nIch frage mich, warum und wie sie hierher kamen.", completion = "Ehrlich? Das hätte ich nicht gedacht. Ihr seid erstaunlich, {name}. Es wegen eines Magierexperiments mit Dämonen aufzunehmen und unversehrt zurückzukehren. Gute Arbeit!\n\nWenn ich wieder in Ironforge bin, werde ich Roetten persönlich von Euch berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1467] = { id = 1467, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagenzien für die Wiederholer AG", description = "Wenn Ihr Eure Bezahlung wollt, müsst Ihr nach Eisenschmiede zurück und persönlich mit Roetten sprechen. Er dürfte froh sein, wenn er Linkstatschs Päckchen vom Hals hat. Gebt ihm das, es müsste genügen, damit Ihr Euren Anteil bekommt.\n\nKeine Bange, ich werde trotzdem ein gutes Wort für Euch einlegen, wenn ich zurück bin. Ich sollte nicht mehr lange in Desolace bleiben müssen.", sourceObjective = "Bringt Linkstatschs Päckchen zu Roetten Steinhammer in Eisenschmiede zurück.", progress = "Grüße, {name}. Das Geschäft blüht, die Laute von Hämmern auf Ambossen hallen durch ganz Ironforge, die Blasebälge entfachen das Feuer und meine Frau backt mir einen Kuchen als Dessert nach dem Abendessen. Könnte das Leben schöner sein?", completion = "Ah, das Päckchen für Leftwitch aus Desolace. Exzellent. Ich schätze Eure Arbeit und Eure Pünktlichkeit, {class}. Schön, dass wir Euch wenigstens für diesen kleinen Auftrag an Bord haben.\n\nIch habe Euren Lohn hier. Lasst alle wissen, dass die Wiederholer AG für eine harte Arbeit stets guten Lohn bezahlt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1468] = { id = 1468, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kinderwoche", description = "Ihr wollt uns tatsächlich hier im Waisenhaus zur Hand gehen? Seid gesegnet, Freund. Eure Unterstützung in der Kinderwoche ist für uns von unschätzbarem Wert.\n\nNehmt diese Pfeife. Sie kann sieben Tage lang verwendet werden - über die ganze Dauer der Kinderwoche hinweg. Durch Benutzung der Pfeife, könnt Ihr mit dem Waisenkind sprechen, auf das Ihr aufpasst. Verwendet sie erneut, um das Kind wieder zu entlassen.\n\nDas Kind ist schon ganz aufgeregt und freut sich darauf Euch kennenzulernen. Worauf wartet Ihr noch {name}, benutzt die Pfeife und trefft Euren Schützling.", sourceObjective = "Benutzt die Pfeife des Menschenwaisenkindes um während der Kinderwoche mit Eurem Schützling zu sprechen.\n\nBereitgestellter Gegenstand:", completion = "Um... hi. Meine Name ist Randis und ich glaube, Ihr sucht nach mir? Ihr seid ein Abenteurer, genauso wie es meine Mama und mein Papa waren. Ich bin so glücklich Euch zu treffen!\n\nHoffentlich erleben wir zusammen viele lustige Sachen. Es gibt so viele Sachen, die ich gerne einmal machen würde und die Matrone hat gesagt, dass Ihr diese Woche so etwas wie mein großer Bruder seid. Das finde ich toll!", sourceObjectiveStatus = "unverified-source-field" }
quests[1469] = { id = 1469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rhapsodies Geschichte", description = "Vor dem Flug trank ich ein ganzes Fass Starkbier. Hicks!\n\nUnd was für ein Flug das war. Ich sauste herum und Brohann folgte mir. Aber ich hab keinen Tempel nicht gesehen. Hicks!\n\nJedenfalls sah ich keinen Tempel, bis mir schwindlig wurde und ich von meinem Reittier fiel. Ich fiel kopfüber ins Wasser und wurde in die Tiefe gesogen. Dort sah ich mich von einer Schar unheimlicher Trolle umringt. Ich schwamm, was das Zeug hielt! Und schaffte es sogar mit diesem Trollsouvenir da raus. Hier, bringt es Brohann und lasst ihn wissen, dass der Tempel tatsächlich da unten ist. Hicks!", sourceObjective = "Bringt das Schrifttafelfragment der Atal'ai zu Brohann Fassbauch in Sturmwind.", progress = "Endlich seid Ihr zurückgekehrt, {name}. Es ist eine Weile her, seit wir zuletzt miteinander sprachen. Ich dachte schon, Ihr hättet meinen Auftrag an Euch vielleicht vergessen.\n\nHabt Ihr diesen nichtsnutzigen Greifenreiter gefunden? Hatte er etwas zu berichten?", completion = "Rhapsody Shindigger! Genau... wie konnte ich so einen Namen nur vergessen?\n\nEr wusste also die ganze Zeit von dem versunkenen Tempel? Also das hätte Euch gewiss eine Menge Laufarbeit sparen können.\n\nAber dieses Artefakt der Atal'ai! Das nenne ich einen Fund!", sourceObjectiveStatus = "unverified-source-field" }
quests[1470] = { id = 1470, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der zerrissene Schleier", description = "Seid gegrüßt, Kind. Ich sehe, dass Ihr noch unerfahren in den Dingen der Hexenmeister seid, dass sich die Macht noch Eurem Griff entzieht. Doch ich spüre Euren Eifer zu lernen.\n\nUnd Ihr werdet lernen.\n\nDurch Ignoranz kann man keine Stärke finden. Wissen ist unsere größte Macht. Indem wir es anwenden, können wir die chaotische Magie und die Wesen der Leere kontrollieren und unserem Willen beugen.\n\nIch zeige Euch, wie Ihr einen Diener an Euren Willen bindet, doch zuerst müsst Ihr mir drei Schädel der klappernden Skelette nahe der verlassenen Schmiede bringen.", sourceObjective = "Bringt Venya Marthand 3 Schädel eines klappernden Skeletts.", progress = "Eure Macht ist noch gering, doch ich vermute, Ihr ahnt die Möglichkeiten bereits.\n\nMit der Macht, die uns durchströmt, könnten selbst Tote sich lebendig fühlen.", completion = "Wiewohl Ihr noch unerfahren und am Anfang des Lernens seid, habt Ihr bewiesen, dass Ihr hinreichend Fähigkeiten besitzt, das Beschwören und Binden eines Wichtels zu meistern. Lasst Euch nicht von der Größe eines Wichtels täuschen. Ihm fehlt es zwar an Körperkraft, aber dafür besitzt er Macht und Klugheit, die Euch dienlich sein werden.\n\nHört mir gut zu, {name}, denn ich werde diese Lektion nicht wiederholen und überlasse es Euch, sie zu meistern.", sourceObjectiveStatus = "unverified-source-field" }
quests[1471] = { id = 1471, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Gewiss habt Ihr den Kreis der Beschwörung unter uns bemerkt. Nur dort könnt Ihr einen ungebundenen Leerwandler herbeirufen.\n\nMit diesen Runen könnt Ihr ihn herbeirufen, dann müsst Ihr ihn durch die Kraft von Waffen und Magie beherrschen.\n\nWenn er unterworfen wurde, wird er Euch ergeben sein. Kommt dann zu mir und ich werde den Beschwörungszauber erklären, damit er Euch in jeder Hinsicht zu Willen ist.", sourceObjective = "Beschwört mit Hilfe der Runen der Beschwörung einen Leerwandler, unterwerft ihn und bringt die Runen der Beschwörung dann zu Carendin Halgar im Magieviertel von Unterstadt zurück.", progress = "Ich erwarte, von Eurem Erfolg zu hören, {name}. Doch solltet Ihr scheitern, wird es Eure geringste Sorge sein, dass Ihr meinen Erwartungen nicht entsprochen habt.", completion = "Ihr habt Eure Sache gut gemacht, {name}. Jetzt will ich Euch den Zauber verraten, mit dem der Leerwandler beschworen wird.\n\nDie Macht, die er freisetzt, steht nun zu Eurer Verfügung. Benutzt sie weise.", sourceObjectiveStatus = "unverified-source-field" }
quests[1472] = { id = 1472, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlinger der Seelen", description = "Ein Sayaad ist ein Verschlinger von Seelen, Bezwinger des Willens, Versucher der Herzen. Eine durch und durch böse und engstirnige Kreatur.\n\nDie Rechtschaffenen wie auch die Boshaften erzählen Geschichten über sie und verwenden dabei ihre bekannteren Namen: Sayaad in weiblicher Gestalt heißen Sukkubus, in männlicher Gestalt Inkubus.\n\nDer Dämon muss mit einem Anreiz in unsere Welt gelockt werden: den Herzen reiner und liebender Sterblicher. Diesen können Sayaad nicht widerstehen. Dann könnt Ihr sie beherrschen und zu Eurem Eigen machen.\n\nSprecht mit meinem Assistenten Godrick Farsan im Tempel. Er hilft Euch bei der Suche nach einem Köder.", sourceObjective = "Sprecht mit Godrick Farsan im Tempel der Verdammten.", completion = "Hat Carendin Euch geschickt? Nun gut, {name}.\n\nSchätzt mich nicht gering, weil mein Augenlicht erloschen ist. Ich sehe jetzt mit ungeahnter Klarheit Dinge, die mir verborgen waren. Was ich einst als Fluch erachtete, ist jetzt ein Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1473] = { id = 1473, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreatur der Leere", description = "Alle scheinen sich einig, dass Ihr nunmehr bereit seid zu lernen, wie man einen Leerwandler beschwört.\n\nEin aus dem jenseitigen Chaos erschaffenes Wesen - wenn Ihr eines beschwört, es aber nicht kontrollieren könnt, zerreißt es Euch.\n\nEgalin beschwor den ersten Leerwandler und hielt in seinem Zauberfoliant fest, wie es bewerkstelligt wird.\n\nLeider wurde er uns von einem Agenten des Scharlachroten Kreuzzugs gestohlen, der ihn in seinem Stützpunkt in einem Turm im Westen versteckte. Bringt ihn mir und ich lehre Euch das Wissen.", sourceObjective = "Beschafft Egalins Zauberfolianten und bringt ihn zu Carendin Halgar in den Tempel der Verdammten.", progress = "Egalin war der Lehrmeister, der mich unterrichtete. Er vermochte den Leerwandler, den er beschworen hatte, fast nebenbei zu kontrollieren.\n\nAls ich an der Reihe war, es zu versuchen, überschätzte ich mich. Spielt nicht mit den Mächten, die Ihr besitzt, {name}, sie können selbst den Wachsamsten verzehren.", completion = "Ah, das ist ausgezeichnet. Vermutlich hatte Perrine keine Ahnung von der wahren Macht des verstaubten Buches, das er uns gestohlen hatte.\n\nEs wird uns nicht noch einmal genommen werden. Studiert die Struktur des Zaubers, {name}, und die Art und Weise, auf die Eure Macht kanalisiert werden muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[1474] = { id = 1474, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Benutzt diese Herzen und wirkt einen Zauber am Beschwörungskreis, um eine Tür zu öffnen, durch die der Sukkubus kommen kann. Eure Mächte sind jetzt größer und Ihr werdet sie alle brauchen, um den Sukkubus zu besiegen. \n\nHütet Euch vor seinen Bezauberungen, {name}, manch starker Geist wurde schon seinem Willen unterworfen. Wenn er überwunden wurde, kehrt der Sukkubus in die Leere zurück, dann lehre ich Euch den Zauber, um ihn nach Eurem Gutdünken zurückzurufen.", sourceObjective = "Beschwört mit Hilfe der reinen Herzen einen Sukkubus, unterwerft ihn und bringt die reinen Herzen dann zu Carendin Halgar im Magieviertel von Unterstadt zurück.", progress = "Von den Mächten jenseits der Leere ist der Sukkubus eine der gefährlichsten, da er die Schwachen leicht um den Finger wickeln kann.\n\nDenkt jetzt und immerzu daran.", completion = "Wieder habt Ihr Eure Sache gut gemacht, {name}. Es ist eine Weile her, seit ich einen jungen {class} mit so viel Potenzial wie Euch gesehen habe. Seid versichert, dass ich Eure Fortschritte im Auge behalten und Euch bei künftigen Prüfungen vorbereiten und unterstützen werde.\n\nJetzt will ich Euch den Beschwörungszauber für den gerade von Euch unterworfenen Sukkubus zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1475] = { id = 1475, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Tempel von Atal'Hakkar", description = "Der Legende zufolge ist der Tempel von Atal'Hakkar ein heiliger Schrein, der dem alten Gott Hakkar dem Seelenschinder geweiht ist. Der Tempel, der von einem tückischen Trollstamm namens Atal'ai unterhalten wird, soll angeblich uneinnehmbar sein.\n\nDa der Tempel jetzt im Tränenteich versunken ist, dürfte es noch schwieriger sein, Artefakte zu bergen. Aber genau das müsst Ihr tun, {name}.\n\nHelft mir dabei, indem Ihr die intakten Schrifttafeln der Atal'ai sammelt. Bringt sie mir und ich schicke der Forschergilde einen Helden zurück. Wir werden uns den Ruhm teilen.", sourceObjective = "Sammelt 10 Schrifttafeln der Atal'ai für Brohann Fassbauch in Sturmwind.", progress = "Da sich langsam das Dunkel über meine Laufbahn senkt, wende ich mich an Euch, {name}, damit Ihr mir bei meinem letzten Auftrag für die Forscherliga helft. Wenn meine alten Knochen genug Kraft hätten, die Sümpfe des Elends und den versunkenen Tempel zu meistern, würde ich an Eurer Seite kämpfen.\n\nMein Stolz macht es mir schwer, Euch um Eure Hilfe beim Sammeln der Schrifttafeln der Atal'ai zu bitten. Doch das hohe Alter schließt andere Möglichkeiten aus.\n\nBitte helft mir, {name}. Ich möchte erst aus der Forscherliga ausscheiden, wenn ich ihre letzte Bitte erfüllt habe.", completion = "Die Schrifttafeln der Atal'ai! Ich danke Euch, {name}!\n\nWenn ich sie der Forscherliga übergeben habe, werden unser beider Namen in die Geschichte eingehen. Ihr habt einem alten Zwerg geholfen, die letzte Verpflichtung seines Lebens zu erfüllen. Dafür bin ich Euch ewig dankbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[1476] = { id = 1476, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzen der Reinen", description = "Einen Sukkubus anzulocken, erfordert ein reines Herz. Aber gibt es denn Sterbliche, die frei von Sünde sind?\n\nAnhand von Bruchstücken zufällig mitgehörter Geschichten habe ich zwei Menschen gefunden, die genügen sollten.\n\nDer Erste ist Dalin Schmiedevater, der sich der Fürsorge für die Flüchtlinge von Lordaeron verschrieben hat, die von ihresgleichen am Graumarnwall verstoßen werden.\n\nDer andere ist Corma Villard, eine Frau, die ihrer verlorenen Liebe treu bleibt und im Sumpfland nach Spuren von ihr sucht.\n\nBringt ihre Herzen zu Carendin. Doch zuvor möchte ich Euch Eure Opfer zeigen.", sourceObjective = "Bringt die Herzen von Dalin Schmiedevater und Corma Villard zu Carendin Halgar im Tempel der Verdammten.", progress = "Das Tempo Eurer bisherigen Fortschritte überrascht mich angenehm, {name}. Bringt mir die Herzen und Ihr werdet mich abermals beeindrucken.", completion = "Wenn man das Herz eines gütigen Menschen so sieht, schaut es aus wie alle anderen auch, findet Ihr nicht?\n\nVielleicht haben wir eine... andere... Sichtweise auf die Dinge. Aber diese werden genügen. Ich zweifle nicht, dass ein Sukkubus von ihrer Reinheit angelockt wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[1477] = { id = 1477, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überaus wichtige Vorräte", description = "Unsere Magier führen Forschungen in der Burg Nethergarde in den Verwüsteten Landen durch, die entscheidend für unser Verständnis der Dunklen Portale sind. Sie benötigen fast ununterbrochen Nachschub, doch unsere Nachschubwege nach Nethergarde sind dürftig.\n\nIhr müsst helfen sicherzustellen, dass der Nachschub nach Nethergarde gelangt. Meldet Euch bei Wachhauptmann Sorigal in Dunkelhain und tut, was er verlangt. Diese Aufgabe führt Euch in Feindesland, {name}. Macht Euch bereit.", sourceObjective = "Sprecht mit Wachhauptmann Sorigal in Dunkelhain im Dämmerwald.", completion = "Andromath schickt Euch? Sehr gut. Ich habe eine wichtige Aufgabe für Euch...", sourceObjectiveStatus = "unverified-source-field" }
quests[1478] = { id = 1478, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halgars Beschwörung", description = "Ah, {name}! Carendin Halgar ließ mich soeben wissen, dass er Euch für weitere Ausbildung sehen möchte.\n\nIhr solltet stolz auf Euch sein, {name} Es kommt nicht jeden Tag vor, dass Meister Halgar persönlich einen jungen Hexenmeister unterrichtet.\n\nIhr findet ihn im Magieviertel von Unterstadt nahe des Tempels der Verdammten.", sourceObjective = "Sprecht mit Carendin Halgar in Unterstadt.", completion = "Gut, wie ich sehe, konnte Ageron Euch finden, {name}. Vergeuden wir keine Zeit mit müßigem Geplauder und Höflichkeiten, sondern konzentrieren wir uns auf die Ausbildung. Ihr habt immer noch viel zu lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1479] = { id = 1479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Baum der Ewigen", description = "Ich habe Geschichten von den Nachtelfen gehört, darüber, dass sie ihre Bank in einen Baum gebaut haben, der aber wie ein Bär aussieht. Das ist so cool! Nachtelfen sind niedlich, wie sie die Natur lieben und so, aber Bären sind der Hammer!\n\nWürdet Ihr bitte mit mir den Bärenbaum in Darnassus angucken gehen? Es gibt ein Boot, das uns ganz in die Nähe dorthin bringt und es wird auch bestimmt nicht lange dauern. Bitte, bitte, bitte!", sourceObjective = "Begleitet Euren Schützling zur Bank in Darnassus. Die dortige Bank ist in einen Baum gebaut, welcher als der Baum der Ewigen bekannt ist.", completion = "Wow, der Baum der Ewigen ist wieder krasser als ich ihn mir je vorgestellt habe! Ich hätte nie gedacht, dass er so groß ist und hast du die Bäume auf der Spitze gesehen?! Ich frage mich, wie sie die Äste so formen konnten.\n\nDanke, dass du mich nach Darnassus mitgenommen hast, {name}. Du bist toll!", sourceObjectiveStatus = "unverified-source-field" }
quests[1480] = { id = 1480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderber", description = "Die zerrissene Haut riecht verfault und ist erstaunlich geschmeidig für etwas, das so trocken und zerbrechlich wirkt.\n\nAls Ihr sie aufrollt, könnt Ihr deutlich die roten Zeichen einer Art Sprache auf der einen Seite erkennen. Am unteren Ende der Haut befindet sich ein sehr deutliches Symbol, das Ihr für eine Art Unterschrift haltet.\n\nVielleicht könnte Maurin Euch mehr darüber erzählen?", sourceObjective = "Bringt die geschundene Dämonenhaut nach Desolace zu Maurin Knochenspalter.", progress = "Die Burning Blade begreifen langsam, wie schwach sie wirklich sind. Ihre Magie ist jämmerlich, ihre Stärke lachhaft.\n\nIhre einzige Macht kommt von jenen, denen sie dienen, und nicht von einem Verständnis von wahrer Macht und Wissen.", completion = "Hmm, diese Runen stammen tatsächlich von einer Sprache, {name}, einer alten Sprache. Sie scheinen vage Ähnlichkeit mit der Sprache der Eredun zu haben, doch die Unterschiede sind gewichtig. Wenn ich mich nicht irre, ist dies eine Art von Vertrag... Hier, ja, dieses Symbol ist die Unterschrift eines Dämons: Lord Azrethoc.", sourceObjectiveStatus = "unverified-source-field" }
quests[1481] = { id = 1481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderber", description = "Ich denke, mit den entsprechenden Reagenzien kann ich diesen Dämonenlord finden.\n\nWenn er wirklich so mächtig ist, wie ich vermute, brauche ich gesammelte Gegenstände von tödlichen Kreaturen. Doch Ihr handelt im Namen des Kriegshäuptlings, daher werdet Ihr die Aufgabe gewiss übernehmen.\n\nAls Erstes muss ich jeden Schutzzauber brechen, den er gegen Wahrsagen hat. Daher brauche ich den Skalp eines Satyrs... aber nicht den eines beliebigen Satyrs. Der Skalp muss von einem Schattenpirscher der Zornsäer stammen.\n\nSucht in den antiken Ruinen nordöstlich von Desolace nach ihnen.", sourceObjective = "Bringt Maurin Knochenspalter in Desolace einen Schattenpirscherskalp.", progress = "Bringt mir keinen falschen Skalp, {class}. Die falschen Reagenzien würden unseren Tod bedeuten. Der Dämonenlord könnte Kontingenzzauber besitzen, die alle töten, die ihm wahrsagen.\n\nDas Schicksal hat mir schon genug Schmerzen zugefügt.", completion = "Die Schattenpirscher konnten Euch nicht töten, {class}. Eindrucksvoll... höchst eindrucksvoll.\n\nDieser Skalp wird für meinen Zauber genügen. In Eurer Abwesenheit konnte ich einige andere Reagenzien für den Zauber sammeln.\n\nIch bin fast bereit. Ich brauche nur noch einen Fokus für den Zauber... etwas, um ein Bild des Dämonenlords und seines Aufenthaltsortes zu projizieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[1482] = { id = 1482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderber", description = "Ein Orakelkristall wäre genau richtig. Die Naga stellen sie her, damit ihre Orakel sie benutzen können.\n\nNordwestlich von hier liegt ein großes Korallenriff vor der Küste, das die Naga als ihre Heimat nutzen, da es so nahe am Ufer liegt. Dort könnt Ihr ihre Orakel finden. Die Zackenkammnaga sind tödlich und reagieren ungnädig auf Euer Eindringen, seid daher vorsichtig und eilt Euch.\n\nWenn Ihr zurückkehrt, suchen wir diesen Dämonenlord Azrethoc.", sourceObjective = "Bringt Maurin Knochenspalter in Desolace einen Orakelkristall.", progress = "Ich bin bereit für den Orakelkristall, {class}. Wenn wir diesen Lord Azrethoc finden und vernichten könnten, würden wir beide in der Gunst des Kriegshäuptlings steigen. Wir wären gut beraten, wenn wir eiligst zusammenarbeiten würden, damit wir unsere Sache voranbringen und in der Gunst des Kriegshäuptlings steigen.", completion = "Ein kostbarer Orakelkristall... makellos... wunderschön. So ist es.\n\nWir sollten unverzüglich beginnen. Unsere oberste Sorge sollte sein, diesen Dämonenlord zu finden. Unsere ganze Konzentration muss darauf gerichtet sein, ihn zu töten.\n\nTretet einen Schritt zurück, {class}, und lasst uns sehen, was dieser Dämon ist und wo wir ihn finden können.", sourceObjectiveStatus = "unverified-source-field" }
quests[1483] = { id = 1483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ziz Fizziks", description = "Die Venture Company stahl viele meiner besten Goblindenker, aber von Zeit zu Zeit bekommen wir Gelegenheit, einige zurückzustehlen.\n\nVor einiger Zeit stellte die Filiale der Venture Company im Steinkrallengebirge Gerenzo Pfeifzang ein... einen Gnom! Ihr anderer Ingenieur, Ziz Fizziks, war so erschüttert davon, dass er mich anflehte, ihm eine neue Stelle beim Tüftlerverband zu besorgen. Ich gab ihm einige Aufgaben, aber möglicherweise braucht er dabei Hilfe.\n\nVielleicht könntet Ihr mal nach dem Rechten sehen? Er ist am Westrand der Scherwindklippe stationiert.", sourceObjective = "Sprecht mit Ziz Fizziks bei der Scherwindklippe.", completion = "Ich dachte, die Bosse der Venture Company wären Sklaventreiber, doch dann traf ich Sputtervalve, den Grausamsten von ihnen!\n\nHa! Aber immer noch besser als arbeitslos zu sein, denke ich... Oder schlimmer, mit diesem Gerenzo zu arbeiten. Wenn Ihr helfen wollt, habe ich etwas für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[1484] = { id = 1484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderber", description = "Diese Kreatur ist weitaus gefährlicher als ich dachte. Zweifellos stellt Takata in Frage, dass ich so einer Kreatur gewachsen bin, und es würde ihn in seiner Ehre kränken, wenn er nicht wüsste, was gerade passierte.\n\nSprecht mit dem Schwertkämpfer, sagt ihm, Ihr seid bereit, den Dämon zu erschlagen, wenn er es erlaubt, aber bedrängt ihn nicht zu sehr. Es ist besser, wenn er denkt, dass es seine Idee war.", sourceObjective = "Sprecht mit Takata Stahlklinge in Desolace.", completion = "Ich wurde Zeuge, was soeben mit Maurin und dem Dämonenlord geschah. Diese Kreatur scheint selbst als Erscheinung mehr Macht zu haben als mein Hexenmeistergefährte. Ich frage mich, ob er der Aufgabe gewachsen ist, das Monster zu besiegen? Es stünde dem Kriegshäuptling besser zu Gesicht, wenn ich selbst ginge, aber angesichts meiner Verantwortung hier würde ich dem Klan Schande machen, wenn ich meine Pflichten hier vernachlässigen würde, um zur eigenen Ehre gegen das Böse zu kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1485] = { id = 1485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Üble Familiare", description = "Die Hexenmeister, die vor uns kamen, weckten das Misstrauen der Horde. Man toleriert uns zwar, aber man liebt uns nicht.\n\nDas ließ die Hexenmeister freilich nicht näher zusammenrücken, da viele in Abgeschiedenheit leben und ihre Magie allein erforschen. Ich will Euch nicht auf den einen oder anderen Weg führen, sondern nur helfen, reifer zu werden.\n\nBevor ich Euch die Kunst des Beschwörens lehre, bringt mir sechs Köpfe der üblen Familiare aus der Höhle im Nordosten.", sourceObjective = "Bringt 6 Köpfe übler Familiare zu Ruzan.", progress = "Es ist wichtig, dass Ihr die Wesen kontrollieren könnt, die Ihr durch Eure Magie beschwört. Nur wenige interessieren sich für die Lehren der {class}, daher möchte ich Euer Leben nicht gefährden, indem ich Euch etwas lehre, ehe Ihr dazu bereit seid.", completion = "Während Eurer Ausbildung zum {class} werdet Ihr lernen, Wesen vielerlei Arten herbeizurufen. Manchen sieht man es nicht an, aber alle sind nützliche Werkzeuge.\n\nLasst Euch nicht von der geringen Größe eines Wichtels täuschen. Ihr habt zweifellos bemerkt, dass sie dennoch gefährliche Widersacher sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1486] = { id = 1486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deviatbälge", description = "Als Naralex tiefer in seinen Alptraum vorstieß, stieg eine seltsame Schar von Bestien unter dem Brachland in die Höhlen des Wehklagens vor.\n\nDiese Deviatkreaturen haben seltsame, überirdische Eigenschaften. Sie sind zwar von Natur aus böse, doch bin ich der Meinung, dass ihre Existenz hier in Kalimdor auch etwas Gutes haben kann. Ich glaube, ihre Bälge sind besonders gut für die Lederverarbeitung geeignet.\n\nWenn Ihr Euch der Aufgabe gewachsen fühlt, steigt in die Höhlen hinab und holt einige Deviatbälge.", sourceObjective = "Nalpak in den Höhlen des Wehklagens möchte 20 Deviatbälge.", progress = "Ich bin sehr daran interessiert, die Bälge der Deviatkreaturen zu untersuchen, die sich in diesen Höhlen eingenistet haben. Konntet Ihr einige beschaffen, {class}?", completion = "Eure Bemühungen bei der Beschaffung dieser Bälge werden nicht unbemerkt bleiben, {name}.\n\nVielen Dank für Eure Mühe.", sourceObjectiveStatus = "unverified-source-field" }
quests[1487] = { id = 1487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausrottung der Deviat", description = "Naralex hatte ein edles Ziel.\n\nUnser großer Anführer trachtete danach, in den Smaragdgrünen Traum zu gelangen und dabei zu helfen, aus diesem kargen Land wieder den üppigen Wald zu machen, der hier einst wuchs. Aber etwas ist furchtbar schief gegangen.\n\nNaralex' Traum wurde zum Alptraum. Verderbte Kreaturen siedelten sich in den Höhlen an.\n\nWährend einige Jünger von Naralex versuchen, unseren Meister zu wecken, ist es mein Trachten, die Höhlen von diesen bösen Bestien zu befreien.\n\nWagt Euch in die Höhlen, {name}, und löscht die Deviatbrut aus.", sourceObjective = "Ebru in den Höhlen des Wehklagens möchte, dass Ihr 7 Deviatverheerer, 7 Deviatvipern, 7 Deviatschlurfer und 7 Deviatschreckensfange tötet.", completion = "Als Jünger von Naralex bewundere ich Eure Tapferkeit, {name}.\n\nEure Unterstützung bei der Befreiung der Höhlen ist der erste Schritt bei unserer schweren Aufgabe, das Brachland wiederherzustellen.\n\nVielen Dank, und möge Euch Wohlstand gewiss sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1488] = { id = 1488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Verderber", description = "Wiewohl ich nichts über diesen Lord Azrethoc weiß, stimme ich mit Maurin überein, er muss aufgehalten werden. Besonders wenn er versucht, Einfluss über die Brennende Klinge zu bekommen, um seine Ziele voranzutreiben.\n\nIhr habt schon gezeigt, dass Ihr den Kriegshäuptling unterstützen möchtet. Ich verlasse mich darauf, dass Ihr eine Truppe zusammenstellt, die den Dämonenlord und seinen Hexenmeisterdiener besiegt.\n\nWenn Ihr bereit seid, geht direkt nach Süden und kehrt zu mir zurück, wenn die Bedrohung beseitigt wurde.", sourceObjective = "Besiegt Lord Azrethoc und Jugkar Grimm'rod. Kehrt dann zu Takata Stahlklinge in Desolace zurück.", completion = "Ein großer Sieg für uns alle, {name}. Feiern wir unseren Erfolg. Ich gehe jetzt davon aus, dass unsere Zukunft hier nicht so trostlos ist, wie ich einst dachte.\n\nDie Dämonen werden besiegt werden, die Bemühungen der Burning Blade sind zum Scheitern verurteilt und wir haben vielleicht eines Tages einen Ort, den wir eine sichere Heimat nennen dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1489] = { id = 1489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hamuul Runentotem", description = "Die Schalen, die Ihr mir gebracht habt, haben eine Besudelung, eine, die ich nie zuvor gesehen habe. Ich bin mir sicher, dass das Wasser der Oasen der Grund dafür ist. Ich spüre die Verwirrung, die sie über das Land bringen. Es ist, als würde das Land träumen und nicht erwachen können.\n\nDie Höhlen des Wehklagens müssen die Quelle dieser Besudelung sein. Doch ehe Ihr dorthin geht, solltet Ihr mit dem Druidenältesten Hamuul Runentotem sprechen. Ich ließ ihn über die Vorfälle im Brachland informieren. Er ist weise und kann Euch Rat geben.\n\nIhr findet ihn in Donnerfels auf der Anhöhe der Ältesten.", sourceObjective = "Sprecht mit Hamuul Runentotem.", completion = "Ich grüße Euch, {name}. Ihr seid hier willkommen und ich schlage vor, dass Ihr all Eure Kraft zusammennehmt. Denn die Aufgabe, die wir Euch stellen... ist schrecklich.", sourceObjectiveStatus = "unverified-source-field" }
quests[1490] = { id = 1490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nara Wildmähne", description = "Ich betrat das Land der Träume und träumte von einem Druidenkult, der in den Höhlen des Wehklagens haust. Ich sah, dass ihre Ziele einst edel waren, sie jedoch vom rechten Weg abkamen. Sie sind jetzt Diener der Besudelung, die das Brachland befallen hat.\n\nIch bin alt und meine Kraft verlässt mich. Ich konnte nicht lange an diesem Traumort verweilen und weiß wenig mehr von den besudelten Druiden. Aber Nara ist jung und starken Willens. Sie blieb in dem Traum zurück, als ich floh.\n\nSprecht mit Nara. Sie ist in diesem Zelt da drüben.", sourceObjective = "Sprecht mit Nara Wildmähne.", completion = "Ja, es stimmt. Ich weiß von den Druiden in den Höhlen des Wehklagens. Ich habe ihre verzerrten schuppigen Gesichter gesehen. Ich kenne ihre Verbrechen ebenso wie ihre Pläne.\n\nIhr müsst sie aufhalten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1491] = { id = 1491, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klugheitstränke", description = "Nun gut, die Raptorenhörner haben nicht funktioniert. Aber das macht nichts... nicht alles klappt beim ersten Mal! Außerdem habe ich wohl etwas gefunden, das in meinen Klugheitstränken noch besser funktioniert!\n\nEs gibt eine Substanz, die Klageessenz genannt wird. Ich glaube, sie ist die Ursache für die seltsamen Pflanzen und Tiere im Brachland. Bringt mir etwas davon, dann erprobe ich es in meinem Trank!\n\nIch hörte, die Essenz reichert sich in Ektoplasmakreaturen in den Höhlen des Wehklagens im Westen an. Jagt diese Kreaturen und sammelt die Essenz.", sourceObjective = "Sammelt 6 Portionen Klageessenz.", progress = "Wo ist meine Klageessenz?", completion = "Prima, Ihr habt sie! Ich kann es kaum erwarten, sie zu erproben. Das wird mir ein Vermögen einbringen, ich weiß es!\n\nDanke, {name}. Nehmt das. Wenn ich reich bin, schicke ich Euch mehr, versprochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1492] = { id = 1492, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Werftmeister Flunkerblick", description = "Ich muss eine Kiste mit Tränken, Reagenzien und anderen Gegenständen zu meinen Geschäftspartnern in der alten Welt schaffen. Ich habe kaum Zeit, sie selbst zum Dock von Ratschet zu bringen, und die letzte Karawane ist schon aufgebrochen.\n\nKönntet Ihr sie bitte freundlichst zu Werftmeister Flunkerblick bringen? Er wird dafür sorgen, dass sie an Bord des nächsten Schiffes zur Schwarzmeerbucht kommt.", sourceObjective = "Bringt die gesicherte Kiste zu Werftmeister Flunkerblick in Ratschet.", progress = "Ihr wollt mit dem nächsten Schiff fahren oder habt einen Gegenstand, der an Bord gebracht werden soll?", completion = "Eine recht kleine Kiste. Ja, dafür müsste ich noch Platz an Bord des Schiffes finden. Es läuft mit der nächsten Flut aus, das dürfte wohl schnell genug sein. Exzellent. Lasst es mich noch eben in mein Geschäftsbuch eintragen.\n\nAlles erledigt! Guten Tag, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1498] = { id = 1498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Verteidigung", description = "Als Krieger ist eine unserer wichtigsten Aufgaben... der Schutz. Wir sind der Schild der Horde und sorgen für die Sicherheit unserer schwächeren Brüder. Wenn Ihr Euch bei uns einreihen möchtet, müsst Ihr mir Eure Tauglichkeit beweisen.\n\nGeht zum Donnergrat in Durotar, wo die Blitzechsen und Donnerechsen hausen. Jagt die Bestien! Zeigt mir, dass Ihr härter als sie seid! Trotzt ihren Angriffen und bringt mir einen Stapel ihrer versengten Schuppen als Beweis.\n\nGelingt Euch das, unterrichte ich Euch.", sourceObjective = "Bringt 5 versengte Schuppen zu Uzzek bei der Fernwacht im Brachland.", progress = "Habt Ihr die Schuppen, {name}? Wenn Ihr den Angriffen der Donner-Echsen nicht trotzen könnt, könnt Ihr von meiner Unterweisung nicht profitieren.", completion = "Ah. Ich sehe, Ihr habt die Donner-Echsen besiegt, was Eure Zähigkeit beweist. Jetzt zeige ich Euch, wie harte Haut und listige Bewegungen zusammen eine undurchdringliche Verteidigungsmauer bilden können.\n\nPrägt Euch das gut ein, {name}. Und seid bereit für weitere Instruktionen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1499] = { id = 1499, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Üble Familiare", description = "Zureetha hat Novizen wie Euch geschickt, damit sie helfen, die Zahl der Kreaturen in der Höhle einzudämmen, in deren Nähe Ihr gegen die üblen Familiare gekämpft habt.\n\nIch finde, es wäre gut für Euch, wenn Ihr Erfahrung sammelt, indem Ihr ihr helft. Erwähnt unbedingt, dass Ihr mitgeholfen habt, das Wichtel-Problem zu lösen, womöglich hat sie eine Belohnung für Euch.", sourceObjective = "Sprecht mit Zureetha Fernblick.", completion = "Ihr habt Eure Sache gut gemacht, {name}.\n\nDie abscheulichen Familiare waren zwar nur Schoßtierchen der dunkleren Mächte bei den Burning Blade, doch Euer Erfolg gegen sie lässt kommende Großtaten ahnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1500] = { id = 1500, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erweckung von Naralex" }
quests[1501] = { id = 1501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kreatur der Leere", description = "So wenige Hexenmeister sind übrig... Wir riskieren viel, doch die Risiken sind gerechtfertigt. Ihr müsst bald Reife in Eurer Fähigkeit erlangen, wenn Ihr der Horde und dem Kriegshäuptling nützlich sein wollt.\n\nEs ist Zeit, dass Ihr einen neuen Beschwörungszauber lernt.\n\nAls Erstes müsst Ihr die Schrifttafel der Verga wiederbeschaffen, die von Hexenmeistern der Brennenden Klinge gestohlen wurde und nun in ihrem Unterschlupf in der Knochenhöhle verwahrt wird. Mit der Tafel zeige ich Euch die Runen, mit denen ein Leerwandler beschworen wird.", sourceObjective = "Holt die Schrifttafel der Verga für Gan'rul Blutauge in Orgrimmar.", progress = "Habt Ihr die Schrifttafel der Verga, {name}? Ich wünsche erst wieder mit Euch zu sprechen, wenn Ihr sie habt.", completion = "Gut. Ich hoffe, Ihr habt den Burning Blade weitere Verluste zugefügt, als Ihr dies beschafft habt.\n\nSie sind dem Kriegshäuptling ein Dorn im Auge und eine echte Pest für die {class} im Allgemeinen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1502] = { id = 1502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thun'grim Brandblick", description = "Es ist wichtig, dass ein Krieger eine hochwertige Waffe hat. Und wenn es einen Orc gibt, der hochwertige Waffen herstellen kann, dann ist das Thun'grim Brandblick. Er ist ein Einsiedler, der auf den Hügeln östlich des Wegekreuzes haust.\n\nWenn Ihr eine Waffe sucht, Krieger, dann solltet Ihr Euch an Thun'grim wenden. Um ihn zu finden reist Ihr zuerst zum Wegekreuz im Westen und wendet Euch dann nach Osten in die Berge. Sein Lager liegt hoch auf einem Berggipfel.", sourceObjective = "Sprecht mit Thun'grim Brandblick im Brachland.", completion = "Meine Augen sind schon lange ausgetrocknet, weil ich ins Feuer der Schmiede schaute, aber manches kann ich noch sehen. Ich kann sehen, dass Ihr etwas wollt.\n\nUnd da Ihr den Weg hierher gefunden habt, kann ich mir denken, was Ihr begehrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1503] = { id = 1503, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschmiedeter Stahl", description = "Ich gebe Euch eine Waffe, {name}, doch vorher müsst Ihr mir helfen. Vor einigen Nächten kamen die Klingenmähnen von Nordwesten in mein Lager. Sie wollten nicht mit mir kämpfen, wissen aber, wie schlecht es um mein Augenlicht bestellt ist. Einige lenkten mich durch Schnauben ab, während die anderen mich bestahlen. Diese Feiglinge!\n\nSie nahmen eine Eisentruhe mit, in der sich Schmiedestahlbarren befanden. Wenn Ihr sie wiederbeschaffen könnt, bekommt Ihr die Waffe, die Ihr sucht.\n\nSucht im Stacheleberlager nach der Eisentruhe und bringt die Schmiedestahlbarren zurück.", sourceObjective = "Bringt die Schmiedestahlbarren zu Thun'grim Brandblick im Brachland.", progress = "Habt Ihr meine Stahlbarren?", completion = "Ihr habt sie gefunden! Und alle Stangen sind da, was mich nicht überrascht. Ich glaube nicht, dass die Grimmhauer wussten, was sie mit diesem edlen Stahl anfangen sollten.\n\nDanke, {name}. Hier ist Eure Belohnung. Möge sie Euch nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1504] = { id = 1504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Nun studiert die Schrifttafel der Verga, denn sie enthält die Glyphen, die Ihr für die Beschwörung braucht. Bringt sie zu dem Kreis in Neeru Feuerklinges Zelt auf der anderen Seite der Höhle. Dort könnt Ihr den Leerwandler herbeirufen.\n\nIhr müsst ihn mit allen körperlichen und magischen Mitteln besiegen, die Euch zur Verfügung stehen. Wenn das vollendet ist, kommt mit den Glyphen der Beschwörung zu mir zurück und ich führe Euch vor, wie Ihr die Kreatur an Euren Willen bindet.", sourceObjective = "Beschwört mithilfe der Glyphen der Beschwörung einen Leerwandler, unterwerft ihn und bringt dann die Glyphen der Beschwörung zu Gan'rul Blutauge in Orgrimmar zurück.", progress = "Der Leerwandler ist eine mächtige Kreatur. Ich weiß noch, wie ich an Eurer Stelle war, {name}. Nach diesen vielen Jahren bekämpft mich mein eigener Leerwandler inzwischen etwas weniger stark, aber vermutlich nur, weil er darauf hofft, dass meine Wachsamkeit dann nachlässt.\n\nVergesst das nicht, {name}.", completion = "Ihr habt Eure Sache gut gemacht, {name}. Ich werde Euch zeigen, wie man einen Leerwandler beschwört, der dem, den Ihr gerade besiegt habt, sehr ähnlich ist.\n\nIhr solltet wissen, dass wir große Erwartungen in Euch setzen, und bisher habt Ihr sie auch erfüllt.\n\nAber dass Euch das nicht zu Kopf steigt, denn verglichen mit den Aufgaben, die noch vor Euch liegen, war dies hier ein Kinderspiel.", sourceObjectiveStatus = "unverified-source-field" }
quests[1505] = { id = 1505, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran Uzzek", description = "Die Horde ehrt ihre Krieger, da ihre Kraft außer Frage steht. Doch die wahrhaft großen Helden sind auch große Schüler.\n\nSucht nach Uzzek. Er ist ein Veteran zahlreicher Kämpfe und unterrichtet jetzt junge Krieger in der Gefechtskunst. Ihr findet ihn südlich der Fernwacht, der Orcgarnison an der Grenze von Brachland und Durotar.", sourceObjective = "Sprecht mit Uzzek bei der Fernwacht.", completion = "Hallo, Jüngelchen. Seid Ihr zur Ausbildung hier, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[1506] = { id = 1506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gan'ruls Beschwörung", description = "Ihr da. {name}, richtig?\n\nIch hoffe, Ihr seid nicht zu sehr beschäftigt, denn Gan'rul möchte Euch unverzüglich sprechen. Ihr findet ihn mit den Hexenmeisterältesten in der Kluft der Schatten.\n\nMeinen früheren Erfahrungen mit Gan'rul nach zu urteilen, bedeutet Eure Einbestellung entweder etwas sehr Gutes oder etwas sehr Schlechtes.", sourceObjective = "Sprecht mit Gan'rul Blutauge in Orgrimmar.", completion = "Gut. Ich hatte befürchtet, Ophek würde Euch nicht erreichen.\n\nEs ist Zeit, dass ich Eure Hexenmeisterausbildung fortsetze. Eure aktuellen Angelegenheiten müssen warten.\n\nIch gehe davon aus, dass das kein Problem sein wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[1507] = { id = 1507, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlinger der Seelen", description = "Eure Zeit ist gekommen, mehr über die Beschwörungsmagien zu lernen. Ihr werdet lernen, einen Sayaad zu beschwören, eine Kreatur mit unglaublichen geistigen Mächten. Er kann sich schwache Geister zu Diensten machen... doch seid unbesorgt! Ich bin sicher, Ihr seid der Herausforderung gewachsen.\n\nEin Sayaad kann nur beschworen werden, wenn man ihn mit einem Gegenstand ködert, der große Hingabe und Liebe bedeutet. Ich überlasse es Euch, so ein Objekt zu finden.\n\nEin Vorschlag? Sprecht mit Cazul... Es scheint wenig zu geben, das der alte Hexenmeister nicht weiß.", sourceObjective = "Sprecht mit Cazul in der Kluft der Schatten.", completion = "Hm... {name}. Ihr seid noch neu auf Eurem Weg, doch ich spüre das Potenzial für Größe in Euch.\n\nIhr wurdet mit Gaben geboren, {name}. Sorgt dafür, dass Ihr sie nicht vergeudet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1508] = { id = 1508, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der blinde Cazul", description = "Wenn Gan'rul Euch zu mir geschickt hat, dann gewiss, weil Ihr einen Sukkubus, also einen weiblichen Sayaad, beschwören sollt und einen Gegenstand braucht, um ihn anzulocken.\n\nHmm... Wenn Ihr Euch von einem Blinden führen lassen möchtet, {name}, dann hört zu. In den Hängen von Orgrimmar, westlich des Himmelsturms im Tal der Stärke, lebt Zankaja. Sie wartet darauf, dass ihr Lebensgefährte zurückkehrt.\n\nGeht zu ihr.", sourceObjective = "Sprecht mit Zankaja in Orgrimmar.", completion = "Seid Ihr mit Neuigkeiten von Dogran gekommen? Er sollte vor Tagen zurück sein und ich habe kein Wort gehört...", sourceObjectiveStatus = "unverified-source-field" }
quests[1509] = { id = 1509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten von Dogran", description = "Dogran, mein Gefährte, wurde jüngst zum Dienst am Wegekreuz abkommandiert. Es war eine Beförderung und er war sehr stolz.\n\nIch war natürlich traurig, ließ es ihn aber nicht wissen. Und auch besorgt. Das Brachland ist gefährlicher als Orgrimmar, daher fürchtete ich das Schlimmste.\n\nSeit einer Woche sollte er nun schon zu Hause sein und ich habe kein Wort von ihm gehört...\n\nVielleicht könntet Ihr zum Wegekreuz gehen und nachfragen, ob es Neuigkeiten gibt? Er arbeitete mit Gazrog, der noch dort stationiert sein sollte.", sourceObjective = "Sprecht mit Gazrog beim Wegekreuz.", completion = "Zankaja? Das ist Dograns Gefährtin, nicht?\n\nJa, ich habe von ihm gehört, aber keine Neuigkeiten, die Ihr ihr überbringen solltet...\n\nNein, er ist nicht tot. Aber er ist verletzt und Gefangener der Stacheleber.", sourceObjectiveStatus = "unverified-source-field" }
quests[1510] = { id = 1510, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuigkeiten von Dogran", description = "Er war im Camp Taurajo stationiert, wo wir versuchten, die Stacheleber auszurotten. Er führte ein paar Grunzer zu einem ihrer Lager, wo er schwer verwundet wurde. Die anderen schafften es zurück und versuchten, ihn zu retten. Er war in einem schlimmen Zustand, seine Wunden eiterten, daher wollten sie ihn nicht mitnehmen, ohne ihn erst zu versorgen.\n\nSie schickten eine Nachricht hierher und baten um ein Heilgebräu von den Trollen der Malaka'jin im Steinkrallengebirge. Wir schickten Leute, um eines zu holen, aber diese sind noch nicht zurückgekehrt.", sourceObjective = "Sprecht mit Ken'zigla am Malaka'jin.", completion = "Ein {race}, hm? Ich hoffe, Ihr seid nicht wegen ihm gekommen. Er hat es nicht geschafft. Diese Goblins haben ihn alle gemacht.\n\nEr sagte nur, er bräuchte ein Heilgebräu, sonst nichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[1511] = { id = 1511, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ken'ziglas Trunk", description = "Ich dachte mir, dass ein anderer kommen würde, um den Trunk zu holen, daher habe ich ihn dennoch vorbereitet.\n\nDa habt Ihr ihn, {name}. Aber denkt daran, Ihr solltet ihm nur die Hälfte geben! Dadurch bekommt er genug Kraft, sich zu bewegen, ohne dass er verblutet. Wartet eine Nacht und gebt ihm dann die andere Hälfte.\n\nWie auch immer, Ihr solltet dies zu Logmar im Camp Taurajo bringen. Nach allem, was er mir gesagt hat, sollte er wissen, wo dieser Dogran ist.", sourceObjective = "Bringt Ken'ziglas Trunk zu Grunzer Logmar im Camp Taurajo.", progress = "Ja, was gibt's?", completion = "Das wurde auch Zeit! Dogran wäre fast gestorben, während er darauf wartete.\n\nWir müssen den Trunk sofort zu ihm bringen, aber die meisten Grunzer, die hier stationiert sind, befinden sich auf Nahrungssuche.", sourceObjectiveStatus = "unverified-source-field" }
quests[1512] = { id = 1512, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Liebesgabe", description = "Zankaja ist jung und wunderschön. An einen Invaliden gekettet zu sein... Ich dulde nicht, dass ihr diese Ungerechtigkeit widerfährt.\n\nLasst mich allein, {name}. Und habt Dank. Vielleicht beende ich mein Leben im ruhmreichen Kampf statt als leblose Hülle.\n\nUnd bitte erzählt meiner Gefährtin nichts davon... Ich möchte nicht, dass sie sich Schuld auflädt.", sourceObjective = "Bringt den schmutzverkrusteten Anhänger zu Gan'rul Blutauge in Orgrimmar.", progress = "Ihr seid zurückgekehrt. Seid Ihr bereit, gegen einen Sukkubus zu kämpfen?", completion = "Wenn Ihr mir sagt, dass dies genügt, dann vertraue ich Euch, {name}. Aber erlaubt mir, ihn zu reinigen... Sauber und glänzend dürfte er für einen Sukkubus noch verlockender sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1513] = { id = 1513, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Bringt dies zum Beschwörungskreis in Neerus Zelt, {name}. Beschwört einen schändlichen Sukkubus und zeigt ihm Eure Überlegenheit. Ich glaube an die Kraft Eurer Magie. Aber seid wie stets wachsam, denn Stolz und Selbstüberschätzung wurden manchem viel versprechenden Hexenmeister zum Verhängnis.\n\nWenn Ihr ihn besiegt habt, bringt den Anhänger zu mir, damit ich Zankaja die Neuigkeit überbringen kann.", sourceObjective = "Beschwört mithilfe von Dograns Anhänger einen Sukkubus, unterwerft ihn und bringt dann Dograns Anhänger zu Gan'rul Blutauge in Orgrimmar zurück.", progress = "Wenn ich einen Sukkubus ansehe, geht mir das Herz auf... Aber zugleich kann ich fast meiner Seele Niedergeschlagenheit spüren, die wie die Gezeiten abfließt.\n\nSeid wachsam.", completion = "Erfolg! Seid versichert, dass ich von meinem Musterschüler nichts anderes erwartet habe.\n\nIhr habt Euch als würdig erwiesen, daher zeige ich Euch mit Freuden die Methode, wie Ihr Euren unterworfenen Sukkubus beschwört. Geht jetzt, Ihr habt viel zu lernen. Wenn ich Euch das nächste Mal sehe, erwarte ich, dass Ihr wahre Meisterschaft über Euren Sukkubus erlangt habt.\n\nÜberlasst die Trauer um Dogran und Zankaja denen unter uns, die älter an Jahren sind, aber vergesst sie nicht und bewahrt sie als Schutz gegen die Launen der dunklen Macht, die Ihr heute zu beschwören gelernt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1514] = { id = 1514, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbte Windblüte", progress = "Ihr habt eine kränkliche, verderbte Ausgabe von etwas gefunden, das wie eine Windblütenpflanze aussieht. Die Beeren, die von der Pflanze herabhängen, sehen verfault und giftig aus. Es muss sich dringend jemand um die Pflanze kümmern, wenn sie wieder zu ihrem Normalzustand zurückkehren soll.", completion = "Ihr wendet zwei cenarische Pflanzensalben auf die Windblüte an. Sofort beginnt sie sich zu verwandeln. Sie blüht auf und wird zu einer vor Leben sprühenden und gesunden Pflanze." }
quests[1515] = { id = 1515, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dograns Gefangenschaft", description = "Ihr habt es bis hierher geschafft, wenn Ihr es bis zu Ende durchstehen möchtet, werde ich Euch nicht aufhalten. Aber ich kann keine Leute erübrigen, Ihr seid also auf Euch allein gestellt.\n\nDogran wird in einem Lager der Stacheleber nördlich von hier festgehalten. Sucht nach zwei nebeneinander stehenden Hütten. Er wird schwer bewacht... Das heißt, wenn sie ihn noch nicht getötet haben oder er seinen Verletzungen erlegen ist.\n\nViel Glück.", sourceObjective = "Bringt Ken'ziglas Trunk zu Dogran im Brachland.", completion = "Ein übel schmeckendes Gebräu...\n\nDoch ich spüre genügend Kraft in mir, um wegzuhinken... Aber auf mein Bein werde ich den Rest meines Lebens verzichten müssen. Und auf meinen Arm auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[1516] = { id = 1516, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Die Zeit ist gekommen, <junger/junge:c> {class}. Ihr seid stark geworden und Euer Geist ist ausdauernd wie die Erde. Dass Ihr dem Pfad des Schamanen folgt, zeigt, dass Ihr Weisheit besitzt, sogar bevor Ihr Euch selbst beweist.\n\nDas Element der Erde wird über Euer Schicksal wachen und Teil von Euch werden, wenn Ihr bereit seid. Doch Ihr müsst vor der Erde selbst bestehen. Wenn Ihr bereit seid, werdet Ihr Dinge sehen, von denen nur Schamanen wissen.\n\nSucht die Teufelspirscher im Norden und beschafft Euch zwei ihrer Hufe. Kehrt dann zu mir zurück und wir sprechen weiter über Eure Zukunft.", sourceObjective = "Bringt 2 Teufelspirscherhufe zu Canaga Erdenrufer im Tal der Prüfungen.", progress = "Geduld ist der Erde größte Tugend. Die Erde sieht den Zyklus aller Dinge: die Berge werden zu Wüsten, Flüsse werden zu Schluchten. Die Erde ist das störrischste und weiseste aller Elemente, sie toleriert keine Ungeduld.\n\nDie Erde ruft Euch nun, denn eine Zeit der Konflikte rückt näher. Wenn Ihr erfolgreich zu mir zurückkehrt, werdet Ihr dem Ziel, ganzheitlich zu werden, sehr viel näher sein.\n\nAndere werden Euch Eure Weisheit neiden und Euch ihrer Unwissenheit wegen hassen.", completion = "Exzellent. Euer Erfolg zeigt, dass Ihr vorbereitet seid.\n\nVon allen Elementen repräsentiert die Erde das Fundament aller Dinge. Sie ist Eure Kraft, Eure Ausdauer und Eure Geduld. Die Erde wird Euch schützen, aber nur, wenn Ihr angemessenen Respekt zeigt. Die Erde kann, wie alle anderen Elemente auch, kleinmütig sein. Die Erde ist die Grundlage des Lebens und wenn Ihr ihre Gesetze achtet, wird Euch größere Weisheit zuteil. Vergesst niemals die Geheimnisse, die die Erde mit Euch teilt.\n\nIch werde jetzt ein Sapta für Euch machen. Wenn Ihr es akzeptiert, werdet Ihr Euren Weg erkennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1517] = { id = 1517, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Ein Sapta ist ein Getränk, mit dem unsere Seelen an die Elemente gebunden werden. Mit Magie gestärkt lässt dieser Trank die Willensstarken die Elemente sehen, wie es sonst niemand kann. Euer Geist wird mit dem Element verbunden, für das das Sapta geschaffen wurde. Nur wenige auserwählte Schamanen kennen das Rezept.\n\nDas Sapta wird stets an einem heiligen Ort getrunken, niemals anderswo...vergesst das nicht.\n\nBesucht den Geisterfelsen südwestlich von hier...er befindet sich am Ende des Verborgenen Pfades. Trinkt Euer Sapta dort und...tja, Ihr werdet schon sehen.", sourceObjective = "Sucht den Geisterfelsen und trinkt das Erdsapta.\n\nBereitgestellter Gegenstand:", completion = "Ah... {name}... die Erde ist erfreut, Euch hier zu sehen.\n\nAn Körper und Geist verbunden werdet Ihr vorwärts schreiten, wissend, dass die Berge Eure Kraft sind, die Ebenen Eure Geduld; die Welt selbst Eure Essenz.\n\nEs ist nur erforderlich, dass Ihr demütig vor der Erde steht, um dieses Ritual zu bestehen. Aber die anderen sind nicht so passiv. Sie können chaotisch und häufig brutal sein, doch das liegt in der Natur der Elemente. Duale Naturen widerstreben einander, diese Dinge müsst Ihr gründlich lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1518] = { id = 1518, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Nehmt diesen Rohquarz von mir und bringt ihn als Beweis für unsere Begegnung zu Canaga Erdenrufer. Er wird ein Totem für Euch anfertigen, dessen Herzstück dieser Kiesel sein soll. So winzig er scheinen mag, Ihr werdet feststellen, dass es nicht auf die Größe ankommt und selbst die kleinsten Dinge viele anderen überdauern können.\n\nHabt Geduld, {name}. Bleibt stark und sucht Weisheit. Dies verlangt die Erde von Euch. Am Ende solltet Ihr eins mit der Erde werden... respektiert sie so, wie sie Euch respektiert.", sourceObjective = "Bringt den Rohquarz zu Canaga Erdenrufer im Tal der Prüfungen.", progress = "Ich möchte der Erste sein, der Euch auf dem ersten der vier Pfade begrüßt, die Euch für immer Eurem Schicksal zuführen werden.\n\nWenn Ihr den Stein besitzt, den Euch die Erde gab, werde ich Euch das versprochene Totem geben.\n\nWenn nicht, hebt Euch hinfort, bis Ihr Euren Weg gefunden habt.", completion = "Exzellent!\n\nDas Totem, das ich für Euch anfertigen werde, ist mehr als nur ein Symbol für Euren Status unter den Schamanen... es besitzt Fähigkeiten, die darüber hinausgehen. Ein Nutzen des Totems ist, dass es als Fokus für Zauber dient. Diese Zauber sind mit der Erde verbunden. Je mehr Weisheit Ihr erlangt, desto mehr Fähigkeiten der Erde werden Euch zugänglich sein.\n\nDie Lehrer werden wissen, wann Ihr für größeres Wissen bereit seid.\n\nNehmt vorerst dieses Erdtotem...", sourceObjectiveStatus = "unverified-source-field" }
quests[1519] = { id = 1519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Die Zeit ist gekommen, {class}. Euer Körper ist ausgereift und stark geworden und Euer Geist ist ausdauernd wie die Erde. Ich sehe es Euch an... Ihr besitzt bereits Weisheit.\n\nDie Erde leitet unser Volk und spricht zu uns... und bald auch zu Euch. Aber Ihr müsst geprüft werden. Wenn Ihr bereit seid, werdet Ihr Dinge sehen, von denen nur unsere Art weiß.\n\nSucht die Schamanen der Borstennacken in ihrer Klamm im Osten auf und beschafft Euch eine ihrer Salben, die sie für ihre Rituale verwenden. Kehrt erst zu mir zurück, wenn Ihr genügend davon für Euren eigenen Trank habt.", sourceObjective = "Bringt 2 Dosen Ritualsalbe zu Seherin Rabenfeder im Camp Narache.", progress = "Die Erde ist geduldig und wird auf Euch warten, bis Ihr bereit seid, denn sie weiß, mit der Zeit schwinden alle Dinge und werden wiedergeboren. Das ist der Zyklus des Lebens. Berge werden zu Wüsten. Flüsse werden zu Schluchten. Die Erde ist das störrischste und weiseste aller Elemente.\n\nIhr müsst vor allem Geduld und Ausdauer lernen. Die Erde ruft Euch nun, denn sie spürt, dass Ihr bereit seid. Betrachtet dies als Eure Wiedergeburt, wenn Ihr erfolgreich seid. Hinterher werdet Ihr niemals wieder zur Unwissenheit zurückkehren können.", completion = "Gut, {name}. Eure Rückkehr hierher zeigt, dass Ihr wahrlich für den nächsten Schritt bereit seid.\n\nVon allen Elementen repräsentiert die Erde das Fundament aller Dinge. Sie ist Eure Kraft, Eure Ausdauer und Eure Geduld. Die Erdenmutter wird Euch schützen, aber nur, wenn Ihr ihr den angemessenen Respekt erweist. Sie ist die Grundlage des Lebens und wenn Ihr ihre Gesetze achtet, wird Euch größeres Wissen zuteil. Vergesst niemals die Geheimnisse, die sie mit Euch teilt.\n\nIch werde jetzt Euer Sapta für Euch machen. Wenn Ihr es akzeptiert, wird sich ein neuer Weg vor Euch auftun.", sourceObjectiveStatus = "unverified-source-field" }
quests[1520] = { id = 1520, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Ein Sapta ist ein Getränk, mit dem unsere Seelen an die Elemente gebunden werden. Mit Magie gestärkt lässt dieses Elixier die, die offenen Geistes sind, die Elemente sehen, wie sie zuvor noch von niemandem gesehen wurden. Euer Geist wird ewig an das Element gebunden, für das das Sapta geschaffen wurde. Nur wenige Auserwählte unserer Art kennen das Geheimnis seiner Herstellung.\n\nDas Sapta wird stets an einem heiligen Ort getrunken und niemals anderswo.\n\nSucht den Schamanenschrein östlich von hier und trinkt von dem Sapta.", sourceObjective = "Sucht den Kodofels und trinkt das Erdsapta.\n\nBereitgestellter Gegenstand:", completion = "Ah... {name}... die Erde ist erfreut, Euch hier zu sehen.\n\nAn Körper und Geist verbunden werdet Ihr vorwärts schreiten, wissend, dass die Berge Eure Kraft sind, die Ebenen Eure Geduld; die Welt selbst Eure Essenz.\n\nEs ist nur erforderlich, dass Ihr demütig vor der Erde steht, um dieses Ritual zu bestehen. Aber die anderen sind nicht so passiv. Sie können chaotisch und häufig brutal sein, doch das liegt in der Natur der Elemente. Duale Naturen widerstreben einander, diese Dinge müsst Ihr gründlich lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1521] = { id = 1521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Erde", description = "Nehmt diesen Rohquarz von mir und bringt ihn als Beweis für unsere Begegnung zu Seherin Rabenfeder. Sie wird ein Totem für Euch anfertigen, dessen Herzstück dieser Kiesel sein soll. So winzig er scheinen mag, Ihr werdet feststellen, dass es nicht auf die Größe ankommt und selbst die kleinsten Dinge Berge überdauern können.\n\nHabt Geduld, {name}. Bleibt stark und sucht Weisheit. Dies verlangt die Erde von Euch. Am Ende solltet Ihr eins mit der Erde werden... respektiert sie so, wie sie Euch respektiert.", sourceObjective = "Bringt den Rohquarz zu Seherin Rabenfeder im Camp Narache.", progress = "Seid gegrüßt, {name}. Ihr würdet nicht zu mir zurückkehren, wenn Ihr Eure Aufgabe nicht bewerkstelligt hättet. Ich möchte der Erste sein, der Euch auf dem ersten der vier Pfade begrüßt, die für immer Eure Reise beherrschen werden.\n\nWenn Ihr den Stein besitzt, den Euch die Erde gab, werde ich Euch das versprochene Totem geben. Wenn nicht, bedauere ich Euch. Mit großem Stolz erfüllt es den, der sich voll und ganz den Elementen verschrieben hat.", completion = "Großartig.\n\nDas Totem, das ich für Euch anfertigen werde, ist mehr als nur ein Symbol... es besitzt Fähigkeiten, die darüber hinausgehen. Ein Nutzen des Totems ist, dass es als Fokus für Zauber dient. Diese Zauber sind mit der Erde verbunden. Je mehr Weisheit Ihr erlangt, desto mehr Fähigkeiten der Erde werden Euch zugänglich sein. Die Lehrer in ganz Kalimdor werden wissen, wann Ihr für größeres Wissen bereit seid und es Euch sagen, wenn Ihr sie besucht.\n\nNehmt vorerst dieses Erdtotem...", sourceObjectiveStatus = "unverified-source-field" }
quests[1522] = { id = 1522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Feuer sei mit Euch, Mann. Ich sehe, Ihr seid schon bewandert in den Wegen der Erde und scheint mir bereit, mit Kranal zu sprechen.\n\nKranal lebt nördlich des Wegekreuzes im Brachland. Er kennt sich mit den Elementen aus und kann Euch was übers Feuer beibringen...wenn Ihr denkt, dass Ihr bereit seid.\n\nEr ist leicht zu finden, geht nur nicht zu weit. Wenn Ihr zu weit geht, seid Ihr plötzlich im Elfenland.", sourceObjective = "Sucht Kranal Fiss im Brachland.", completion = "Hmmm, hat Searn Euch geschickt, ja?\n\nAlso Searn kann man immer vertrauen. Er scheint überzeugt, dass Ihr bereit seid, Euer nächstes Sapta zu nehmen, das Feuersapta.\n\nIch sehe es schon in Euren Augen, das Lodern, das Verlangen. Ihr habt von der Macht gekostet und seid jetzt bereit für mehr. Geduld, {name}. Vergesst nicht, was Euch die Erde lehrte. Macht und Zerstörung werden sicherlich kommen, doch Ihr müsst dennoch wissen, wann Ihr Euch zurückhalten solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1523] = { id = 1523, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, {name}. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über Zerstörung zu lernen... und über Chaos. Ihr könnt das Element des Feuers verstehen lernen, wenn Ihr bereit seid, dafür zu bezahlen.\n\nSucht nach Kranal Fiss im Brachland. Er lebt in einer kleinen Siedlung nördlich des Wegekreuzes, aber gebt Acht, wenn Ihr das Land der Nachtelfen erreicht, seid Ihr zu weit gegangen.", sourceObjective = "Sucht Kranal Fiss im Brachland.", completion = "Hmmm, hat Xanis Euch geschickt, ja?\n\nAlso Xanis kann man immer vertrauen. Er scheint überzeugt, dass Ihr bereit seid, Euer nächstes Sapta zu nehmen, das Feuersapta.\n\nIch sehe es schon in Euren Augen, das Lodern, das Verlangen. Ihr habt von der Macht gekostet und seid jetzt bereit für mehr. Geduld, {name}. Vergesst nicht, was Euch die Erde lehrte. Macht und Zerstörung werden sicherlich kommen, doch Ihr müsst dennoch wissen, wann Ihr Euch zurückhalten solltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1524] = { id = 1524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Ihr seid mächtig genug, das Totem des Feuers zu tragen, doch bedeutet das nicht, dass Ihr bereit seid.\n\nAm Südstromfluss in Durotar, vor dem Großen Meer, liegt ein verborgener Pfad zu einem der höchsten Gipfel des Landes. Sucht einen Weg nach oben. Dann werdet Ihr einen unserer heiligen Schreine finden, den Telf Joolam bewacht... den Schrein der Schlafenden Flamme.\n\nBringt ihm diese Fackel... sie zeigt, dass Ihr versucht, das Feuer zu bändigen. Bringt sie mir zurück, wenn Ihr sie an der Kohlenpfanne des Schreins entzündet habt, und ich sorge dafür, dass Ihr das Totem des Feuers bekommt.", sourceObjective = "Bringt die Fackel der schlafenden Flamme zu Telf Joolam in Durotar.", progress = "Seid gegrüßt, {name}. Ihr befindet Euch am Schrein der schlafenden Flamme. Nur jene, die wahrlich in den schamanistischen Künsten bewandert sind, werden je die Geheimnisse dieses Ortes und der Macht kennen lernen, die er birgt. Tut mir Leid, dass Ihr den weiten Weg auf Euch genommen habt, nur um jetzt abgewiesen zu werden - die Reise hierher ist alles andere als sicher -, aber ich bin der Bewahrer des Schreins und kann nicht jeden hier umherstreifen lassen.", completion = "Ah, mein Fehler, {name}. Ich muss mich entschuldigen. Mir war nicht klar, dass Ihr die Fackel besitzt. Es freut mich, Eure Bekanntschaft zu machen.\n\nViele Abenteurer finden auf der Suche nach verlorenen Schätzen oder der Jagd auf mystische Kreaturen hierher und werden von einem scheinbar leeren Schrein abgewiesen. Aber wir kennen die Wahrheit, nicht, {name}?\n\nDieser Schrein verbirgt ein größeres Geheimnis vor den einfachen Mitgliedern der Horde. Für uns ist er heilig.", sourceObjectiveStatus = "unverified-source-field" }
quests[1525] = { id = 1525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Aber Ihr seid doch nicht zum Geschichtsunterricht hergekommen, oder? Ihr seid wegen der ewigen Flamme und einem Feuertotem gekommen.\n\nZunächst einmal müsst Ihr ein Sapta anfertigen und Euch selbst an das Feuer binden.\n\nIch kann das Feuersapta für Euch herstellen, wenn Ihr mir zwei Gegenstände bringt. Der Erste ist Feuerteer, ein einfacher Gegenstand, den normalerweise die Zauberer der Klingenmähnen im östlichen Brachland mit sich führen.\n\nDer zweite Gegenstand dürfte gefährlicher zu bekommen sein: ein Reagenzienbeutel von einem Kultisten der Brennenden Klinge. Ihr findet sie in einer Höhle über den Klammen nordöstlich von Klingenhügel.", sourceObjective = "Bringt 1 Feuerteerstück und 1 Reagenzienbeutel zu Telf Joolam in Durotar.", progress = "Ich habe genügend Zutaten für ein Feuersapta, wenn Ihr den Reagenzienbeutel und etwas Feuerteer finden könnt. Die Fanatiker der Burning Blade tragen die richtigen Komponenten für die meisten ihrer Zauber in diesen Beuteln und haben meist ausreichend von den Gegenständen, die ich benötige, damit Ihr nicht weiter nach etwas anderem suchen müsst.\n\nDie Saptas werden stets aus Zutaten hergestellt, die in enger Verbindung zu ihrem jeweiligen Element stehen. Es macht unsere Arbeit leichter, da die Hexenmeister mit dem Feuer verbunden sind.", completion = "Diese werden genügen, {name}.\n\nFeuer ist mehr als Chaos und Zerstörung... Ihr tut gut daran, das nicht zu vergessen. Es dreht sich auch um Leben und Schöpfung. Alle Dinge sind auf diese Weise miteinander verbunden. Kräfte sind einander entgegengesetzt, doch zugleich kann die eine nicht ohne die andere existieren. Beide löschen sich gegenseitig aus, geben einander aber auch erst einen Sinn. Vergesst das niemals.\n\nUnterschiedliche Arten der Magie in Verbindung miteinander zu verwenden, zeigt nicht nur wahre Fertigkeit, sondern große Weisheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[1526] = { id = 1526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Das Feuersapta ist fertig. Die Zeit ist gekommen, dass Ihr Euch der Flamme stellt. Benutzt das Sapta am Schrein und geht zum Berggipfel, um Euch dort der Manifestation zu stellen. Er wird Euch erst angreifen, wenn Ihr bereit seid, wird aber wissen, dass Ihr ihn sehen könnt.\n\nSchlagt ihn schnellstens nieder, {name}, denn seine Macht wächst, je länger Ihr braucht, um ihn zu besiegen. Wenn er bezwungen wurde, legt seine Glut in die Kohlenpfanne und entzündet die Fackel.", sourceObjective = "Besiegt die schwache Feuermanifestation und legt Glut in die Kohlenpfanne auf dem Schrein der ewigen Flamme.", progress = "Die Kohlenpfanne hat etwa ein Drittel Eurer Höhe und sieht normal aus, abgesehen von den Inschriften auf ihrem glatten Metallrand. Das Metall scheint nicht vom Wetter angegriffen zu sein und die Schale, die darauf ruht, fühlt sich kalt an.", completion = "Eine weiß glühende Flamme lodert in der Schale auf, als Ihr die Glut hineinlegt. Ihr könnt spüren, wie die magischen Effekte des Sapta durch Euren Körper strömen und das Feuer rhythmisch vor Euch tanzt.\n\nIhr haltet das Ende der Fackel in die Pfanne und sie fängt sofort Feuer.", sourceObjectiveStatus = "unverified-source-field" }
quests[1527] = { id = 1527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Feuers", description = "Mit der Fackel fest in der Hand wendet Ihr Euch von der Kohlenpfanne ab und lasst den Blick über Durotar schweifen. Ihr spürt, wie Aufregung Euren Geist erfüllt, als der Wind anschwillt und die Flamme heftig flackern lässt.\n\nAuf der Suche nach Kranal Fiss betretet Ihr den Pfad zurück ins Brachland.", sourceObjective = "Bringt die Fackel der ewigen Flamme zu Kranal Fiss im Brachland.", progress = "Ja, {name}? Was habt Ihr da?", completion = "Euer Geist brennt heller als jede Fackel, die ich je gesehen habe, {name}, und darauf solltet Ihr stolz sein.\n\nWenn Ihr diesem Weg weiter folgt, werdet Ihr über die Elemente gebieten und unsere Brüder werden Führung und Weisheit bei Euch suchen. Lasst mich der Erste sein, der Euch gratuliert und Euch Euer neuestes Totem überreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1528] = { id = 1528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Wasser sei in Eurer Zukunft, Mann. Ich sehe, Ihr seid schon bewandert in den Wegen des Feuers und scheint mir bereit, mit Islen zu sprechen.\n\nIslen lebt an der Küste des Brachlandes. Wenn Ihr am Ufer des Südstroms nach Süden geht, könnt Ihr sie gar nicht verfehlen...achtet auf den großen Hai! Sie kennt sich mit den Elementen aus und kann Euch etwas übers Wasser beibringen...wenn Ihr denkt, dass Ihr bereit seid.\n\nSie ist leicht zu finden, geht nur nicht zu weit nach Süden...sie ist gleich hinter Ratschet.", sourceObjective = "Sucht Islen Wasserdeuter im Brachland.", completion = "Der Wind weht heftig vom Horizont her, die Erde unter Euren Füßen ist fest und Euer Geist ist bereits vom Feuer gewärmt... ich würde sagen, es ist an der Zeit, dass Ihr etwas über die Reinheit des Wassers lernt.\n\nEuer Weg hat Euch so weit gebracht und Euer Geist wird Euch die Kraft geben, noch weiter zu gehen. Doch den ersten Schritt müsst Ihr selbst machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1529] = { id = 1529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Es ist lange her, seit Ihr zuletzt geprüft wurdet, {name}. Bislang habt Ihr bei Euren Studien Geduld bewiesen, doch die Zeit ist gekommen, da Ihr mehr lernen müsst. Die Zeit ist gekommen, mehr über die Reinheit des Wassers zu lernen.\n\nSucht nach Islen Wasserdeuter im Brachland. Sie befindet sich an der Ostküste, südlich von Ratschet und dem Südstrom. Ihr findet sie in ihrer Fischerhütte. Viel Glück, {name}.", sourceObjective = "Sucht Islen Wasserdeuter im Brachland.", completion = "Der Wind weht heftig vom Horizont her, die Erde unter Euren Füßen ist fest und Euer Geist ist bereits vom Feuer gewärmt... ich würde sagen, es ist an der Zeit, dass Ihr etwas über die Reinheit des Wassers lernt.\n\nEuer Weg hat Euch so weit gebracht und Euer Geist wird Euch die Kraft geben, noch weiter zu gehen. Doch den ersten Schritt müsst Ihr selbst machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1530] = { id = 1530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Wenn Ihr eine Lektion über Wasser lernen müsst, dann diese: Wasser bedeutet Wiedergeburt.\n\nSeine Macht fließt, erodiert und reinigt alle Arten von Dingen. Seine Fähigkeit zu heilen und zu regenerieren ist unvergleichlich, jedoch nur, wenn es rein ist.\n\nWenn Ihr begreift, dass verunreinigtes Wasser alles verheeren kann, was es berührt, werdet Ihr schätzen lernen, wie lebenswichtig dieser Rohstoff ist.\n\nWenn Ihr das Wassersapta möchtet, sucht Brine tief im Südlichen Brachland. Ihr Heim wird unablässig von den dortigen Stachelebern heimgesucht.", sourceObjective = "Sucht Brine beim Schwarzdorngrat im Südlichen Brachland.", completion = "Ja?\n\nMmm, ich habe das Gefühl, als wüsste ich, was Ihr mich fragen wollt: was veranlasst jemanden, hier im tiefsten Brachland zu leben, ständig von Stachelebern bedroht und ohne Schutz? Wir alle haben unsere Gründe, mit denen wir unser Tun rechtfertigen. Die wahre Frage ist jedoch, was führt einen bescheidenen {race} in die entlegensten Winkel des Brachlandes, um mit einer Frau zu sprechen, die sich eindeutig nicht um ihr Wohlergehen schert?\n\nIch wette, die Antwort darauf kennen wir beide.", sourceObjectiveStatus = "unverified-source-field" }
quests[1531] = { id = 1531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "Macht Euch auf den Weg, Mann. Ihr seid bereit, Euch des Lufttotems würdig zu erweisen, aber zuerst müsst Ihr Prate Wolkendeuter in Tausend Nadeln finden. Wenn Ihr sie mit ausreichend Respekt behandelt, wird sie bereit sein, Euch zu sagen, wie Ihr das Lufttotem bekommen könnt.\n\nGeht durch das Brachland nach Süden und weiter nach Osten, wenn Ihr Tausend Nadeln erreicht habt. Ihr werdet sie verborgen in einem Erdloch mit ihrem Liebsten finden - haha, sagt ihr nicht, dass ich schlecht über sie geredet habe - das mag sie nicht sonderlich.", sourceObjective = "Sucht Prate Wolkendeuter in Tausend Nadeln.", completion = "Fürs Erste werde ich Euch geben, was Ihr benötigt, um Eure Sprüche zu fokussieren und die Geister der Luft anzurufen. Nehmt dieses Totem, und wenn Ihr bereit seid, übt noch etwas mehr mit mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[1532] = { id = 1532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Luft", description = "Die Winde von Kalimdor wehen Euch entgegen und Ihr sollt zu den Mächtigsten unserer <Brüder/Schwestern> gehören. Ich sehe mit Stolz, dass Ihr so weit gekommen seid und so eine viel versprechende Zukunft habt.\n\nDas Luftelement ist schwer zu kontrollieren, doch ich vertraue darauf, dass Eure Fertigkeiten alle Hindernisse überwinden, die Euch den Weg versperren.\n\nGeht zum äußersten Südrand des Brachlandes und betretet Tausend Nadeln. Dort, weit im Osten, werdet Ihr Prate Wolkendeuter finden. Sie wird Euch mehr beibringen.", sourceObjective = "Sucht Prate Wolkendeuter in Tausend Nadeln.", completion = "Fürs Erste werde ich Euch geben, was Ihr benötigt, um Eure Sprüche zu fokussieren und die Geister der Luft anzurufen. Nehmt dieses Totem, und wenn Ihr bereit seid, übt noch etwas mehr mit mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[1534] = { id = 1534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Nehmt diesen Wasserschlauch und begebt Euch tief in die dichten Wälder, an den Ort, den die Nachtelfen Eschental nennen. Sie liegen weit nördlich des Brachlandes.\n\nWenn Ihr den Wald betreten habt, reist nach Westen, an den Bergen entlang, die das Steinkrallengebirge und das Eschental trennen. Jenseits des Mystralsees findet Ihr einen heiligen Ort: die Sternenstaubruinen. In der Mitte des Sees findet Ihr einen kleinen Brunnen.\n\nBringt mir eine Probe des Brunnenwassers. Das ist die letzte Komponente, die Ihr braucht, ehe ich Euch zu Islen zurückschicke.", sourceObjective = "Füllt den leeren blauen Wasserschlauch bei den Sternenstaubruinen im Eschental und kehrt zu Brine im Brachland zurück.", progress = "Habt Ihr das Wasser schon, {name}? Es heißt, die Ruinen werden von riesigen Kreaturen der Natur beschützt, die keine Besucher dulden, doch das könnten Mythen sein, um die Feinde der Nachtelfen einzuschüchtern.\n\nSeid dennoch vorsichtig.", completion = "Großartig, {name}. Nachdem Ihr alle drei Proben gesammelt habt, kann ich für Euch eine Phiole des reinsten Wassers herstellen, das ein lebendiges Geschöpf finden kann. Es wird bei den nächsten Schritten Eures Initiationsritus Verwendung finden.\n\nEs freut mich, Euch in unserer Mitte begrüßen zu dürfen, {name}. Ihr gereicht allen Schamanen zum Stolz. Ich kann es kaum erwarten, von Euren zukünftigen Taten zu hören.", sourceObjectiveStatus = "unverified-source-field" }
quests[1535] = { id = 1535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Um Wissen zu erlangen und das Sapta von mir zu bekommen, dürft Ihr nur nach den reinsten Formen des Wassers suchen. Doch achtet auf Eure Umgebung, wenn Ihr die Proben für mich beschafft. Hütet Euch vor Kreaturen, die auf das Wasser angewiesen sind, das sie beschützen. Seht, wie es Wälder und Wüsten beeinflusst. Beobachtet, wie die Substanz, die das Leben erhält, Kreaturen dazu zwingt, Leben zu nehmen.\n\nWir beginnen mit einer einfachen Aufgabe: unterhalb meiner Hütte befindet sich ein Tümpel mit der kostbaren Flüssigkeit. Füllt diesen Schlauch damit und kehrt zu mir zurück.", sourceObjective = "Füllt den leeren braunen Wasserschlauch im Wasserloch unterhalb von Brines Hütte und kehrt damit zu Brine im Brachland zurück.", progress = "Ich bin fast bereit, Euch die anderen Aufgaben zu geben. Habt Ihr den Schlauch schon gefüllt?\n\nIch weiß, welche Beschützerinstinkte die Stacheleber entwickeln können. Für sie bedeutet selbst so eine kleine Wasserquelle großen Reichtum. Bei der geringsten Menge Regen im Brachland feiern sie ein großes Fest. Wasser ist ihrer Art heilig, weil es so selten ist. Habt Ihr verstanden?", completion = "Ich dachte mir, dass es zu Blutvergießen kommt, wenn Ihr versucht, Wasser aus dem Teich zu schöpfen. Leider begreifen die Stacheleber nicht, dass alle Lebewesen miteinander verbunden sind; dass ihre Gier nur Leid und Schmerz über ihr Volk bringt. Wie viel könnten sie erreichen, wenn sie ihre Differenzen beilegen und ihre Klans vereinigen würden.\n\nNochmals, ein Jammer, aber vermutlich ein Segen für alle anderen Völker des Brachlandes.", sourceObjectiveStatus = "unverified-source-field" }
quests[1536] = { id = 1536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Wassers", description = "Vor langer Zeit folgte ich einigen Gefährten ins Vorgebirge des Hügellands. Wir verteidigten uns gegen einige aufmüpfige Menschen, die dort beheimatet sind, und kamen in eine kleine Stadt, die die Verlassenen übernommen hatten: Tarrens Mühle.\n\nDort fand ich etwas höchst Eigentümliches: In der Mitte der Stadt befand sich ein kleiner Brunnen mit frischem Quellwasser. Ich bin nicht sicher, ob die gebeutelten Bewohner der Stadt seinen Wert überhaupt kennen... er ist eine kleine heilige Insel in einem unheiligen Meer.\n\nBringt mir eine Probe dieses Wassers in diesem Wasserschlauch.", sourceObjective = "Füllt den leeren roten Wasserschlauch am Brunnen in Tarrens Mühle und kehrt zu Brine im Brachland zurück.", progress = "Der Brunnen, der mitten in der Stadt rein bleibt, erinnert mich an Geschichten, die mir in meiner Kindheit erzählt wurden, {name}. Selbst in Zeiten von großem Schmerz und Kummer kann man ein Fünkchen Hoffnung finden, ein kleines Symbol, um das man sich schart. Das Orc-Volk sieht Thrall auf diese Weise. Er überlebte allen Widrigkeiten zum Trotz, erhob sich und führte unser Volk durch seine Kraft und sein Vorbild.\n\nIch bin nicht sicher, ob je ein Orc so viel gelitten hat wie er, aber gleichzeitig bin ich nicht sicher, ob je ein Orc stärker sein wird als er.", completion = "Das ist gut, {name}. Ihr geht die vorliegende Aufgabe entschlossen an und seid fähig, das zu suchen, was benötigt wird.\n\nIch benötige nur noch eine Probe, um das Reagenz herzustellen, das für Euer Sapta erforderlich ist. Islen wird ebenfalls zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1558] = { id = 1558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Steinwerkdamm", description = "In der Nähe von Eisenschmiede, wo all die Zwerge und Gnome leben, gibt es einen Ort namens Loch Modan und die Zwerge haben da einen grooooßen Staudamm gebaut. Ich habe gehört, dass ist eines von den größten Dingen, die je gebaut wurden. Wow!\n\nKönnt Ihr mir den Damm in Loch Modan zeigen, bitte?! Ich glaube der heißt Stein... äh... Steinwerkdamm? Er ist riesig, so viel ist klar. Ich würde so gerne auf den großen Wasserfall heruntersehen. Ich verspreche, mich auch nicht zu weit vorzulehnen.", sourceObjective = "Begleitet Euren Schützling zum Steinwerkdamm in Loch Modan. Geht mit ihm zur Mitte des Damms, damit er auf den riesigen Wasserfall heruntersehen kann.", progress = "Sind wir bald da?", completion = "WOW - Der Damm war tausendmal größer als ich gedacht habe! Bei dem lauten Rauschen des Wassers konnte ich mich kaum noch selber hören. Hey, glaubst du das dem Wasserfall jemals das Wasser ausgeht? Was passiert bloss wenn der Damm mal bricht? WOW, das wäre gruselig.\n\nDanke, dass du mir den Damm gezeigt hast. Das war sehr lieb von dir. Ich hab dir ja gesagt, dass ich mich nicht zu weit überlehnen werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[1559] = { id = 1559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blitzstrahlbombenanleitung", sourceObjective = "Ihr seid also Ingenieur, hm? Als Dank für Eure Hilfe bei der Beschaffung der Perlen bekommt Ihr eine Anleitung für Blitzstrahlbomben.\n\nViel Glück und versucht, Euch nicht selbst zu blenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[1560] = { id = 1560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toogas Bitte", description = "Ich habe mich vollkommen verirrt!\n\nTorta, meine Frau, schickte mich Essen holen, aber ich muss irgendwo falsch abgebogen sein.\n\nWürdet Ihr so freundlich sein, mich zu Torta zurückzuführen? Sie wartet südlich vom Dampfdruckpier auf mich.", sourceObjective = "Zeigt Tooga den Weg zurück zu seiner Frau Torta.", progress = "Wo ist Tooga?", completion = "Er konnte also den Rückweg nicht allein finden? Typisch.\n\nAlso ich finde, Ihr verdient etwas für Eure Mühe...", sourceObjectiveStatus = "unverified-source-field" }
quests[1578] = { id = 1578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachschub für die Front", description = "Die Gebirgsjäger vom Loch Modan kämpfen gegen Troggs und sind damit schwer beschäftigt! Sie benötigen konstanten Nachschub an neuen Rüstungen und Waffen, wenn wir diese Troggs je bezwingen wollen.\n\nDarum ist mein Kollege Thorvald hier und versucht, die Gebirgsjäger gut ausgerüstet zu halten. Wenn Ihr einige Kupferäxte und Kettengürtel aus Kupfer herstellen und sie Thorvald bringen könntet, wäre er Euch sehr verbunden. Vielleicht weiht er Euch sogar in sein Wissen ein.\n\nThorvald ist im südlichem Wachturm von Loch Modan.", sourceObjective = "Bringt 6 Kupferäxte und 6 kupferne Kettengürtel zu Thorvald im südlichen Wachturm von Loch Modan.", progress = "Ich habe keine Zeit zu plaudern. Haben wir etwas miteinander zu tun?", completion = "Ah, Entschuldigung! Ich wusste nicht, dass Ihr hier seid, um die Truppen auszurüsten. Die Sachen, die Ihr hergestellt habt, werden eine große Hilfe sein!\n\nHier sind Pläne für einige Rüstungen. Ich hoffe, Ihr findet sie nützlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[1579] = { id = 1579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klemmmuffen", description = "Ich kam nach Auberdine wegen der Ruhe. Ich möchte meine Erfindungen machen, wo es ruhig ist, denn nach einer durchzechten Nacht ertrage ich den Lärm von Eisenschmiede nicht!\n\nDaher nahm ich ein Schiff nach Auberdine, trank aber unterwegs ein bisschen viel. Ich ließ meine Kiste mit Klemmmuffen über Bord fallen! Ich brauche meine Klemmmuffen!\n\nIch weiß nicht genau, wo ich sie fallen ließ, aber vielleicht habt Ihr ja Glück, wenn Ihr im Meer danach fischt...", sourceObjective = "Bringt 8 Klemmmuffen zu Hexknall Kurbeldreh in Auberdine.", progress = "Habt Ihr meine Klemm-Muffen gefunden, {name}? Ohne meine Klemm-Muffen kann ich meine Stintelpleuel nicht nachziehen!", completion = "Ich kann nicht glauben, dass Ihr sie gefunden habt! Ihr seid der {race} mit dem meisten Glück in Kalimdor!", sourceObjectiveStatus = "unverified-source-field" }
quests[1580] = { id = 1580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elektropeller", description = "Wir wissen, dass Ihr Glück habt, aber... wie viel Glück genau, {name}?\n\nEines Nachts schlenderte ich durch die Straßen von Dunkelküste. Ich suchte nach einem geeigneten Fluss oder See, um meine neuen propellerbetriebenen explodierenden Entenattrappen auszuprobieren. Ich muss wohl etwas beschwipst gewesen sein, denn Stunden später wachte ich in Auberdine auf. Mein Haar war versengt und meine Tasche mit den Elektropellern war weg! Sie müssen mir ins Wasser gefallen sein!\n\nIch brauche diese Elektropeller! Vielleicht könnt Ihr sie aus einem See oder Bach in Dunkelküste fischen...", sourceObjective = "Bringt 12 Elektropeller zu Hexknall Kurbeldreh in Auberdine.", progress = "Habt Ihr meine Elektropeller gefunden? Ich brauche sie, wenn ich meine Forschungen über Entenattrappen fortsetzen soll...", completion = "Ich kann es nicht glauben! Ihr habt sie gefunden! Ihr seid der beste Angler, den ich je gesehen habe!\n\nDanke, {name}. Und hier, nehmt dies. Ihr seid so gut und braucht sie wahrscheinlich nicht, aber sie helfen Euch beim Angeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[1581] = { id = 1581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixiere für die Messerblatts", description = "Unser Kräuter- und Alchemieladen floriert, aber mein Mann verbringt so viel Zeit damit, Tränke zu mischen, dass wir nie Zeit füreinander haben.\n\nKönnt Ihr uns helfen?\n\nWenn Ihr mir einen Vorrat an vorgefertigten Elixieren bringt, würde ich mit Freuden mit Euch tauschen. Ich besitze gewisse seltene Kräuter, die Euch nützlich sein könnten.", sourceObjective = "Bringt 6 Elixiere der Löwenstärke und 2 Elixiere der schwachen Verteidigung zu Syral Messerblatt in Dolanaar.", progress = "Hallo, {name}. Habt Ihr die Elixiere zum Tauschen?", completion = "Die sind ordentlich gemischt. Ihr nehmt Euer Handwerk ernst, {name}, und das ist wichtig für einen Alchimisten.\n\nHier sind Eure frisch gesammelten Kräuter. Benutzt sie mit Umsicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1582] = { id = 1582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondscheinweste", description = "Wir in Darnassus, besonders wir Handwerker, sind sehr beschäftigt. Junge Abenteurer brennen darauf, sich in der Wildnis zu beweisen und benötigen unablässig Nachschub.\n\nWenn Ihr mir helft, meine Bestellungen an Lederwaren zu erfüllen, kann ich Euch vielleicht eine hochentwickelte Technik der Lederverarbeitung beibringen.", sourceObjective = "Bringt 1 Paar geprägte Lederhandschuhe, 5 Paar geprägte Lederstiefel und 5 geprägte Lederumhänge zu Lotherias in Darnassus.", progress = "Seid gegrüßt, {name}.", completion = "Ja, das sind gute Stücke. Ihr habt eine geschickte Hand und ein Auge für Details. Eure Zukunft als Lederer scheint viel versprechend.\n\nHier, {name}. Lasst mich Euch das Muster für eine Mondscheinweste zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1598] = { id = 1598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gestohlene Foliant", description = "Ihr da! {name}, richtig?\n\nIch hoffe, Ihr seid sicher, dass Ihr ein Hexenmeister werden möchtet, denn wenn Ihr nicht allein besteht, werdet Ihr gewiss untergehen.\n\nIch werde Euch unterrichten, muss aber zuerst sicher sein, dass Ihr stark genug seid.\n\nEin Novize, der an der Abtei studierte, lief weg und schloss sich der Bruderschaft der Defias an. Warum mich das kümmert? Weil er einige wichtige Bücher gestohlen hat.\n\nEines davon war ein Buch, das ich selbst wollte, Die Macht der Leere. Stehlt es für mich, sie haben es in ihrem Zelt in den Weinbergen versteckt.", sourceObjective = "Holt Die Macht der Leere für Drusilla La Salle zurück.", progress = "Es wäre zu auffällig für mich gewesen, das Buch selbst zu stehlen. Zum Glück hat mir einer ihrer eigenen Trottel die Drecksarbeit abgenommen.", completion = "Exzellent... Ich wäre nie an diesen Text rangekommen. Er wurde in einem gesicherten Flügel der Bibliothek verwahrt und es hätte verdächtig ausgesehen, wenn ich dort herumgeschlichen wäre.\n\nIhr habt Eure Sache gut gemacht, als Ihr das geholt habt. Ich bin überzeugt, Ihr werdet mit einem eigenen Wichtel fertig, daher sehe ich keinen Grund, Euch nicht zu zeigen, wie man einen beschwört.", sourceObjectiveStatus = "unverified-source-field" }
quests[1599] = { id = 1599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anfänge", description = "Ihr müsst der neue Hexenmeister sein, über den alle tuscheln. Jemand muss Euch sehr mögen, wenn man mich bittet, meine Forschungen aufzuschieben und Eure Ausbildung zu übernehmen.\n\nKeine Bange, ich mache Euch keinen Vorwurf.\n\nDer einfachste Beschwörungszauber, den Ihr lernen werdet, ist der für einen Wichtel. Doch bevor ich ihn Euch beibringe, müsst Ihr beweisen, dass Ihr die notwendigen magischen und körperlichen Fähigkeiten besitzt.\n\nBringt mir drei Federglücksbringer von den Novizen der Frostmähnen aus der Höhle im Südwesten.", sourceObjective = "Bringt 3 Federglücksbringer zu Alamar Grimm in Ambossar.", progress = "Diese Federglücksbringer der Novizen besitzen eine Art von magischer Kraft. Es wird interessant sein, sie zu erforschen. Hätte ich von den Trollen gar nicht erwartet.", completion = "Sehr gut, sehr gut! Ihr habt Eure Sache gut gemacht, {name}. Vielleicht ist das Interesse, das man Euch entgegenbringt, ja doch gerechtfertigt.\n\nAber das müssen andere entscheiden... vorausgesetzt, Euer Wichtel überwältigt Euch nicht und bereitet damit Eurer Karriere ein vorzeitiges Ende. Vorerst bin ich schon damit zufrieden, dass Ihr die ersten Monate als {class} vermutlich überleben werdet.\n\nEin Wort zu dem Wichtel, {name}. Lasst Euch, wie jeder {race} weiß, nicht von der Größe täuschen, seine Magie kann sehr gefährlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1618] = { id = 1618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aufrüstung im Rotkammgebirge", description = "Wir Zwerge sind nicht die Einzigen, die kämpfen. Unsere menschlichen Verbündeten haben auch alle Hände voll zu tun!\n\nDas Rotkammgebirge wird immer wieder von den Schwarzfelsorcs angegriffen und der Vorrat an Ausrüstung ist stets knapp. Ich bin sicher, wenn Ihr ihnen helft, wird der ansässige Schmied, Verner Gutmark, Euch den einen oder anderen Trick beibringen.", sourceObjective = "Tormus Tiefenschmied möchte, dass Ihr 4 runenverzierte Kupfergürtel und 4 schwere Kupferschlägel zu Verner Gutmark ins Rotkammgebirge bringt.", progress = "Ich hoffe, Ihr bringt gute Nachrichten aus Ironforge. Denn ich bin mit meiner Weisheit am Ende!", completion = "Danke, {name}. Das wird mir unwahrscheinlich helfen. Da die Orcs der Blackrock von der Burg Steinwacht angreifen und die Rotkammgnolle in den Vorgebirgen im Norden lauern, muss ich ständig Rüstungen ausbessern und neue Waffen für unsere Truppen anfertigen.\n\nDie Vorräte, die Ihr gebracht habt, bescheren mir einen Moment Ruhe. Daher habe ich genug Zeit, Euch etwas beizubringen...", sourceObjectiveStatus = "unverified-source-field" }
quests[1638] = { id = 1638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ausbildung eines Kriegers", description = "Ihr habt Euch als fähiger Krieger erwiesen, {name}. Aber Ihr seid noch jung und müsst noch viel lernen.\n\nSprecht mit Harry Burlwacht... er ist meist in der Taverne \"Zum Pfeifenden Schwein\" in der Altstadt von Sturmwind. Harry ist ein alter Veteran und guter Lehrer. Er kann Euch einige Kampftechniken zeigen, die Euer Leben verlängern.", sourceObjective = "Sprecht mit Harry Burlwacht in Sturmwind.", completion = "Oh-ho! Trinkt einen Schluck mit mir, Junge. Äußerlich macht Ihr einen zähen Eindruck. Mal sehen, ob Euer Magen ein paar Krüge vom Stärksten aus dem Pfeifenden Schwein verträgt!!!\n\nOder... seid Ihr wegen einer Lektion hier?", sourceObjectiveStatus = "unverified-source-field" }
quests[1639] = { id = 1639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bartleby der Trunkenbold", description = "Ja, ich kann Euch unterrichten. Aber vorher will ich sehen, welche Kampftechniken Ihr schon beherrscht.\n\nSeht Ihr den Betrunkenen am Ende der Bar? Bartleby? Nehmt ihm seinen Krug weg.\n\nHa, und wenn Ihr Bartleby kennt, dann wisst Ihr, dass er ihn nicht freiwillig rausrückt.", sourceObjective = "Sprecht mit Bartleby.", completion = "Hallo, mein Junge! Was hat jemand wie Ihr im Pfeifenden Schwein verloren? Vorsicht, sonst brecht Ihr Euch einen Nagel ab...", sourceObjectiveStatus = "unverified-source-field" }
quests[1640] = { id = 1640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegt Bartleby", description = "Ihr wollt was??? Ihr seid verrückt!\n\nWenn Ihr diesen Krug wollt, müsst Ihr ihn mir aus den kalten, toten Händen brechen...", sourceObjective = "Besiegt Bartleby und redet dann mit ihm.", progress = "Wenn Ihr diesen Krug wollt, müsst Ihr ihn mir aus den kalten, toten Händen brechen...", completion = "Ihr seid viel zäher als Ihr ausseht!", sourceObjectiveStatus = "unverified-source-field" }
quests[1641] = { id = 1641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", sourceObjective = "Hier in Stormwind bin ich dafür verantwortlich, die Paladine auf den Pfad der größten Tugend zu bringen, sobald sie sich dem Weg des Lichts verschreiben und Azeroth vor der Geißel und anderen Bedrohungen verteidigen.\n\nDie Zeit ist gekommen, den ersten Schritt hin zu wahrer Tugend zu tun. Wenn Ihr einverstanden seid, gebe ich Euch das Buch der Offenbarung. Wenn Ihr es studiert, erfahrt Ihr etwas über das Licht und was von Euch erwartet wird. Wenn Ihr es versteht und tüchtig seid, werdet Ihr erfolgreich größere Fähigkeiten erlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1642] = { id = 1642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Ein Paladin muss in allen Dingen das Licht widerspiegeln, das uns Kraft gibt. Wenn einer unserer Art nach dem Göttlichen strebt, bedeutet das nicht, dass er ein Gott sein möchte... wir trachten nur danach, in allem nur Gutes zu tun.\n\nAuch wenn Ihr in diesen schweren Zeiten berufen seid, das Böse zu zerschmettern, dürft Ihr nicht vergessen, dass die Unterstützung anderer Euch wahrhaft von den Bürgern von Azeroth unterscheidet. Mitgefühl, Geduld, Tapferkeit... das alles bedeutet einem Paladin so viel wie Kraft im Kampf.\n\nBedenket das und vergesst es niemals.", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", completion = "Abermals hallo, {name}. Was machen Eure Studien des Folianten der Offenbarung?\n\nDann solltet Ihr bereit sein, Euch prüfen zu lassen. Es gibt in der Stadt und unseren Ländern immer etwas zu tun; barmherzige und verständnisvolle Taten; Menschen, die Hilfe brauchen; Kreaturen, die besiegt werden müssen.\n\nWenn Ihr beweist, dass Ihr die Geduld habt, anderen zu helfen, besonders jenen, die nicht so glücklich sind, beweist Ihr, dass Ihr ein Diener des Lichts und bei klarem Verstand seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[1643] = { id = 1643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Eure Aufgabe, {name}, besteht darin, jemanden hier in Sturmwind zu finden, der der Hilfe bedarf. Jemanden mit reinem Herzen und edlen Motiven. Vielleicht jemanden, der anderen hilft. Vielleicht jemanden, der einen Führer braucht. Was auch immer, die Person muss edle Absichten haben und auf Eure Güte angewiesen sein.\n\nMacht das und kommt zu mir zurück, wenn Ihr fertig seid. Dann sprechen wir weiter über Euren Weg und was es bedeutet, ein Paladin des Lichts zu sein.", sourceObjective = "Sucht im Handelsdistrikt von Sturmwind nach Stephanie Turner.", completion = "Ach, hallo. Was machen Eure Abenteuer? Oh, freut mich zu hören, dass alles gut läuft.\n\nOh, ich? Danke der Nachfrage - alles in allem geht es mir ganz gut.\n\nDurch die wachsende Zahl der Händler sind die Leute nicht mehr so bereit, sich von Leder und Tuch zu trennen, Daher ist es schwerer, Kleidung für die Kinder im Waisenhaus zu machen, aber wir bekommen das schon hin. Mit \"wir\" meine ich meinen Mann und mich. Er ist in Ironforge und sucht dort Hilfe bei den Bürgern.", sourceObjectiveStatus = "unverified-source-field" }
quests[1644] = { id = 1644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Die meisten der guten Seelen haben keine Familien mehr aufgrund der Angriffe der Geißel im letzten Jahrzehnt.\n\nMein Mann John sammelt die Materialien, die ich brauche, um Hemden und Hosen für die Kinder zu machen, aber nicht einmal dafür hatte ich Zeit. Ich war zu sehr damit beschäftigt, ihnen Essen auf ihre Teller und ein Dach über ihre Köpfe zu geben.\n\nWie war das? Ihr wärt bereit, mir zu helfen? Oh, dem Licht sei Dank und Euch ebenfalls, {name}.\n\nWenn Ihr mir etwas Leinen bringen könntet, damit ich den Kindern Kleidung nähen kann, wäre mir das eine große Hilfe.", sourceObjective = "Bringt 10 Stück Leinenstoff zu Stephanie Turner in Sturmwind.", progress = "Ich hoffe, John hat in Ironforge mehr Glück. Die Ausflüge dorthin sind ihm so zuwider, weil er mich und die Kinder allein lassen muss, aber er weiß, es geht nicht anders. Er ist so herzensgut.\n\nManche Jahre waren besser als andere, aber dieses war bei weitem das Schlimmste. Es ist fast, als würde eine gewaltige Veränderung in der Luft liegen. Wer weiß?", completion = "Danke {name}, vielen, vielen Dank!\n\nDie Kinder werden sich freuen und Ihr habt mir so viel Zeit gespart. Jetzt kann ich mich auf die anderen Bedürfnisse der Kinder konzentrieren und mein John hoffentlich früher heimkehren als wir dachten.\n\nNochmals danke, {name}. Ich wusste, ich kann mich auf die Barmherzigkeit anderer verlassen. Das Licht sei mit Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[1645] = { id = 1645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", sourceObjective = "Welche Freude, Euch zu sehen, {name}. Ich bringe die Paladine auf den Pfad der Tugend, wenn sie sich dem Weg des Lichts verschreiben und Azeroth vor der Geißel und anderen Bedrohungen beschützen.\n\nDie Zeit ist gekommen, den ersten Schritt hin zu wahrer Tugend zu tun. Wenn Ihr einverstanden seid, gebe ich Euch den Folianten der Offenbarung. Wenn Ihr es studiert, erfahrt Ihr etwas über das Licht und was von Euch erwartet wird. Wenn Ihr es versteht und tüchtig seid, werdet Ihr erfolgreich größere Fähigkeiten erlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1646] = { id = 1646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Ein Paladin muss in allen Dingen das Licht widerspiegeln, das uns Kraft gibt. Wenn einer unserer Art nach dem Göttlichen strebt, bedeutet das nicht, dass er ein Gott sein möchte... wir trachten nur danach, in allem nur Gutes zu tun.\n\nAuch wenn Ihr in diesen schweren Zeiten berufen seid, das Böse zu zerschmettern, dürft Ihr nicht vergessen, dass die Unterstützung anderer Euch wahrhaft von den Bürgern von Azeroth unterscheidet. Mitgefühl, Geduld, Tapferkeit... das alles bedeutet einem Paladin so viel wie Kraft im Kampf.\n\nBedenket das und vergesst es niemals.", sourceObjective = "Sprecht mit Tiza Kriegshammer in Eisenschmiede.", completion = "Willkommen zurück, {name}. Ich hoffe, Ihr habt die Zeit genutzt und das Buch gelesen.\n\nDann solltet Ihr bereit sein, Euch prüfen zu lassen. Es gibt in der Stadt und unseren Ländern immer etwas zu tun; barmherzige und verständnisvolle Taten; Menschen, die Hilfe brauchen; Kreaturen, die besiegt werden müssen.\n\nWenn Ihr beweist, dass Ihr die Geduld habt, anderen zu helfen, besonders jenen, die nicht so glücklich sind, beweist Ihr, dass Ihr ein Diener des Lichts und bei klarem Verstand seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[1647] = { id = 1647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Eure Aufgabe, {name}, ist es, jemanden hier in Eisenschmiede zu finden, der der Hilfe bedarf. Jemand mit reinem Herzen und edlen Motiven. Vielleicht jemanden, der anderen hilft. Vielleicht jemanden, der einen Führer braucht. Was auch immer, die Person muss edle Absichten haben und auf Eure Güte angewiesen sein.\n\nMacht das und kommt zu mir zurück, wenn Ihr fertig seid. Dann sprechen wir weiter über Euren Weg und was es bedeutet, ein Paladin des Lichts zu sein. Ich warte hier im Tempel auf Eure Rückkehr. Auch andere Paladine brauchen meine Unterstützung.", sourceObjective = "Sucht im Äußeren Ring von Eisenschmiede nach John Turner.", completion = "DAS WAISENHAUS VON STOR... oh, tut mir Leid, ich wollte Euch nicht anschreien, Sire,\n\nIch heiße John Turner. Wie ist das werte Befinden?\n\nGut, gut, freut mich zu hören, dass alles gut für Euch läuft. Ich hatte schon einen langen Arbeitstag und vermisse meine Frau sehr, aber das ist der Preis, den man zahlt, wenn es Mäuler zu füttern und Leiber zu bekleiden gilt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1648] = { id = 1648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Meine Frau und ich führen das Waisenhaus in Sturmwind, das überwiegend Kindern vorbehalten ist, die im letzten Jahrzehnt ihre Eltern bei Angriffen der Geißel verloren haben. Ich komme etwa einmal im Monat nach Eisenschmiede und versuche, bei den Bürgern hier mehr Vorräte zu sammeln und mit den verschiedenen Gruppen zu reden, ob sie irgendwie helfen können.\n\nDieser Ausflug war schrecklich langwierig und nicht sehr ergiebig.\n\nKönnte ich doch nur noch etwas mehr Leinen bekommen, damit meine Frau Kleidungsstücke nähen kann, dann könnte ich endlich eine Ladung nach Hause schicken.", sourceObjective = "Bringt 10 Stück Leinenstoff zu John Turner in Eisenschmiede.", progress = "Bei dem Zustrom von Händlern hier und in ganz Azeroth, sind die Gegenstände knapper, aus denen wir Kleidung für die Kinder in unserem Waisenhaus machen. Es ist sehr anständig von Euch, dass Ihr mir helft, Leinen zu sammeln, damit meine Frau neue Kleidung nähen kann, {name}. Danke.\n\nHoffentlich kann ich bald zu meiner Frau heimkehren.", completion = "Das ist so wunderbar von Euch, {name}. Nochmals danke.\n\nEs ist so anständig von Euch, Mann, dass Ihr das für mich tut. Es ist schön zu sehen, dass Ihr dem Licht folgt. Gäbe es doch nur einen Weg, wie ich Euch vergelten könnte, was Ihr getan habt... wie war das? Es war das Mindeste, das Ihr tun konntet? Seht Ihr? Genau das meine ich, {name}, edel bis zuletzt.\n\nMöget Ihr sicher wandeln und das Licht Euch auf Euren Reisen beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1649] = { id = 1649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Tapferkeit", description = "Ehre, und alle Tugenden, die damit einhergehen, sind wie rare Mineralien: man muss sie ihres Wertes wegen bewundern, wenn man sie findet, aber man muss sich auch die Zeit nehmen, sie aufzuheben... zu veredeln. Mischt man sie richtig, entsteht eine starke Legierung, die manchmal selbst die heftigsten Hiebe nicht zerbrechen können.\n\nDiese Kraft, Euer Glauben, Eure Tapferkeit, müssen geprüft werden. Ihr müsst lernen, niemals den Glauben zu verlieren und erkennen, dass Ihr mit der Macht des Lichts Dinge überwinden könnt, vor denen andere klein beigeben müssen.", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", completion = "Ah, Ihr möchtet eine Prüfung Eurer Ehre von mir. Großartig.\n\nEs gibt viele Aufgaben in der Stadt und dem Umland, die Herausforderungen bieten und wo Männer mit Euren Fertigkeiten gebraucht werden.\n\nIhr solltet diese Prüfung nicht zu leicht nehmen, {name}. Dies könnte, wie so vieles auf unserem Weg, unser Leben kosten. Die Kirche möchte ihre Schäflein stets mehren, weiß aber um die Opfer, die gebracht werden müssen, um den Wert der Paladine, die ihr dienen, zu beweisen.\n\nSeid Ihr bereit?", sourceObjectiveStatus = "unverified-source-field" }
quests[1650] = { id = 1650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Tapferkeit", description = "Gut! Da Ihr nicht zögert, seid Ihr gewiss bereit und brennt darauf, Euch zu beweisen. So sei es.\n\nAm äußersten Ende der Endlosen Küste in Westfall steht ein kleines Haus über dem Ozean. Dort lebt ein Paar, die Stillbrunns. Jordan ist ein unglaublicher Schmied und für einige Zeit nach Eisenschmiede gegangen, um sich mit den Zwergen zu treffen. Dadurch ist seine Frau Daphne allein und schutzlos.\n\nEs wird berichtet, dass die Defias fast das gesamte Gebiet übernommen haben. Gut möglich, dass Daphne Schutz vor den Bösewichtern braucht. Geht dorthin.", sourceObjective = "Sucht Daphne Stillbrunn in Westfall.", completion = "Hallo, {name}. Wenn ich Eure Rüstungen und Waffen sehe, denke ich, dass Ihr mir entweder mein Land wegnehmen wollt oder die Kirche endlich jemanden zu meinem Schutz geschickt hat, so lange Jordan fort ist.\n\nDarf ich mich Euch vorstellen: Ich bin Daphne Stilwell. Ist mir ein Vergnügen.\n\nUnd Ihr kommt nicht zu spät... Seit dem letzten Sonnenaufgang habe ich erst ein halbes Dutzend dieses Abschaums getötet. Sie brauchen eine Weile, bis sie um die Kurve gebogen sind, aber sie haben Euch vermutlich gesehen. Dies bedeutet, dass sie wahrscheinlich jede Minute hier sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[1651] = { id = 1651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Tapferkeit", description = "Ich wette, die kommen bald wieder, also macht Euch bereit.\n\nIch habe eine Schusswaffe im Haus. Ich hole sie und helfe Euch gern, aber Ihr werdet weitgehend auf Euch gestellt sein.\n\nIch habe keine Ahnung, wie viele sie schicken, aber es werden sicher mehr sein als die paar beim letzten Mal.\n\nBittet das Licht um jeden erdenklichen Segen, denn...habt Ihr das gehört? Ich glaube, sie kommen.\n\nWir beziehen Position beim Haus!", sourceObjective = "Verteidigt Daphne Stillbrunn vor dem Angriff der Defias.\n\nKeiner Eurer Geister darf aus seinen irdischen Fesseln befreit werden, wenn Ihr erfolgreich sein wollt.\n\nSprecht erneut mit Daphne Stillbrunn, wenn Ihr erfolgreich wart.", progress = "Wir werden unsere Position beim Haus beziehen!", completion = "Wir haben es geschafft, {name}! Danke für Eure Hilfe. Ihr wart wirklich erstaunlich da draußen. Ich hätte nie gedacht, dass es ein {class} mit so vielen Gegnern gleichzeitig aufnehmen kann.\n\nIhr habt wahrlich Tapferkeit im Angesicht einer Übermacht gezeigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1652] = { id = 1652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Tapferkeit", description = "Kehrt bitte zu Duthorian zurück und lasst ihn wissen, dass ich hier vorerst sicher bin. Dafür muss ich Euch und der Kirche danken.\n\nEr wird eine Nachricht nach Eisenschmiede schicken und meinen Jordan wissen lassen, dass er keinen Grund zur Furcht hat.\n\nOh, ich vermisse meinen Mann so sehr. Ich kann es kaum erwarten, bis er wieder da ist.", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", completion = "So begegnen wir uns wieder, {name}, und wie ich sehe, seid Ihr bester Laune.\n\nDas Heim der Stilwells ist wieder einen Tag sicher, und Eurer Geschichte entnehme ich, dass es an Gefahren nicht gemangelt hat. Gut gemacht.\n\nDaphne und Jordan haben der Kirche sehr geholfen. Dass wir ihr Eigentum - und ihr Leben - durch Euch beschützen ließen, war das Geringste, was wir für sie tun konnten.\n\nIhr werdet für Euren Wagemut belohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[1653] = { id = 1653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Rechtschaffenheit", description = "Ich zweifle nicht daran, dass Jordan Euch persönlich danken möchte, und da ich einen Boten brauche, der ihn wissen lässt, dass es seiner Frau gut geht, scheint Ihr mir die perfekte Wahl zu sein.\n\nJordan sollte ein Paladin des Lichts sein, bevor die Liebe zum Beruf seines Vaters ihn einen anderen Weg einschlagen ließ - er ist innig mit unserer Lebensweise vertraut und wird zu unseren Getreuesten gerechnet.\n\nEr müsste noch in Eisenschmiede sein - tagsüber arbeitet er gern vor den Toren, wohl wegen der kühlen Bergluft.", sourceObjective = "Sprecht mit Jordan Stillbrunn in Eisenschmiede.", completion = "Guten Tag, {name}. Das Licht ist mit Euch, nehme ich an?\n\nWie war das? Duthorian hat Euch geschickt!? Meine Frau, wie geht es ihr? Ich wusste, es würde Ärger geben, wenn ich fortgehe. Bitte sagt mir, dass sie... oh, welch ein Glück. Ich bin so froh, dass sie in Sicherheit ist. Die Defias waren lange vor diesen Angriffen eine Bedrohung, aber jetzt können es die Berater des Königs nicht mehr leugnen.\n\nWas hat Duthorian noch gesagt?\n\nIhr wart es, der meine Frau beschützt hat? Dann danke ich Euch nochmals, {name}. Eine bessere Prüfung der Ehre kann ich mir nicht vorstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1654] = { id = 1654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Rechtschaffenheit", description = "Ich würde Euch gern eine Belohnung geben, wenn Ihr bereit seid, eine anzunehmen. Missversteht mich nicht, meine Großzügigkeit hängt davon ab, wie hilfreich Ihr sein könnt, aber ich denke, wir werden beide von einer derartigen Allianz profitieren.\n\nIch werde Euch eine Waffe schmieden, die Eurer Leistung würdig ist, ein Symbol der Paladinschaft und des Lichts, doch zuvor müsst Ihr die Gegenstände sammeln, die ich zu seiner Herstellung brauche. Ich habe schon angefangen, mir Notizen zu den Gegenständen zu machen, und brauche nur jemanden, der tapfer und geschickt genug ist, sie zu beschaffen. Was sagt Ihr dazu, {class}?", sourceObjective = "Sucht mit Jordans Waffennotizen etwas Weißsteineichenholz, Bailors aufbereitete Erzlieferung, Jordans Schmiedehammer und einen Koredelstein und bringt alles zusammen zu Jordan Stillbrunn in Eisenschmiede.", progress = "Es dürfte schwer sein, die Gegenstände zu bekommen, die Ihr sucht, aber ich versichere Euch, die Waffe, die ich für Euch anfertige, rechtfertigt den Aufwand.\n\nSie wird meine bis dato beste Arbeit werden, und doch nur ein geringer Lohn für den Dienst, den Ihr mir erwiesen habt.", completion = "Das ist wunderbar! Ihr habt alle Gegenstände bekommen.\n\nDamit müsste ich Euch problemlos eine grandiose Waffe schmieden können. Ích hatte seit langem Pläne dafür, aber bisher nie Gelegenheit gefunden, die Zutaten herbeizuschaffen. Danke, {name}.\n\nEs tut gut, wieder den Hammer meines Vaters zu schwingen... und einen Edelstein aus Kor, ich dachte nicht, dass ich je selbst einen sehen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[1655] = { id = 1655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bailors Erzlieferung", description = "Ach, Ihr habt mich erschreckt, <Mann/Frau>! Seht Ihr nicht, dass ich nachdenke?\n\nWie war das? Jordans Lieferung... für Eisenschmiede. Ahhh, ja, ich weiß, wovon Ihr sprecht. Oger der Mo'grosh haben die Erzlieferung meines alten Freundes gestohlen. Die Karawane war auf dem Weg vom Sumpfland hierher und geriet in einen Hinterhalt. Die Wache, die den Angriff überlebte, starb vor wenigen Tagen - der Heiler kam nicht schnell genug hin.\n\nWenn Ihr die Lieferung wollt, müsst Ihr über den Loch nach Nordosten. Dort muss sie irgendwo sein.", sourceObjective = "Bringt Jordans Erzlieferung zu Bailor Steinhand in Loch Modan.", progress = "Aha, schon Glück gehabt? Ha-ha, diese Oger konnten Euch nichts anhaben, was?", completion = "Woll, woll, das ist es. Ha! Hätte ich gewusst, dass Ihr wirklich da rausgeht und gegen diese Oger kämpft, hätte ich Euch eine ganze Liste von Aufträgen gegeben, nicht nur diesen einen. Aber Ihr seid nicht hier, um Geschäfte für mich zu machen, oder?\n\nAbgemacht ist abgemacht; Jordan wollte eine Lieferung meiner Legierung, und die soll er bekommen.\n\nGrüßt ihn von mir, und gute Reise, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1656] = { id = 1656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unvollendete Aufgabe", description = "{name}, bitte, ich flehe Euch an, könnt Ihr mir helfen? Ich habe meine Aufgaben hier auf der Ebene noch nicht beendet - ich bin mitten in meinem Ritual der Kraft - und mein Vater bat mich, diese Felle im Gasthaus der Bluthufe abzuliefern.\n\nIch bin längst nicht erholt genug, mein Ritual und diese Aufgabe für meinen Vater zu beenden. Würdet Ihr an meiner statt gehen?\n\nDas Gasthaus ist angenehm und eine perfekte Oase der Ruhe auf langen Reisen. Ich bin sicher, Ihr stimmt mir zu, wenn Ihr es seht.", sourceObjective = "Bringt das Bündel Felle zu Gastwirt Kauth ins Dorf der Bluthufe.", progress = "Ja, Kindchen? Was kann Kauth für Euch tun?\n\nDie Reise von der Mesa hierher kann für manche eine enorme Last, aber für andere eine willkommene Abwechslung sein. Was ist sie wohl für Euch, frage ich mich...", completion = "Ah, die Felle, auf die ich gewartet habe! Danke.\n\nSie kamen schneller als ich erwartet hatte. Ich mache gute Decken für meine Logiergäste daraus.\n\nIhr könnt gern bleiben, so lange Ihr möchtet. Mein Gasthaus ist stets offen und alle Eures Volkes sind willkommen. Und unterschätzt eine angenehme Nachtruhe nicht, ihr kann auf Reisen eine große Bedeutung zukommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1657] = { id = 1657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verpestung von Süderstade", description = "Feiert die Schlotternächte mit Stil... bereitet unseren Feinden in Süderstade Kummer!\n\nNehmt eine dieser speziell angefertigten Stinkbomben. Sie sind mit einem derartig furchtbaren Schrecken gefüllt, dessen Geruch kein Mensch - oder anderes Wesen mit schwachem Gemüt - ertragen kann. Ihr müsst die Stinkbombe direkt ins Herz von Süderstade werfen, damit sie richtig wirken kann. Seid also auf eine Auseinandersetzung mit der Allianz gefasst!\n\nSolltet Ihr diese Aufgabe bewältigt haben, kehrt zu mir zurück... es ist ein Beitrag zu unserer Befreiung!", sourceObjective = "Werft drei Stinkbomben der Verlassenen ins Herz von Süderstade im Hügelland und kehrt zu Ruferin der Dunkelheit Yanka beim Fest des Weidenmanns in Tirisfal zurück.", completion = "Ah, gut gemacht! Ich hoffe die Allianz erstickt an dem fauligen Gift, das wir ihnen verabreicht haben, genauso wie wir den Witz der Versklavung an die Geißel schlucken mussten!\n\nIhr habt die wahre Bedeutung der Schlotternächte erhalten, {name}, ich danke Euch dafür. Lasst mich ein paar Schlotternachtssüßigkeiten mit Euch als zusätzliche Belohung teilen. Ihr werdet sie sicher als eine recht angenehme Abwechslung betrachten!", sourceObjectiveStatus = "unverified-source-field" }
quests[1658] = { id = 1658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bespitzelt das Fest des Weidenmanns", description = "Ich brauche mutige Freiwillige, die nach Tirisfal ziehen und das Fest des Weidenmanns auskundschaften. Ich möchte nicht lügen - diese Mission ist äußerst gefährlich. Die Wachen des Fests werden besonders bösartig sein. Trotzdem, wir müssen in Erfahrung bringen, wie groß das Fest dieses Jahr ist und wie viel Schaden die Verlassenen dieses Mal während der Schlotternächte anrichten.\n\nSolltet Ihr dabei sein, dann geht nach Tirisfal und kundschaftet das Fest aus. Kehrt mit den Informationen zu mir zurück und ich werde für eine angemessene Belohnung sorgen.", sourceObjective = "Macht das Fest des Weidenmanns der Verlassenen in Tirisfal ausfindig. Kehrt zu Unteroffizier Hartman in Süderstade zurück, sobald Ihr Eure Mission erfüllt habt.", completion = "Gut gemacht, {name}. Das Fest des Weidenmanns wird auch noch zukünftig für Ärger sorgen, wenn die abscheulichen Verlassenen weiterhin die Verbliebenen von Lordaeron jagen dürfen. Es ist KEINE passende Ehrung für dieses einst so stolze Königreich, lasst Euch das gesagt sein...\n\nHier sind ein paar Münzen für eventuell benötigte Reparaturen. Ich habe dem Anlass entsprechend auch ein paar Süßigkeiten, die Ihr mögen könntet, mit hinzugepackt. Gruselige Schlotternächte - lasst es uns dafür sorgen, dass es in Southshore so sicher wie möglich bleibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1661] = { id = 1661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant des Adels", description = "Ich grüße Euch erneut, {name}. Ich bin stolzer als jemals zuvor, Euch <Bruder/Schwester> nennen zu können - Euer Engagement ist ein Tribut an uns alle.\n\nDie Zeit ist für mich gekommen, Euch ein wunderbares Geschenk zu übergeben. Wisset aber, dass ich es Euch fürs Erste zwar frei gebe, später jedoch, falls die Zeit es erlaubt, wird dies eine viel größere Herausforderung für alle Paladine sein, die sich dazu entscheiden, meinen Auftrag anzunehmen.\n\nSprecht erneut mit mir und ich werde Euch einen großen Segen gewähren.", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", completion = "Herzlichen Glückwunsch und möge das Licht Euch schützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1665] = { id = 1665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bartlebys Becher", description = "Okay, hier ist mein Becher. Wartet! Lasst mich zuerst austrinken... da haben wir es.", sourceObjective = "Bringt Bartlebys Becher zu Burlwacht.", progress = "Ich habe Euch mit Bartleby kämpfen gesehen. Ordentlich gemacht! Habt Ihr seinen Becher?", completion = "Da ist er! Er wollte ihn nicht hergeben, aber Ihr wart sehr überzeugend. Gut gemacht.\n\nNun zu Eurer Lektion...", sourceObjectiveStatus = "unverified-source-field" }
quests[1666] = { id = 1666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marschall Haggard", description = "Ihr habt einige Kampftechniken gelernt, braucht aber noch eine anständige Waffe. Ich wette, Marschall Haggard könnte Euch helfen, wenn Ihr mit ihm sprecht.\n\nMarschall Haggard lebt in einem Anwesen im Wald von Elwynn, beim Holzfällerlager des Osttals. Er ist jetzt im Ruhestand, hat aber in seiner Laufbahn eine Menge Ausrüstung gesammelt.\n\nLasst ihn wissen, dass ich Euch geschickt habe, und mit etwas Glück hat er eine Waffe für Euch übrig.", sourceObjective = "Sprecht mit Marschall Haggard.", completion = "Wer ist das? Burlguard, seid Ihr das? Ihr müsst etwas näher kommen. Meine Augen sind nicht mehr das, was sie einst waren. Euch so anzuschleichen, ich dachte schon, Ihr wärt ein Gnoll!", sourceObjectiveStatus = "unverified-source-field" }
quests[1667] = { id = 1667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stumpfzahn Jack", description = "Burlwacht hat Euch geschickt, nicht? Ja, ich habe Waffen übrig, aber zuerst habe ich eine Aufgabe für Euch...\n\nVor einer Weile überlistete mich ein Bösewicht der Defias, Stumpfzahn Jack. Es war dunkel und er trug einen Wappenrock von Sturmwind, daher dachte ich, er sei Marschall Dughan. Er sagte, er braucht meinen alten Marschallstern aus Sturmwind und ich gab ihm diesen... dann lachte er und lief weg, ehe ich ihn packen konnte!\n\nBringt mir meinen Stern! Stumpfzahn Jack hat ihn wahrscheinlich in seinem Lager im Süden versteckt.", sourceObjective = "Holt Marschall Haggards Abzeichen aus Stumpfzahn Jacks Lager und kehrt zu Marschall Haggard zurück.", progress = "Habt Ihr meinen Stern? Ich will mir gar nicht vorstellen, welche Unbill Stumpfzahn Jack damit hätte anstellen können.", completion = "Prima, Ihr habt ihn! Ich fürchtete, er sei für immer dahin und würde von den Defias benutzt werden, um sich als Beamte von Stormwind ausgeben zu können. Dank Euch wird es dazu jetzt nicht kommen.\n\nHier einige Waffen, die ich benutzt habe, als ich noch Marshal war. Ich habe sie gut in Schuss gehalten - trefft Eure Wahl!", sourceObjectiveStatus = "unverified-source-field" }
quests[1678] = { id = 1678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vejrek", description = "Wenn Ihr es in den Reihen der Krieger zu etwas bringen wollt, müsst Ihr zäh sein. Ich kann Euch neue Kampftechniken beibringen, aber zuvor müsst Ihr mir beweisen, dass Ihr gegen richtige Feinde bestehen könnt.\n\nVejrek ist der härteste Troll, den Ihr in dieser Gegend findet. Ihn müsst Ihr besiegen. Er hat eine Hütte im Vorgebirge südlich der Höhle der Frostmähnen.\n\nBringt mir Vejreks Kopf, dann weiß ich, dass Ihr Mumm habt.", sourceObjective = "Bringt Vejreks Kopf zu Muren Sturmlanze in Eisenschmiede.", progress = "Seid Ihr in Vejreks Hütte gewesen, {name}? Rieche ich Trollgestank an Euch?", completion = "Vejrek war ein hässlicher Kerl, was? Ordentlich gemacht, {name}! Ihr habt eindeutig das Zeug dazu, also fangen wir mit der Lektion an...\n\nIhr wisst es vielleicht nicht, aber eine starke Verteidigung ist sehr wichtig für einen {class}. Damit besteht er noch gegen Feinde, wenn andere schon niedergeschmettert wären, und genau so einen brauchen Eure Verbündeten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1679] = { id = 1679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Muren Sturmlanze", description = "Hallo, Krieger! Ihr seid viel versprechend, aber dennoch müsst Ihr ein paar Tricks lernen, und Muren Sturmlanze ist genau der Zwerg, der sie Euch beibringen kann.\n\nIhr findet Muren in der Halle der Waffen im Militärviertel von Eisenschmiede. Sprecht mit ihm, wenn Ihr bereit seid zu lernen, was es heißt, ein Krieger zu sein.", sourceObjective = "Sprecht mit Muren Sturmlanze.", completion = "Ah, {name}. Ich hörte, wie die {class} von Dun Morogh Euren Namen erwähnten. Ich hoffe, Ihr habt nicht Eure ganze Zeit in den Brauereien verbracht!", sourceObjectiveStatus = "unverified-source-field" }
quests[1680] = { id = 1680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tormus Tiefenschmied", description = "Jetzt, da Ihr einige Kampftechniken gelernt habt, wird es Zeit, Euch eine anständige Waffe zu beschaffen. Sprecht mit Tormus Tiefenschmied. Er kann Euch eine Waffe machen, die Euch sicher gefallen wird.\n\nIhr findet Tormus hier in Eisenschmiede bei der Großen Schmiede.", sourceObjective = "Sprecht mit Tormus Tiefenschmied.", completion = "Muren hat Euch geschickt, nicht? Ja, ich kann Euch eine hübsche Waffe machen... aber vorher muss ich Euch um einen Gefallen bitten.\n\nSeid unbesorgt. Es ist ziemlich gefährlich und könnte Euren Tod bedeuten; also genau das, was ein {class} sich wünscht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1681] = { id = 1681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenbands Truppenlager", description = "Mein Mentor Sturgy Eisenband hatte ein Lager südlich des Helmsbettsees im östlichen Dun Morogh. Dort lehrte er die Schmiedekunst und er war der Beste.\n\nAber eines Tages brachte ihm einer seiner Schüler eine Ladung mit seltsamem Erz. Meister Eisenband nannte es Umbralerz und konnte es kaum erwarten, damit zu arbeiten. Doch kurz nach der Lieferung griff eine Bande Dunkeleisenzwerge sein Lager an. Sie töteten alle!\n\nBegebt Euch zu Eisenbands Lager, {name}, und rächt den Tod meines Meisters. Und bringt mir die Ladung Umbralerz, die all das auslöste.", sourceObjective = "Bringt eine Ladung Umbralerz zu Tormus Tiefenschmied in Eisenschmiede.", progress = "Habt Ihr Ironbands Areal betreten? Und habt Ihr das Umbralerz gefunden?", completion = "Ihr habt es gefunden! Gut gemacht!\n\nIch hoffe, Ihr habt im Lauf der Suche eine Menge Dunkeleisenzwerge getötet. Ich fürchte, wir werden sie auf Ironbands Areal nicht zum letzten Mal gesehen haben.\n\nAber danke für das Erz, {name}. Ich brenne darauf, seine Eigenschaften herauszufinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[1682] = { id = 1682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen aus grauem Eisen", sourceObjective = "Hier ein paar Waffen, frisch vom Amboss und aus dem neuen Umbralerz gefertigt, das Ihr mir gebracht habt!\n\nBitte, {name}, sucht Euch eine aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[1683] = { id = 1683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorlus Elendshuf", description = "Bevor ich Euch unterrichten kann, müsst Ihr mir Eure Entschlossenheit beweisen.\n\nDer Satyr Vorlus Elendshuf hat einen unserer entlegenen Mondbrunnen südöstlich der Grabhügel von Ban'ethil gefunden. Nun planscht er darin und verseucht das reine Wasser mit seinem Schmutz.\n\nSucht Vorlus beim Mondbrunnen und vernichtet ihn. Bringt mir sein Horn als Beweis, dann beginne ich Eure Fortgeschrittenen-Ausbildung zum Krieger.\n\nDer Weg zum Mondbrunnen ist gut verborgen, {name}, doch wenn Ihr konzentriert und wachsam bleibt, werdet Ihr ihn finden.", sourceObjective = "Bringt das Horn von Vorlus zu Elanaria in Darnassus.", progress = "Habt Ihr das Horn, {name}. Ist unser Mondbrunnen von dem Scheusal Vorlus befreit?", completion = "Gut gemacht, {name}. Gut zu wissen, dass Vorlus besiegt und unser Mondbrunnen gesäubert ist, und schön zu sehen, dass junge {class} erpicht sind, unser geliebtes Teldrassil frei von Verderbnis zu halten.\n\nBeginnen wir jetzt Eure Ausbildung...", sourceObjectiveStatus = "unverified-source-field" }
quests[1684] = { id = 1684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elanaria", description = "Seid gegrüßt, Krieger. Eure Fertigkeiten wachsen, doch Eurer Beruf verlangt mehr, als Ihr für möglich haltet. Um weiter zu kommen müsst Ihr bald einen Lehrer finden.\n\nDie Kriegerin Elanaria weilt in Darnassus auf der Terrasse der Krieger. Sie kann Euch unterweisen.", sourceObjective = "Sprecht mit Elanaria.", completion = "Ich entbiete Euch einen Gruß, {name}. Man hört Euren Namen oft in Darnassus, denn Ihr seid viel versprechend. Doch wir werden sehen, ob Ihr die Willenskraft besitzt, dem Pfad des Kriegers zu folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1685] = { id = 1685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gakins Beschwörung", description = "Läuft es nicht immer so? Ich habe den ganzen Tag nach Euch gesucht und konnte Euch nicht finden, und jetzt, da ich es nicht erwarte, kommt Ihr einfach zu mir spaziert.\n\nIch habe genug Zeit mit der Suche nach Euch vergeudet, daher möchte ich gleich zur Sache kommen. Meister Gakin hat Euch zu weiterer Ausbildung gerufen. Mir scheint, Ihr solltet ihn so rasch wie möglich aufsuchen.\n\nIhr findet ihn im Keller der Taverne 'Zum Geschlachteten Lamm'. Übrigens solltet Ihr diesen Treffpunkt nicht an die große Glocke hängen. Muss ja nicht jeder wissen.", sourceObjective = "Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Sturmwind.", completion = "Höchste Zeit, dass Ihr erscheint. Ich hätte vielleicht einen Tüchtigeren als Remen auf die Suche nach Euch schicken sollen.\n\nEinerlei.\n\nIhr wart zu lange ohne Ausbildung, und ein {class} ohne Ausbildung behält den Kopf nicht lange auf den Schultern.", sourceObjectiveStatus = "unverified-source-field" }
quests[1686] = { id = 1686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eluras Schemen", description = "Ihr habt viel gelernt, {name}. Jetzt fertigen wir Euch eine Waffe an. Die Waffe eines Kriegers.\n\nDazu müsst Ihr nach Dunkelküste reisen.\n\nVor langer Zeit zerschellte ein Schiff auf den Felsen beim Leuchtturm von Auberdine. Viele Kisten Eluniterz sanken auf den Meeresgrund.\n\nAls Erstes müsst Ihr den Wächter des Elunits besiegen, Eluras Schemen. Sie war einst Kapitän des Schiffes und verfluchte sich selbst dazu, für alle Zeiten in der Tiefe zu verweilen und ihre Schiffsladung zu schützen. Besiegt sie, nehmt Ihr das Medaillon ab und sammelt die verlorenen Elunitkisten ein.", sourceObjective = "Bringt 8 Ladungen Eluniterz und das Medaillon von Elura zu Elanaria in Darnassus.", progress = "Habt Ihr Eluras Schemen besiegt, {name}? Und habt Ihr das verlorene Eluniterz?", completion = "Tapfer, tapfer, {name}.\n\nIhr habt Eluras Schemen den wohlverdienten Frieden gegeben. Aus dem gewonnenen Elunit werden wir eine prima Waffe für Euch machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1687] = { id = 1687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der gruselige Leuchtturm", description = "Abends erzählen uns die Matronen manchmal Gruselgeschichten. Die sind spitze! Einmal haben sie uns von einem Geist erzählt, der in einem Leuchtturm in Westfall spukt. Er soll einmal ein Piratenkapitän gewesen sein, dessen Schiff ihm von anderen Piraten weggenommen wurde. Wow!\n\nKönnen wir uns bitte den Leuchtturm in Westfall anschauen? Ich will nachgucken, ob der Geist des Kapitäns noch immer dort ist! Ich bleibe auch immer nah bei Euch. Ich renn' auch bestimmt nicht weg oder so was.", sourceObjective = "Besucht mit Eurem Schützling den Leuchtturm an der Küste von Westfall.", progress = "Sind wir bald da?", completion = "Wow! Das war ja ein richtiger Geist! Das war ja der Hammer - Ich kann es kaum erwarten, das meinen Freunden im Waisenhaus zu erzählen. Captain Grayson... er sah sogar wie ein Pirat aus! Wenn ich mal groß bin, möchte ich auch ein Geisterpirat sein!\n\nDanke, dass du Westfall mit mir besucht hast, {name}. Ich weiß, da waren viele gefährliche Wesen in der Wildnis von Westfall und ich hoffe das ich dir nicht zuviel Sorgen bereitet habe. Du bist der Beste!", sourceObjectiveStatus = "unverified-source-field" }
quests[1688] = { id = 1688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surena Caledon", description = "Ich hatte eine Studentin namens Surena Caledon. Sie stand da, wo Ihr jetzt steht, und brannte darauf, die Hexenmeistermagie zu lernen, und ihr Talent war nicht von schlechten Eltern. Mehr als das, sie war jung und eine wahre Augenweide. Hätte ich sie doch nur damals schon durchschaut, die falsche Schlange!\n\nDas diebische Weib brannte mit einem Schläger durch, Erlan Tragmehr. Ihr Verlust ist unbedeutend, aber ich schenkte ihr einen Blutsteinhalsschmuck, den ich wiederhaben muss.\n\nIhr Leben hat keine Bedeutung mehr für mich. Ihr findet sie bei Brackbrunns Kürbisbeet. Bringt wieder, was mir gehört.", sourceObjective = "Beschafft Surenas Halsreif für Gakin den Dunkelbinder in Sturmwind.", progress = "Selbst die Alten und Weisen können sich von Jugend und Schönheit blenden lassen, {name}. Ihr tätet gut daran, diesen Rat Euer ganzes Leben lang nicht zu vergessen.", completion = "Surena war begabt, aber nicht so sehr, dass sie die Hexenmeistermagie selbst gemeistert hätte. Ein Jammer, dass ein Talent verschwendet wird, aber manchmal geht es nicht anders.\n\nIch hoffe, meine Investition in Euch wird andere Resultate zeigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1689] = { id = 1689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Ihr habt meinen Halsreif zurückgebracht und Surena bezwungen und damit gezeigt, dass Ihr mindestens ebenso begabt seid, wie sie es war.\n\nNichtsdestoweniger kann ich Euch versichern, dass Ihr dringend Ausbildung benötigt. Ihr meistert den Fluss der Magie, ja, aber zu einem Hexenmeister gehört viel mehr als das.\n\nIch zeige Euch, wie man einen Leerwandler beherrscht, aber bevor ich das kann, müsst Ihr einen am Beschwörungskreis herbeirufen und mit allen Euch zur Verfügung stehenden Waffen unterwerfen. Benutzt die Magie dieses Halsschmuckes unten am Beschwörungskreis.", sourceObjective = "Beschwört mithilfe des Blutsteinhalsreifs einen Leerwandler, unterwerft ihn und bringt dann den Blutsteinhalsreif zu Gakin dem Dunkelbinder in Sturmwind zurück.", progress = "Ich kann Euch erst zeigen, wie man einen Leerwandler kontrolliert, wenn Ihr einen beschworen habt.", completion = "Ihr habt Eure Sache besser als erwartet gemacht, {name}, aber so gut, wie ich gehofft hatte. Jetzt könnt Ihr lernen, wie Ihr Euren unterworfenen Leerwandler beherrscht, einen Verbündeten, der Euch in den bevorstehenden Prüfungen sicher höchst nützlich ist.\n\nIm Augenblick kann ich Euch nichts mehr beibringen, bin aber noch lange nicht fertig mit Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1690] = { id = 1690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wüstenläufergerechtigkeit", description = "Ihr da! Für Euch ist es an der Zeit, ein großer Helfer der Gadgetzan Water Company zu sein.\n\nDie Wüstenläufernomaden draußen in der Tanariswüste haben fast alle Brunnen erobert! Ohne Zugang zu den Brunnen wird unser Wasservorrat im Handumdrehen schwinden. Wenn Ihr Euch unsere Dankbarkeit verdienen wollt, dann helft uns, diese Nomaden der Gerechtigkeit zuzuführen!\n\nBegebt Euch von hier Richtung Osten und schaltet zehn Banditen und Diebe der Wüstenläufer aus und meldet Euch dann umgehend wieder bei mir. Gerechtigkeit wartet auf keinen Mann... keinen Goblin... ach, legt einfach los!", sourceObjective = "Erledigt 10 Banditen und Diebe der Wüstenläufer östlich von Gadgetzan und meldet Euch dann wieder bei Chefingenieur Bilgenritzel.", completion = "Tja, das nenne ich Effizienz! Ihr habt uns geholfen, die Nomaden so weit zu dezimieren, dass wir uns jetzt überlegen können, wie wir die Wasserbrunnen zurückerobern.\n\nDie Gadgetzan Water Company dankt Euch für Eure Hilfe, aber wir sind mit diesen stinkenden Nomaden noch lange nicht fertig. Hört gut zu - das benötigen wir als Nächstes ...", sourceObjectiveStatus = "unverified-source-field" }
quests[1691] = { id = 1691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr Wüstenläufergerechtigkeit", description = "Wir müssen uns jetzt die stärkeren Ränge der Wüstenläufernomaden vornehmen. Ihr habt bisher gute Arbeit geleistet, aber wenn wir diese Brunnen zurückerobern wollen, dann wäre es gut, wenn uns dabei so wenig Nomaden wie möglich gegenüberstünden!\n\nDieses Mal müsst Ihr ihre Schurken, Auftragsmörder und Schattenmagier erledigen. Ihr werdet sie östlich und südöstlich von hier finden.\n\nIch werde Euch nichts vormachen - das ist eine schlimme Bande. Tut dies für uns, dann sind wir auf dem besten Weg, uns das zurückzuholen, was rechtmäßig uns gehört!", sourceObjective = "Erledigt 10 Schattenmagier der Wüstenläufer, 8 Schurken der Wüstenläufer und 6 Auftragsmörder der Wüstenläufer für Chefingenieur Bilgenritzel in Gadgetzan.", progress = "Na, konntet Ihr diese Nomaden ausschalten, wie ich Euch gebeten hatte? Die Gadgetzan Water Company entwickelt Pläne, die auf Eurem Erfolg hier basieren! Lasst uns jetzt nicht im Stich...", completion = "Erstklassige Arbeit, {name}... erstklassig! Ihr habt die Nomadenbevölkerung so weit dezimiert, dass wir tatsächlich den Kampf gegen sie aufnehmen können!\n\nFalls Ihr es noch nicht getan habt, dann sprecht mit Leitungshahnmaschinist Luglunket hier; er vergibt ein Kopfgeld für jeden Wasserbeutel eines Wüstenläufers, über den Ihr gestolpert seid, während Ihr diese Nomaden der Gerechtigkeit zugeführt habt!", sourceObjectiveStatus = "unverified-source-field" }
quests[1692] = { id = 1692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmied Mathiel", description = "Ich habe das Elunit, das Ihr gesammelt habt, in eine Kiste gelegt. Bringt sie zum Schmied Mathiel, er wird eine Elunitwaffe für Euch anfertigen.\n\nMathiel ist im Süden, an der anderen Seite dieses Gebäudes zu finden.", sourceObjective = "Bringt die Kiste mit Elunit zu Schmied Mathiel.", progress = "Seid gegrüßt, junger {class}. Wie kann ich Euch mit meinen Fertigkeiten dienlich sein?", completion = "Ah, Eluniterz. Ein Metall, mit dem sich gut arbeiten lässt, denn es wurde von der Göttin Elune persönlich gesegnet. Es wäre mir eine Ehre, Waffen daraus herzustellen.\n\nBitte wartet, während ich arbeite...", sourceObjectiveStatus = "unverified-source-field" }
quests[1693] = { id = 1693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen aus Elunit", sourceObjective = "{name}, ich habe mit dem Elunit, das Ihr mir brachtet, diese Waffen hergestellt. Bitte nehmt die, die Euch am angenehmsten ist.\n\nUnd ich muss Euch danken. Es ist eine Ehre und Freude, mit Elunit zu arbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1698] = { id = 1698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yorus Gerstenbräu", description = "Yorus Gerstenbräu hat eine Herausforderung für alle tüchtigen Krieger der Allianz verkündet. Er wartet im Gasthaus von Seenhain im Rotkammgebirge und verspricht jedem, der seine Prüfung besteht, eine hohe Belohnung.", sourceObjective = "Sprecht mit Yorus Gerstenbräu.", completion = "Ha! Ihr habt von meiner Herausforderung gehört, richtig?\n\nSetzt Euch und hört zu. Bestellt ein Getränk und genießt es... es könnte Euer Letztes sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1699] = { id = 1699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Rethbanspießrutenlauf", description = "Ich nenne meine Herausforderung den Rethbanspießrutenlauf. Um die Prüfung zu bestehen, müsst Ihr lediglich die Rethbanhöhlen betreten, bis zur ersten Gabelung gelangen und hierher zurückkehren. Ganz einfach! Aber es gibt da ein paar Hürden...\n\nIhr müsst binnen einer Stunde zurück sein.\n\nGanze Heerscharen von Rotkammgnollen versperren den Weg.\n\nVor dem Start müsst Ihr einen Schluck des Stammgetränks meiner Familie zu Euch nehmen: Gerstenbräu!\n\nWas sagt Ihr dazu? Die Rethbanhöhlen liegen im Vorgebirge nördlich von Seenhain. Seid Ihr bereit, am Rethbanspießrutenlauf teilzunehmen?", sourceObjective = "Betretet die Rethbanhöhlen, geht bis zur ersten Gabelung und kehrt innerhalb der zulässigen Zeit zu Yorus Gerstenbräu zurück.\n\nIhr dürft nicht sterben und Euren Geist befreien.", completion = "Ihr habt es geschafft! Gut gemacht! Ein dreifach Hoch für {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[1700] = { id = 1700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimand Elmore", description = "Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte. Sie muss zu Grimand Elmore geschickt werden. Er ist hier im Zwergendistrikt, im Waffenladen.\n\nUnd duckt Euch, wenn Ihr ihm die gebt. Er bildet sich ungeheuer viel auf seine Fertigkeiten ein. Es wird ihm nicht gefallen, etwas von mir zu lernen...", sourceObjective = "Bringt Furens Notizen zu Grimand Elmore.", progress = "Hallo und schönen Tag. Wie kann ich Euch dienlich sein?", completion = "Furen hat das geschrieben? Wie kann er es wagen! Ich habe ihm all das beigebracht, was er weiß! Unerhört, dass er glaubt, er könnte mich etwas lehren! Unerhört!\n\nHm... aber in diesen Notizen steht etwas, das ich gern versuchen würde...", sourceObjectiveStatus = "unverified-source-field" }
quests[1701] = { id = 1701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuergehärteter Panzer", description = "Ich gab Euch einen guten Schild, aber dabei muss es nicht bleiben. Ich kenne das Geheimnis, wie man extrem harte Panzerrüstungen herstellt. Es ist nicht leicht und erfordert sehr rare Materialien, aber wenn Ihr bereit seid, die Kleinarbeit zu machen, fertige ich ein Teil für Euch an.\n\nWas sagt Ihr dazu, {name}? Wenn Ihr Euch der Herausforderung gewachsen fühlt, gebe ich Euch eine Liste, was Ihr beschaffen müsst und wo Ihr es bekommt.", sourceObjective = "Sammelt die Materialien, die Furen Langbart benötigt, und bringt sie zu ihm nach Sturmwind.", progress = "Wie läuft die Suche, {name}? Habt Ihr die Materialien?", completion = "Ihr habt alles? Erstaunlich! Ich hatte befürchtet, diese Schimären würden Euch fressen!\n\nDann lasst uns mal mit der Rüstung anfangen...", sourceObjectiveStatus = "unverified-source-field" }
quests[1702] = { id = 1702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schildschmied", description = "Ihr habt echt gezeigt, aus welchem Holz Ihr geschnitzt seid, als Ihr am Rethbanspießrutenlauf teilgenommen habt, {name}. Und ich stehe zu meinem Wort. Ihr bekommt die versprochene Belohnung...\n\nAber sie ist in Sturmwind.\n\nSprecht mit meinem Freund Furen Langbart im Zwergendistrikt von Sturmwind. Er ist der beste Schildschmied, den Ihr je gesehen habt, und er schuldet mir einen großen Gefallen.\n\nHier, bringt Furen dieses Fässlein mit Gerstenbräu und bittet ihn um einen Schild. Er wird Euch einen schönen geben.", sourceObjective = "Bringt das Fässlein mit Gerstenbräu zu Furen Langbart.", progress = "Hallo! Trockene Zeiten, findet Ihr nicht auch?", completion = "Ah, Gerstenbräu. Erstklassiges Gesöff! Ihr seid also bei Yorus gewesen, hm?\n\nIch kann Euch einen Schild machen, ja Sir! Einen Besseren werdet Ihr nicht finden, ungelogen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1703] = { id = 1703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathiel", description = "Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte. Sie muss zum Schmied Mathiel geschickt werden. Er lebt in Darnassus. Das ist weit weg, aber ich bin sicher, er wird dankbar sein, wenn er erfährt, was ich gelernt habe.", sourceObjective = "Bringt Furens Notizen zu Mathiel.", progress = "Ich entbiete Euch einen Gruß, {class}.", completion = "Das ist interessant, wirklich sehr interessant. Mein Zwergen-Kollege Furen hat da eine grandiose Entdeckung gemacht!\n\nDanke, {name}. Es wäre mir eine Ehre, seine neuen Techniken selbst anzuwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[1704] = { id = 1704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klockmort Spannersplint", description = "Ich fertigte eine Kopie meiner Notizen über die Techniken an, die ich lernte, während ich Eure Rüstung herstellte, und brauche jemanden, der sie zu Klockmort Spannersplint bringt. Er ist ein gnomischer Schmied in Eisenschmiede, und wenn er herausfindet, was ich herausgefunden habe...Ich wette, er reißt sich vor Aufregung selbst den Bart aus.", sourceObjective = "Bringt Furens Notizen zu Klockmort Spannersplint.", progress = "Guten Tag, Morgen oder Abend. Ich kann es von hier unten nicht erkennen. Bringt Ihr mir Arbeit?", completion = "Oh je! Diese Notizen sind erstaunlich! Und mehr noch... sie sind unglaublich und phantastisch und machen meine Knie ganz weich!\n\nFuren hatte einen Durchbruch! Einen echten Durchbruch! Ich kann es kaum erwarten, seine neue Technik zu erproben!", sourceObjectiveStatus = "unverified-source-field" }
quests[1705] = { id = 1705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennendes Blut", description = "Ich gebe nur ungern zu, dass Furen tatsächlich etwas gefunden haben könnte. Aber um ganz sicher zu sein, muss ich seine Techniken an einem neuen Rüstungsteil erproben. Wenn Ihr mir mit den Materialien helft, {name}, könnt Ihr die Rüstung haben.\n\nUm die Rüstung herzustellen benötige ich Proben von brennendem Blut und brennendem Felsen.\n\nDie findet man meines Wissens nur im Dämmerwald. Die Worgs der Nachtheuler in der Mine von Rolands Verdammnis haben brennendes Blut, und Bauchreißer, ihr Anführer, wird den Fels haben.\n\nMöge das Schicksal Euch Schnelligkeit gewähren {name}.", sourceObjective = "Bringt 20 Phiolen brennendes Blut und 1 brennenden Fels zu Grimand Elmore in Sturmwind.", progress = "{name}, habt Ihr das brennende Blut und den Fels? Ich brauche sie, um die Rüstung zu vollenden.", completion = "Saubere Arbeit! Wenn Ihr mich jetzt entschuldigen wollt, ich habe zu tun...", sourceObjectiveStatus = "unverified-source-field" }
quests[1706] = { id = 1706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimands Rüstung", sourceObjective = "Ich kann es kaum glauben! Furens Technik war ein Erfolg. Seine Rüstung sollte ungeheuren Belastungen standhalten können.\n\nDa habt Ihr sie, {name}. Und habt Dank. Ich hätte nicht an Furens Entdeckung geglaubt, wenn Ihr nicht die Materialien gesammelt hättet, die ich für einen Test brauchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[1707] = { id = 1707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserbeutelkopfgeld", description = "Seid gegrüßt, {name}, mein Name ist Lochbeutel, und wir haben einen wichtigen Auftrag für Euch, wenn Ihr bereit seid! Hussah!\n\nNichts würde mir als altgedientem Leitungshahnmaschinisten mehr gefallen, als Euch jeden Wasserbeutel eines Wüstenläufers abzunehmen, den Ihr draußen in der Wüste findet. Das ist ja ohnehin unser Wasser - die Nomaden haben es einfach nur gestohlen! Die Gadgetzan Water Company bietet Euch ein offizielles Überlebenspaket für jeweils fünf, die Ihr abliefert. Am wichtigsten ist aber, dass Ihr Gadgetzan selbst helft!", sourceObjective = "Bringt Leitungshahnmaschinist Lochbeutel in Gadgetzan 5 Wasserbeutel eines Wüstenläufers.", progress = "Habt Ihr die fünf Wasserbeutel eines Wüstenläufers, die wir benötigen? Falls Ihr sie habt, dann gehört das Gadgetzan Water Company-Care-Paket, Modell 103-XB, Euch!", completion = "Hervorragend - je mehr Wasserbeutel wir wiederbeschaffen können, desto weiter sind wir von einer Katastrophe entfernt! Bringt mir mehr und ich werde Euch für jeweils fünf Wasserbeutel belohnen, die Ihr mir bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1708] = { id = 1708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenkoralle", description = "Ich möchte Furen Langbarts neue Techniken an einer eigenen Rüstung erproben. Und weil Ihr Furen geholfen habt und er mir, sollt Ihr die Rüstung bekommen, wenn sie fertig ist!\n\nUm das Teil zu beenden, brauche ich eine spezielle Koralle, Sengkoralle. Sie wächst nur an einem Ort - an der Küste südlich des Hafens von Menethil im Sumpfland.\n\nBringt mir genügend Sengkoralle und ich mache mich gleich an die Arbeit. Und beeilt Euch, {name}. Ich brenne so sehr darauf, endlich anzufangen, dass meine Zehen jucken!", sourceObjective = "Bringt 20 Ladungen Sengkoralle zu Klockmort Spannersplint in Eisenschmiede.", progress = "Hallo, hallo, {name}. Habt Ihr die Sengkoralle? Ich will endlich arbeiten!", completion = "Das sind sie. Gut gemacht! Und jetzt lasst mich dies verhütten und zerhämmern, damit ich Furens Technik selbst anwenden kann. Mal sehen, was dann passiert!\n\nOh je, oh je! Ich weiß genau, diese Rüstung wird sehr, sehr hart!", sourceObjectiveStatus = "unverified-source-field" }
quests[1709] = { id = 1709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klockmorts Kreation", sourceObjective = "Hier ist Eure Rüstung, {name}. Furens Prozess hat ausgezeichnet funktioniert! Perfekt! Wunderbar, ehrlich!\n\nMan könnte mit einer Belagerungsmaschine über diese Rüstung fahren und sie würde wieder ihre alte Form annehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1710] = { id = 1710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sonnenverbrannte Schalen", description = "Mein Kollege, Furen Langbart, hat eine Entdeckung gemacht, die ich schnellstens ausprobieren möchte. Ich möchte sie an einer neuen Rüstung erproben, an der ich forsche, denn ich glaube, Furens Techniken werden grandiose Ergebnisse erzielen.\n\nWerdet Ihr mir helfen? Wenn Ihr sammelt, was ich zur Herstellung der Rüstung brauche, fertige ich für Euch auch eine an.\n\nIch brauche sonnenverbrannte Eierschalen der Steilhangwyvern, die am Steilhang in Tausend Nadeln hausen. Sucht unter den Nestern nach den Schalen und kommt zu mir zurück, wenn Ihr eine ausreichende Menge habt.", sourceObjective = "Bringt 20 sonnenverbrannte Schalen zu Mathiel in Darnassus.", progress = "Habt Ihr die Schalen, {name}? Sie sind recht stark und können zu einem Lack verarbeitet werden, mit dem ich die Kettenglieder meiner neuen Panzerrüstung überziehe.", completion = "Ah, danke. Dies wird großartig funktionieren!\n\nIch werde sofort mit der Rüstung beginnen...", sourceObjectiveStatus = "unverified-source-field" }
quests[1711] = { id = 1711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathiels Rüstung", sourceObjective = "Ich habe Eure Rüstung vollendet und bin recht zufrieden. Furens neue Techniken passen ausgezeichnet zu meinen. Ich bin sicher, diese Rüstung wird sehr widerstandsfähig sein.\n\nDanke, {name}. Möge sie Euch in künftigen Kämpfen nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1712] = { id = 1712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cyclonian", description = "Ich beobachte diesen Ort seit Ewigkeiten. Ich beobachte, damit ich eines Tages den großen Cyclonian fallen sehen kann. Doch ich fand noch keinen Helden, der den Windlord besiegen konnte.\n\nVielleicht seid Ihr dieser Held.\n\nBeweist es mir. Sammelt die Gegenstände, die ich brauche, um Cyclonian zu beschwören, dann weiß ich, dass Ihr ein großer Krieger seid. Vielleicht könnt Ihr ihn besiegen und sein Wirbelherz bekommen.\n\nWenn ja, übertrage ich die Macht des Herzens in eine Waffe und schenke Euch diese Waffe.\n\nHier ein Pergament mit den Gegenständen, die ich benötige.", sourceObjective = "Bringt die Gegenstände auf Bath'rahs Pergament zu Bath'rah dem Windbehüter in Alterac.", progress = "Habt Ihr die Gegenstände, {name}? Wenn Ihr sie sammelt, habe ich den Beweis, dass Ihr genügend Kraft besitzt, um es mit Cyclonian aufzunehmen.", completion = "Ihr habt die Gegenstände für meinen Zauber gesammelt und mir Eure Kraft und Geschicklichkeit bewiesen. Doch das nächste Stadium Eurer Aufgabe ist noch gefährlicher.\n\nHoffen wir, dass Eure Kraft nicht nachlässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1713] = { id = 1713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beschwörung", description = "Ich bin bereit, das Ritual zur Beschwörung Cyclonians durchzuführen. Wenn er beschworen ist, müsst Ihr ihn besiegen und sein Wirbelherz nehmen. Ich werde es benutzen, um eine Waffe mit Cyclonians Macht zu stärken.\n\n{name}, seid Ihr bereit, dem Windlord zu trotzen?", sourceObjective = "Bringt das Wirbelherz zu Bath'rah dem Windbehüter.", progress = "{name}, ich muss das Wirbelherz haben!", completion = "Ihr habt es geschafft! Ihr habt Cyclonian besiegt und das Wirbelherz bekommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1714] = { id = 1714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenz der Verbannung", progress = "Der Kessel blubbert. Seine Dämpfe locken...", completion = "Die Glücksbringer sinken langsam in die Tiefen des Kessels...\n\nEine große Luftblase steigt zur Oberfläche der Flüssigkeit und zerplatzt...\n\n... Und ein brodelnder Klumpen geschmolzenen Felsens ist zu sehen." }
quests[1715] = { id = 1715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Geschlachteten Lamm", description = "Hmph. Früher wurden alle Hexenmeister in Khaz Modan unter der Aufsicht der Meister von Gnomeregan ausgebildet, doch jetzt, wo wir gezwungen wurden, in dieses Rattenloch in Eisenschmiede zu ziehen und Magni beschloss, uns genau zu beobachten, sind wir gezwungen, unsere Novizen zur Ausbildung nach Sturmwind zu schicken.\n\nZum Glück ist Gakin kein Tölpel, daher werdet Ihr lernen, was Ihr wissen müsst. Dennoch bringt es mein Blut zum Kochen!\n\nWie auch immer, Ihr findet Gakin im Keller des Geschlachteten Lamms in Sturmwind.", sourceObjective = "Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Sturmwind.", completion = "Blackwrench schickt Euch, richtig? Die verdammten {class} in Ironforge sollten mal ihre Köpfe benutzen. Der Platz und die Lehrer in Stormwind sind begrenzt. Durch den ständigen Zustrom werden wir früher oder später Aufmerksamkeit erregen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1716] = { id = 1716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlinger der Seelen", description = "Ein Sayaad ist ein Verschlinger der Seelen, Bezwinger des Willens, Versucher der Herzen. Er kennt nur das Böse.\n\nSchlüpfrige Geschichten bezeichnen diese Dämonen mit ihren geläufigeren Namen: Sukkubus in der weiblichen und Inkubus in der männlichen Gestalt.\n\nIhr braucht einen Anreiz, um die Kreatur anzulocken. Mit einem Symbol der Liebe als Köder wird sie gewiss auf Euren Ruf reagieren. Besiegt den Dämon und macht ihn zu Eurem Werkzeug.\n\nEs wird allerdings schwer sein, etwas dieser Art zu finden. Ihr solltet mit dem Seher Takar sprechen. Ihr findet ihn im Brachland von Kalimdor nahe dem Camp Taurajo.", sourceObjective = "Sprecht mit Takar dem Seher im Brachland.", completion = "War Eure Reise beschwerlich, {name}? Ihr kommt von weit her, um mit mir zu sprechen. Doch habt keine Furcht, ich weiß, warum Gakin Euch geschickt hat, und es war weise von ihm, denn ich kann Euch bei der Suche helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1717] = { id = 1717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gakins Beschwörung", description = "{name}! Ich hätte nicht erwartet, Euch in der Gegend zu sehen, wurde aber angewiesen, nach Euch Ausschau zu halten.\n\nHöchste Zeit, dass Eure Ausbildung fortgesetzt wird. Beim nächsten Besuch in Sturmwind solltet Ihr bei Gakin reinschauen. Er wird Euch erwarten.", sourceObjective = "Meldet Euch bei Gakin dem Dunkelbinder im Magierviertel von Sturmwind.", completion = "Ich bin froh, dass jemand Eurer habhaft wurde, {name}. Ich fürchtete schon das Schlimmste. Nach der vielen Zeit, die wir in Euch investiert haben, wäre es ein Jammer, Euch zu verlieren.\n\nAber wir können später reden. Wichtig ist jetzt nur Eure Ausbildung.", sourceObjectiveStatus = "unverified-source-field" }
quests[1718] = { id = 1718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Inselbewohner", description = "Euer Ruf als Krieger wächst, {name}. Jetzt ist es Zeit, Euch mit Euresgleichen zu messen und festzustellen, was Ihr könnt.\n\nVor der Küste des Brachlandes, südlich von Ratschet, liegt eine Insel. Sie heißt Prügeleiland und ist ein Treffpunkt für Krieger.\n\nGeht dorthin und kämpft.\n\nSprecht mit Klannoc Macleod, dem obersten Krieger der Insel. Wenn er Euch für würdig erachtet, wird Klannoc Euch weiter auf dem Pfad des Kriegers führen.\n\nUm das Prügeleiland zu erreichen, müsst Ihr nach den Sandbankuntiefen entlang der Händlerküste suchen.", sourceObjective = "Sprecht mit Klannoc Macleod.", completion = "Hallo, {class}. Schön, dass Ihr auf das Prügel-Eiland gekommen seid. Hoffentlich gefällt es Euch hier...", sourceObjectiveStatus = "unverified-source-field" }
quests[1719] = { id = 1719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ringkampf", description = "Wenn Ihr von mir lernen wollt, müsst Ihr zuerst den Ringkampf absolvieren. Das ist eine Herausforderung hier auf dem Prügeleiland, an der wir aufstrebende Krieger teilnehmen lassen, die sich für gut genug halten. Wenn Ihr gewinnt, dann weiß ich, dass Ihr es tatsächlich seid.\n\nGeht als Erstes mitten in diese Menge dort und stellt Euch auf den Rost. Dadurch weiß Twiggy Flachkopf, dass Ihr bereit seid, und er schickt Euch Herausforderer.\n\nWenn Ihr alle Herausforderer besiegt habt, ruft er Big Will. Tötet Big Will und kehrt innerhalb der von uns gesetzten Frist zu mir zurück.", sourceObjective = "Tötet Big Will und sprecht mit Klannoc Macleod auf dem Prügeleiland.", progress = "Habt Ihr die Herausforderung absolviert?", completion = "Gut gemacht, {name}. Ihr habt den Ringkampf bestanden!\n\nIhr seid ein würdiger {class}. Es ist mir eine Ehre, Euch zu unterrichten...", sourceObjectiveStatus = "unverified-source-field" }
quests[1738] = { id = 1738, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzholz", description = "Als Vorbereitung auf Eure Ankunft nutzte ich mein zweites Gesicht, um über die Welt und hinter die Nebel der Zeit zu schauen. Ich habe herausgefunden, wonach Ihr sucht.\n\nIm Krieg der Ahnen fielen zwei Liebende gemeinsam im Kampf. Wo sie ihren letzten Seufzer taten, wuchs ein als Herzholz bekannter Baum als Symbol ihrer unsterblichen Liebe.\n\nEr sollte genügen, um einen Sukkubus anzulocken. Ihr findet ihn in den Ruinen von Ordil'Aran im nordwestlichen Teil des Waldes vom Eschental.", sourceObjective = "Holt das Herzholz aus dem Eschental und bringt es zu Gakin dem Dunkelbinder im Magierviertel von Sturmwind.", progress = "War Eure Suche erfolgreich, {name}?", completion = "Ja, ich sehe, dass das voll und ganz genügt, lasst mich nur einen Moment damit arbeiten...\n\nTakar ist ein recht findiger Bursche, nicht? Wenn ich ihn nur überreden könnte, wieder in die Zivilisation zu kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1739] = { id = 1739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Mit dem Herzholzkern könnt Ihr einen Zauber am Beschwörungskreis unten in der Gruft wirken und ein Portal öffnen, durch das der Sukkubus kommen kann.\n\nSeid vorsichtig, {name}, Sukkuben haben schon den stärksten Geist unterjocht.\n\nWenn Ihr ihn bezwungen und in die Leere zurückgeschickt habt, kommt wieder zu mir, dann zeige ich Euch, wie Ihr ihn rufen und kontrollieren könnt.", sourceObjective = "Beschwört mithilfe des Herzholzkerns einen Sukkubus, unterwerft ihn und bringt dann den Herzholzkern zu Gakin dem Dunkelbinder im Geschlachteten Lamm zurück.", progress = "Manchmal frage ich mich, ob Surena nicht ein verkleideter Sukkubus war, der geschickt wurde, um meinen Geist zu verwirren... Ha! Ich glaube, ich überschätze sie doch ein bisschen...", completion = "Gut gemacht, gut gemacht, {name}. Wie ich sehe, haben wir gut daran getan, Euch auszubilden. Eure Leistung enttäuschte uns nicht...\n\nIch habe keine Bedenken, Euch zu zeigen, wie Ihr Euren neu gebundenen Sukkubus kontrollieren könnt. Passt gut auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[1740] = { id = 1740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kugel von Soran'ruk", description = "Wenn Dämonen der Legion in Ungnade fallen, wird ihr Geist in Kugeln gefangen und an ihre Magier und Hexenmeister verteilt.\n\nViele wurden von ihren Bediensteten in Azeroth getragen. Selbst als Bruchstücke besitzen sie die Macht der darin gefangenen Dämonen.\n\nDie Kugel von Soran'ruk wurde in zwei Teile zerbrochen. Eines davon wurde abermals zerbrochen und von den Akolythen des Schattenhammers in der Tiefschwarzen Grotte benutzt. Das andere, größere Teil besaß ein Hexer in der Burg Schattenfang. Sucht sie, dann kann ich sie zusammenfügen...", sourceObjective = "Sucht 3 Fragmente von Soran'ruk und 1 großes Fragment von Soran'ruk und bringt sie zu Doan Karhan im Brachland.", progress = "Ich brauchte viele Jahre, um die Teile der Kugel von Zargain zu sammeln, aber sie hat mir gute Dienste geleistet, was die Kugel von Soran'ruk für Euch gewiss auch tun wird.", completion = "Ja... Die Kugel war nicht allzu sehr fragmentiert, fast alle Stücke sind da. Es ist einfach, sie zusammenzufügen und Soran'ruk wieder heil zu machen.\n\nIch habe mein Leben dem Studium der Kugeln der Brennenden Legion und ihrer Neugestaltung gewidmet. Ihr habt mir einen Gefallen damit getan, diese Stücke zum Zweck des Studiums zu sammeln, und ich werde sie Euch zurückgeben - vollständig wiederhergestellt - in einer Gestalt Eurer Wahl.", sourceObjectiveStatus = "unverified-source-field" }
quests[1758] = { id = 1758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Kabale", description = "Mehr als ein einfacher Beschwörungskreis wird erforderlich sein, um einen Teufelsjäger als Herausforderer für Euch herzubringen.\n\nMeine drei Akolythen und ich helfen, die magischen Kreise zu erschaffen. Ihr benötigt eine Kopie des Folianten der Kabale, der seit geraumer Zeit als verschollen gilt. Er wurde von der ersten Gruppe Hexenmeister geschrieben, die ohne Unterstützung einen Teufelsjäger beschwörten.\n\nVielleicht kann Krom Starkarm Euch dabei helfen. Heute ist er ein fahrender Hexenmeister, hortet alte Schriften und hängt in der Bibliothek von Eisenschmiede herum.", sourceObjective = "Sprecht mit Krom Starkarm in Eisenschmiede.", completion = "Foliant der Kabale? Hmm... kommt mir bekannt vor. Aber ich habe ihn noch nie gesehen, und glaubt mir - ich erinnere mich an jedes Buch, das ich gelesen habe.\n\nHmm...\n\nAh, ja! Ich habe Hinweise darauf in Bibliothek-Katalogisierungen gesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1778] = { id = 1778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Ich werde bald Pläne für meine Heimkehr machen. Hoffentlich geht es Stephanie gut in Sturmwind. Ich kann es kaum erwarten, sie wiederzusehen. Auf bald, {class}.", sourceObjective = "Sprecht mit Tiza Kriegshammer in Eisenschmiede.", completion = "Ihr seid also so schnell wieder hier, hm? Und was, sagt an, habt Ihr in der Zeit, die Ihr in der Ferne verbrachtet, denn erreicht?\n\nKonntet Ihr bei einem edlen Unterfangen helfen? Vielleicht habt Ihr den Wert der Barmherzigkeit gelernt, oder etwas mehr über Eure Verpflichtung gegenüber den Bürgern von Azeroth erfahren. Sagt mir, wem Ihr geholfen habt, und wie... Beeindruckend, {name}, das sind gewiss Taten von einem, der dem Licht folgt.\n\nSolche Opfer werden im Laufe der Zeit immer belohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1779] = { id = 1779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Ich möchte, dass Ihr das nehmt, {name}. Es heißt Symbol des Lebens.\n\nIhr habt bewiesen, dass Ihr barmherzig und geduldig seid. Jetzt sollt Ihr mir zeigen, wie versiert Ihr geworden seid, was Gefecht und Macht angeht.\n\nMein Mann Muiredon kehrte jüngst von einer Begegnung mit Dunkeleisenzwergen zurück und kam gerade noch mit dem Leben davon - er ist da drüben und einer unserer Priester heilt schon seine Wunden.\n\nNehmt das Symbol und redet mit ihm. Wenn Ihr ihm helfen könnt, dann sprechen wir uns bald wieder. Möge das Licht auf Euch scheinen.", sourceObjective = "Nehmt das Symbol des Lebens und sprecht mit Muiredon Kriegshammer in Eisenschmiede.\n\nBereitgestellter Gegenstand:", completion = "*husten*\n\nGuten Tag, {class}. Schenkt meinen Wunden keine Beachtung, die guten Priester hier flicken den alten Muiredon schon wieder zusammen. Noch brauche ich die Macht des Symbols des Lebens nicht, das Ihr da habt.\n\nMeine Frau schickt Euch, um mit mir zu sprechen, hm? Schön, schön. Ich werde mit Euch reden und Euch genau schildern, was Muiredon und seinem besten Freund Narm, einem {class} wie Ihr einer seid, zugestoßen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[1780] = { id = 1780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Ich bringe das noch heute zu den Kindern. Bitte bleibt unversehrt, {class}. Es kommt nicht oft vor, dass <Männer/Frauen> Eures Charakters in der Stadt auftauchen, doch Ihr habt bewiesen, dass die Paladine in Sturmwind die Bedürftigen nicht im Stich lassen.\n\nLebt wohl.", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", completion = "Ihr kehrt so schnell zurück, {name}. Und was habt Ihr während Eurer Abwesenheit von der Kathedrale erreicht?\n\nHabt Ihr bei einer edlen Sache geholfen? Vielleicht habt Ihr den Wert der Barmherzigkeit gelernt, oder etwas mehr über Eure Verpflichtung gegenüber den Bürgern von Azeroth erfahren. Sagt mir, wem Ihr geholfen habt, und wie ... Ich bin beeindruckt, {name}, das sind gewiss Taten von einem, der dem Licht folgt und andere höher schätzt als sich selbst.\n\nSolche Opfer werden im Laufe der Zeit immer belohnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1781] = { id = 1781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Nehmt das, {name}. Es heißt Symbol des Lebens.\n\nIhr habt bewiesen, dass Ihr barmherzig und geduldig seid. Jetzt ist die Zeit gekommen, um festzustellen, ob Ihr stark genug seid für die größte Gabe des Lichts.\n\nMein Freund Gazin kehrte jüngst von einer Begegnung mit Defias in Elwynn nahe Heldenwache zurück - er kam gerade so mit dem Leben davon. Er ist in der Nähe des Altars, wo unsere Priester seine Wunden heilen.\n\nNehmt das Symbol und sprecht mit ihm. Wenn Ihr ihm helfen könnt, dann sprechen wir uns bald wieder. Möget Ihr Euch im Schein des Lichts sonnen.", sourceObjective = "Bringt das Symbol des Lebens zu Gazin Tenorm in Sturmwind.\n\nBereitgestellter Gegenstand:", completion = "*husten*\n\nWelch Freude, Euch zu sehen, {class}. Schenkt meinen Wunden keine Beachtung, die guten Priester hier flicken den alten Gazin wieder zusammen. Ich brauche die Macht des Symbols des Lebens nicht, das Ihr da habt... noch nicht.\n\nDuthorian schickt Euch, um mit mir zu sprechen, hm? Schön und gut. Ich werde Euch genau schildern, was mir und meinem Freund Henze zugestoßen ist. Und mit etwas Glück und Geschick Eurerseits könnt Ihr vielleicht doch uns allen helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1782] = { id = 1782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Furens Rüstung", sourceObjective = "Hier ist Eure Rüstung, {name}. Sie wird dem stärksten Angriff standhalten, oder ich will nicht mehr Furen Longbeard heißen!\n\nUnd ich habe Euch zu danken. Ich habe bei der Arbeit mit dem Material, das Ihr mir brachtet, viel gelernt. Ich glaube, eines Tages werde ich einen weiteren Durchbruch schaffen!\n\nIch werde das, was ich gelernt habe, den anderen Schmieden der Allianz schicken.\n\nIch sage ihnen, was für eine große Hilfe Ihr wart. Vielleicht möchten sie den Gefallen erwidern.", sourceObjectiveStatus = "unverified-source-field" }
quests[1783] = { id = 1783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Er spionierte einigen Dunkeleisenzwergen nach, die sich südlich des Helmsbettsees eingebunkert hatten. Wir wussten, dass sie nichts Gutes im Schilde führten, daher dachten Narm und ich, wir sollten der Sache nachgehen - wir sahen, wie ihr Anführer seinen Männern Befehle gab.\n\nNarm und ich wollten einige töten, aber sie waren stärker als wir dachten und es wurden immer mehr. Narm sagte mir, ich solle Verstärkung holen, und hier bin ich.\n\nNarm braucht Hilfe und ich werde erst ruhen, wenn er sie bekommt.\n\nKönnt Ihr helfen, {name}?", sourceObjective = "Nehmt das Symbol des Lebens und erweckt Narm Faulk in Dun Morogh wieder zum Leben.", completion = "Ich kann Euch nicht genug danken, Bruder.\n\nDa Ihr das Symbol des Lebens tragt, kann ich nur vermuten, dass Tiza und Muiredon Euch hergeschickt haben.\n\nEs stimmt, ich wurde Opfer der Dunkeleisenzwerge, als ich versuchte, eines der Manuskripte zu bekommen: Es gelang mir so lange durchzuhalten, bis Muiredon entkommen konnte, aber das Licht hätte mich fast in sich aufgenommen, als Ihr gekommen seid. Dass Ihr mächtig genug wart, das Symbol zu benutzen, bedeutet eine große Zukunft für Euch, doch davon wollen wir später sprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1784] = { id = 1784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Bevor ich im Kampf fiel, hatten Muiredon und ich fast einen der Spione der Dunkeleisenzwerge in der Nähe dieses kleinen Hauses besiegt. Wir wurden Zeugen, wie ihr Hauptmann ihnen Befehle weitergab, und wollten sie töten und die Befehle an uns nehmen.\n\nEinige im Rat von Eisenschmiede glauben nicht, dass sich Dunkeleisenzwerge in Dun Morogh aufhalten. Bekämen wir eines dieser Manuskripte, hätten wir nicht nur den Beweis für ihre Tätigkeiten, sondern möglicherweise auch eine Vorstellung dessen, was sie planen.\n\nBeschafft eines dieser Manuskripte und bringt es zu Muiredon, {name}.", sourceObjective = "Beschafft ein Dunkeleisenmanuskript von den Dunkeleisenzwergen beim Helmsbettsee und kehrt zu Muiredon Kriegshammer in Eisenschmiede zurück.", progress = "Ihr seid zurück! Wie mich das freut, {name}. Meine Wunden sind verheilt und ich bin bereit, schnellstens zum Helmsbedsee zurückzukehren, sobald ich meine Frau davon überzeugt habe, dass es mir gut geht.", completion = "Ha-ha! Ihr habt es geschafft! Ihr habt Narm gerettet und den Beweis gefunden, den meine Frau braucht, um den Rat zu überzeugen. Einen solchen Segen des Lichts wie Euch sah ich noch nie... natürlich mit Ausnahme meiner Frau.\n\nNochmals danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1785] = { id = 1785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Ich sehe, meine Frau steht schon da drüben und platzt vor Stolz. Schleppt Euch besser mal hier rüber, aber pronto. Könnte mir denken, dass sie Euch was zu sagen hat.\n\n's Licht soll mit Euch sein, {class}. Wenn die Zeit reif ist, such ich nach Euch auf den Schlachtfeldern, wenn es gegen die Geißel und die Dunkeleisenzwerge geht.", sourceObjective = "Sprecht mit Tiza Kriegshammer in Eisenschmiede.", completion = "Heute habt Ihr ganz Ironforge einen großen Gefallen getan, {name}. Ich bin stolz, dass Ihr zu uns gehört, und wenn Ihr bereit seid, würde ich Euch gern mit dieser Rolle segnen. Das Symbol des Lebens funktioniert nur bei einem {class}, der bereit ist, den größten Segen des Lichts zu empfangen - die Macht, die Toten ins Leben zurückzurufen.\n\nIch lehre Euch die Fähigkeit, Eure Gefährten wiederzubeleben. Nutzt sie weise, {name}, und habt Dank von mir, meinem Mann und ganz Ironforge.", sourceObjectiveStatus = "unverified-source-field" }
quests[1786] = { id = 1786, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Henze und ich schafften es nach Heldenwache, einer Insel inmitten des Steinhügelsees im nordöstlichen Elwynn. Wir hörten, dass Defias unsere Grenzen unterwandert hatten und wollten einen Beweis für die Berater des Königs.\n\nAls wir eine Bande dieses Abschaums sahen, die Dokumente durchlasen, griffen wir an. Leider wurden wir recht schnell durch ihre Magier überwältigt.\n\nHenze wehrte sie ab, derweil ich entkam...der elende Narr muss immer den Helden spielen.\n\nEr ist jetzt da draußen, der gute Henze. Könnt Ihr uns helfen, {name}?", sourceObjective = "Nehmt das Symbol des Lebens und erweckt Henze Faulk in Elwynn wieder zum Leben.", completion = "Danke, Bruder.\n\nDa Ihr das Symbol des Lebens tragt, darf ich wohl annehmen, dass Euch Duthorian oder Gazin geschickt hat.\n\nIch wurde Opfer der Zauberer der Defias, als Gazin und ich ihnen ihre Pläne abnehmen wollten. Ich hielt lange genug durch, dass Gazin entkommen konnte, aber am Ende überwältigte mich ihre Magie.\n\nDoch Ihr konntet mich zurückholen: Nicht jeder besitzt die Fähigkeit, das Symbol zu benutzen, {name}. Es spricht für Euch, dass Ihr fähig wart, es durch Euren eigenen Glauben mächtig werden zu lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1787] = { id = 1787, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Wir müssen uns später ausgiebiger über das Symbol unterhalten. Wichtig ist jetzt, dass wir diese Papiere bekommen, die die Defias studierten. Wenn wir sie in die Finger bekommen, können wir beweisen, dass die Defias Elwynn unterwandert haben und hoffentlich Einblick in ihre weiteren Pläne erhalten.\n\nMomentan bin ich nicht in der Verfassung zu kämpfen, {name}. Glaubt Ihr, Ihr seid stark genug, den Defias hier auf der Insel diese Papiere abzunehmen?\n\nWenn Ihr sie beschaffen könnt, bringt sie Gazin und lasst ihn wissen, dass ich wohlauf bin.", sourceObjective = "Beschafft eine Schrift der Defias von den abtrünnigen Hexern der Defias in Elwynn und kehrt zu Gazin Tenorm in Sturmwind zurück.", progress = "Ist Henze in Sicherheit, {name}? Hattet Ihr Erfolg?\n\nDurch Eure Fertigkeiten im Umgang mit Waffen und der Macht des Lichts sollte Heldenwache vor den Defias sicher sein, doch das müssen der König und seine Berater entscheiden.", completion = "Großartig! Ihr habt es geschafft und Henze gerettet. Das Licht ist eindeutig mit Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[1788] = { id = 1788, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Offenbarung", description = "Ich bringe das Manuskript zu den Beratern des Königs, nachdem Duthorian einen Blick darauf geworfen hat. In der Zwischenzeit solltet Ihr mit Duthorian sprechen. Er wird Euch ganz sicher auf die Schulter klopfen wollen!\n\nNochmals danke, {name}. Ich hoffe, wir sehen uns wieder. Ihr seid ein Verbündeter, den ich voller Stolz meinen Freund nenne.", sourceObjective = "Sprecht mit Duthorian Rall in Sturmwind.", completion = "Ihr habt Eure Sache heute gut gemacht, {name}. Ihr solltet stolz auf Eure Leistungen sein.\n\nUnd noch stolzer solltet Ihr auf Eure Fähigkeiten sein. Nicht jeder kann die Macht des Symbols des Lebens nutzen. Da Ihr das Licht rufen könnt, um die Toten zu erwecken, seid Ihr bereit für eine der größten Ehren eines Paladins: die Macht der Auferstehung.\n\nIhr werdet die Macht haben, gefallene Gefährten zurückbringen zu können, wie das bei Henze geschah.\n\nGehabt Euch wohl, {name}. Das Licht scheint auf Euch und Ihr solltet dankbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1789] = { id = 1789, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Symbol des Lebens", sourceObjective = "Solltet Ihr es nicht schaffen, Narm zu helfen, nachdem Ihr das Symbol des Lebens benutzt habt, {name}, dann kommt zu mir zurück und ich werde Euch ein weiteres geben.\n\nEs ist sowohl für meinen Ehemann als auch für mich wichtig, dass Ihr erfolgreich zurückkehrt. Bitte sputet Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[1790] = { id = 1790, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Symbol des Lebens", sourceObjective = "Sputet Euch, {name}, mehr als ein Leben steht auf dem Spiel, wenn Ihr scheitert.\n\nWenn Ihr Gazin und Henze aus irgendeinem Grund nicht helfen könnt, dann kommt zu mir zurück und ich gebe Euch ein weiteres Symbol des Lebens für Eure Reisen.\n\nVersteht meine Unterstützung nicht als reine Wohltätigkeit. Ihr müsst Euch wie jeder andere {class} beweisen, und wenn Ihr ständig scheitert, fällt das später auf Euch zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[1791] = { id = 1791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Windbehüter", description = "Jetzt, da Ihr Eure Berserkerhaltung gelernt habt, wollt Ihr bestimmt auch eine hübsche Waffe dazu.\n\nSprecht mit Bath'rah dem Windbehüter. Das ist ein Trolleinsiedler, der zwischen dem Alteracgebirge und den Westlichen Pestländern lebt. Er ist ein geschickter Waffenmacher und mächtiger Schamane.\n\nUm Bath'rah zu finden, solltet Ihr zu dem Fluss gehen, der an der Ostflanke von Tarrens Mühle entlangfließt. Folgt ihm nach Norden - Bath'rah hat sein Lager nahe den Ruinen am Ostufer des Flusses aufgeschlagen.", sourceObjective = "Sprecht mit Bath'rah dem Windbehüter.", completion = "Ihr seid weit gereist, junger {class}. Ich sehe Feuer in Euren Augen. Ihr sucht eine Waffe mit großer Macht, ja?\n\nIch kann Euch bei Eurer Suche helfen. Und Ihr mir bei meiner.", sourceObjectiveStatus = "unverified-source-field" }
quests[1792] = { id = 1792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wirbelwaffe", sourceObjective = "Ich habe das Wirbelherz und bin bereit, es in ein Gefäß Eurer Wahl zu legen.\n\nWählt eine Waffe, {name}, und wisset, dass ihre Macht die Macht des Cyclonian ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[1793] = { id = 1793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Ehre", sourceObjective = "Es steht fest, dass das Licht mit Euch ist, {name}, doch da die Zeiten zunehmend gefährlicher werden, ist es wichtig zu wissen, welche Kräfte dem Fleische innewohnen. Wenn Dämonen, Großdrachen oder ein anderes Übel einen Fuß in unser Land setzen, wird Eure Tapferkeit auf die Probe gestellt. Werdet Ihr stark genug sein?\n\nTapferkeit in jedweder Situation gehört ebenso zu einem {class} wie das Licht, seine Rüstung und seine Waffe. Die Schwachen beschützen und den Glauben nicht verlieren, sind zwei weitere Lektionen, die Ihr meistern müsst, wenn Ihr in der Kathedrale des Lichts studiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[1794] = { id = 1794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Ehre", sourceObjective = "Es steht fest, dass das Licht mit Euch ist, {name}, doch da die Zeiten zunehmend gefährlicher werden, ist es wichtig zu wissen, welche Kräfte dem Fleische innewohnen. Wenn Dämonen, Großdrachen oder ein anderes Übel einen Fuß in unser Land setzen, wird Eure Tapferkeit auf die Probe gestellt. Werdet Ihr stark genug sein?\n\nTapferkeit in jedweder Situation gehört ebenso zu einem {class} wie das Licht, seine Rüstung und seine Waffe. Die Schwachen beschützen und den Glauben nicht verlieren, sind zwei weitere Lektionen, die Ihr meistern müsst, wenn Ihr in der Kathedrale des Lichts studiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[1795] = { id = 1795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bindung", description = "Wenn Ihr hinreichend vorbereitet seid, sollten wir beginnen. Lasst mich Euch den Vorgang erklären.\n\nIch beginne damit, dass ich den Standard-Beschwörungskreis erstelle. Wenn das geschehen ist, werden meine Akolythen mit den Kanalisierungsruten den größeren Kreis erstellen.\n\nIst das abgeschlossen, lest Ihr die Zauberformel aus dem Folianten der Kabale und der Teufelsjäger erscheint. Seid vorsichtig, {name}. Ein Teufelsjäger ist ein mächtiger Widersacher. Ich möchte nicht, dass er Euch einen Kopf kürzer macht.", sourceObjective = "Beschwört mithilfe des 'Folianten der Kabale' einen Teufelsjäger, unterwerft ihn und bringt den 'Folianten der Kabale' zu Strahad Farsan in Ratschet zurück.", progress = "Jedem {class} sollte ein Teufelsjäger zur Verfügung stehen. Obwohl er schwer zu bändigen ist, macht die Macht, die er seinem Herrn gibt, die Kosten bei weitem wett.", completion = "Ich muss sagen, ich bin beeindruckt, {name}. Als ich meinen Teufelsjäger unterwarf, kam ich knapp mit dem Leben davon. Ich spüre, Ihr habt das Potenzial, einer der mächtigsten {class} dieser Gegend zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[1796] = { id = 1796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Komponenten für die verzauberte Goldblutrobe", description = "Der erste Gegenstand, bei dessen Erschaffung ich Euch helfen werde, ist eine Robe. Ihr werdet die Gegenstände für mich sammeln und wir werden sie zusammensetzen. Vorausgesetzt Ihr seid erfolgreich, werdet Ihr danach den ersten von vielen Gegenständen haben, die Euch mächtiger machen und Euch bei Eurem Kampf helfen werden.\n\nFür den Anfang müsst Ihr in den Besitz der Roben von Arcana kommen. Ein Schneider kann sie für Euch machen oder vielleicht könnt Ihr eine von jemandem kaufen... am meisten würde es mich beeindrucken, wenn Ihr sie selbst herstellen könntet... aber wie auch immer, bringt mir die Roben und dann machen wir weiter.", sourceObjective = "Bringt die Roben von Arcana zu Menara Leerbringer im Brachland.", progress = "Wie läuft Eure Suche nach den Roben, {name}? Habt Ihr selbst welche hergestellt? Diese persönlichen Feinarbeiten machen das Erfüllen mit Magie so viel schöner. Sie geben Euch eine große Befriedigung. Aber ich habe Verständnis, wenn Ihr Euch für den schnelleren Weg entschieden habt und sie habt herstellen lassen. Es hat schon was für sich ... ein solcher Ehrgeiz.", completion = "Das dürfte reichen, {name}.\n\nAlle magischen Gegenstände müssen mit einem Gegenstand von hoher Qualität beginnen. Je mehr Mühe und Können man in einen Gegenstand legt, desto größere Magie kann er aufnehmen. Seltene und teurere Komponenten halten die Magie besser. Ihr werdet nicht bereuen, diese Roben in jene mit einzubringen, die wir später für Euch machen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[1798] = { id = 1798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Suche nach Strahad", description = "Es ist Zeit, dass Ihr die Beschwörung eines Teufelsjägers lernt, {name}. Ich habe nicht die erforderlichen Reagenzien und Gegenstände, um Euch hier zu unterrichten, daher müsst Ihr einen anderen aus unserem inneren Kreis aufsuchen, nämlich Strahad Farsan.\n\nEr hat sich im Goblinhafen von Ratschet niedergelassen. Ich werde ihn von Eurer Ankunft in Kenntnis setzen lassen.", sourceObjective = "Sprecht mit Strahad Farsan im Brachland.", completion = "{name}? Ah, natürlich. Unser neuestes Wunderkind. Leider entspricht die Realität nicht ganz der Legende.\n\nWie auch immer, Ihr seid gekommen um zu lernen, und nicht um anzuhören, wie ich Witze über Euch mache.", sourceObjectiveStatus = "unverified-source-field" }
quests[1799] = { id = 1799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragmente der Kugel von Orahil", description = "Gut, dann können wir beginnen.\n\nIhr müsst als Erstes mit meinen Akolythen im Inneren sprechen. Wählt einen ihrer Wege und folgt ihm - sie werden Euch alles erklären.\n\nAls Zweites müsst Ihr nach Desolace reisen und eine Höllenkugel von einem der Hexenmeister beim Zirkel der Mannoroc holen. Diese Kugel werdet Ihr mit der Hilfe einer Magierin namens Tabetha tief in den südlichen Düstermarschen reinigen. Sie wird Euch aufgrund unserer gemeinsamen Vergangenheit helfen.\n\nKommt erst zurück, wenn Ihr beide Dinge erledigt habt, um die ich Euch gebeten habe.", sourceObjective = "Sprecht mit Menaras Akolythen im Inneren des Turms über Ratschet und wählt einen ihrer Wege, um ihm zu folgen.\n\nBringt danach eine Höllenkugel zu Tabetha in den Düstermarschen.", progress = "Da Ihr offensichtlich kein Magier seid, frage ich mich, ob ich Euch überhaupt trauen kann. Ich kann die Macht des Arkanen an Euch riechen, aber Ihr scheint Euch dem Gestank der Verderbnis entzogen zu haben, der Eurer Art so bereitwillig anhängt.\n\nJa, ein {class} ... ein {class} ist gekommen, um mich um Hilfe zu bitten.\n\nNun, was kann ich für Euch tun, {name}?", completion = "Oh, Menara schickt Euch also. Nun denn... Ich nehme an, Ihr könnt bis auf weiteres als mein Gast bleiben. Ihr habt aber doch bestimmt dringende Geschäfte zu erledigen - vielleicht seid Ihr hier, um verlorene Macht zu suchen? Vielleicht liege ich falsch. Vielleicht ist die Verderbnis doch nicht so weit entfernt von Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[1800] = { id = 1800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Thronsaal von Lordaeron", description = "Wenn wir brav sind und die Hausarbeiten ordentlich machen, erzählen uns die Waisenmatronen oft Geschichten von großen Schlachten und darüber, wie Lordaeron fiel und wie der böse Arthas seinen eigenen Vater umbrachte, nur um König zu werden.\n\nEr hatte keine Ehre, {name}! Wenn ich erst einmal groß und ein mächtiger Krieger der Horde bin, wird mein Schwert durch die Ehre geleitet werden; niemals durch das Böse!\n\nWürdet Ihr mit mir den Thronsaal besuchen, bitte? Er befindet sich kurz vor dem Abgang, über den man nach Unterstadt heruntergeht.", sourceObjective = "Besucht mit Eurem Schützling den alten Thronsaal in Lordaeron. Er befindet sich kurz vor dem Abgang nach Unterstadt.", completion = "Der Thronsaal war vielleicht gruselig, {name}! Obwohl er völlig leer war, konnte man noch fühlen das etwas sehr böses dort passiert ist. Ich fühlte Wut... aber ich war auch traurig. Jetzt verstehe ich, warum uns die Matronen solche Geschichten erzählen. Ich werde niemals mein Volk betrügen!\n\nDanke, dass du mit mir den Thronsaal besucht hast, {name}. Ich glaube, ich habe viel gelernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1801] = { id = 1801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Kabale", description = "Mehr als ein einfacher Beschwörungskreis wird erforderlich sein, um einen Teufelsjäger als Herausforderer für Euch herzubringen.\n\nMeine drei Akolythen und ich helfen, die magischen Kreise zu erschaffen. Ihr benötigt eine Kopie des Folianten der Kabale, der seit geraumer Zeit als verschollen gilt. Er wurde von der ersten Gruppe Hexenmeister geschrieben, die ohne Unterstützung einen Teufelsjäger beschwörten.\n\nVielleicht kann Jorah Annison Euch dabei helfen. Heute arbeitet er als Kartograf in Unterstadt, weiß aber dennoch mehr über alte Schriften als ich.", sourceObjective = "Sprecht mit Jorah Annison in Unterstadt.", completion = "Karten machen! Bilder, Einschätzungen der Realität. Dafür habe ich keine Verwendung.\n\nIn Büchern, Erzählungen und Beschreibungen! Dort ist die Wahrheit. Ich würde alle Karten in diesem Laden für ein Buch über den Siegeszug der Totenbeschwörung oder eine Geschichte über den Triumph der dunklen Fürstin tauschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1802] = { id = 1802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Kabale", description = "Er ist verschollen, aber man glaubt zu wissen, wo man ihn finden könnte.\n\nNur eine Kopie wurde jemals angefertigt, und die wurde einst beschädigt, eine Vielzahl von Seiten herausgerissen. Man munkelt, dass er irgendwie den Zentauren von Tausend Nadeln in die Hände gefallen sein soll.\n\nDer Rest ging an der Küste westlich von Süderstade verloren, als er per Schiff zum Hafen von Menethil hätte transportiert werden sollen. Er kam nie an.\n\nAls Gegenleistung für dieses Wissen verlange ich nur, dass Ihr ihn findet und mir zur Ansicht bringt.", sourceObjective = "Beschafft den schimmeligen Folianten und das zerlumpte Manuskript für Krom Starkarm in Eisenschmiede.", progress = "Haben sich die Gerüchte als zutreffend erwiesen, {name}?", completion = "Phantastisch! Nun gehöre ich zu den Wenigen, die seinen Inhalt gesehen haben.\n\nIch kann es kaum erwarten, den Text weiter zu studieren. Das ist ein großer Tag, {name}! Wenn Ihr mich nur einen Blick hineinwerfen lassen würdet, bevor Ihr geht. Ich bin sicher, Strahad wird bereit sein, mir eine Kopie zu schicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[1803] = { id = 1803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Kabale", description = "Ah! Ich sehe, Ihr seid ein Hexenmeister, der meinen Geschmack teilt. Den Folianten der Kabale zu beschaffen ist ein würdiges Ziel. Habt Ihr gewusst, dass er sich einst innerhalb der Mauern von Lordaeron befand? Aber er wurde beschädigt, fast die Hälfte der Seiten herausgerissen. Wer würde so eine abscheuliche Tat begehen?\n\nDiese Hälfte ist verschollen, doch man munkelt, sie soll den Zentauren von Tausend Nadeln in die Hände gefallen sein.\n\nDer Rest des Textes sollte nach Eisenschmiede gebracht werden, ging aber während der Überfahrt an der Westküste von Süderstade verloren.", sourceObjective = "Beschafft den schimmeligen Folianten und das zerlumpte Manuskript für Jorah Annison in Unterstadt.", progress = "Mag sein, dass Ihr Hirngespinsten nachjagt, {name}, aber selbst die wildesten Gerüchte enthalten meist ein Körnchen Wahrheit.", completion = "Ach nein! Was haben wir denn hier?\n\nDas ist beeindruckend, {name}. Ich hätte es nie für möglich gehalten, aber hier halte ich den vollständigen Folianten der Kabale in Händen.\n\nLasst mich nur kurz die Seiten durchblättern bevor Ihr wieder geht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1804] = { id = 1804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Kabale", description = "Ach ja, es ist recht schwer, ihn aus der Hand zu geben. Aber Ihr habt ihn gefunden und natürlich Wichtigeres damit zu tun. Vergesst nur nicht, Strahad zu sagen, dass ich eine Kopie haben möchte.\n\nWährend Ihr fort wart, hat er eine Nachricht für Euch geschickt. Er sagte mir, damit seine Akolythen bei der Beschwörung helfen können, müsst Ihr drei Kanalisierungsruten beschaffen.\n\nEr weiß vielleicht nicht, wo man die findet, aber ich! Sie wurden zuletzt von den Orcs des Drachenmalklans im Sumpfland verwendet. Ich würde mich mal mit ihren Zauberern in Verbindung setzen!", sourceObjective = "Bringt den rekonstruierten Folianten und 3 Kanalisierungsruten zu Strahad Farsan in Ratschet.", progress = "Ich habe Euch eine Weile nicht in dieser Gegend gesehen. Habt Ihr den Folianten und die Ruten schon gefunden?", completion = "Gut gemacht! Der Foliant der Kabale und drei makellose - vermutlich nur leicht zerkratzte - Kanalisierungsruten.\n\nDas wird interessant. Es ist eine Weile her, seit ein junger {class} sich einen Teufelsjäger zugelegt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[1805] = { id = 1805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Foliant der Kabale", description = "Das ist einer der interessantesten Texte, die ich in den letzten Jahren gelesen habe. Die Auswahl hier ist nicht sonderlich groß - zum Großteil sind es Bücher über Geografie - und ich habe sie schon alle gelesen. Hoffentlich schickt mir Strahad eine Kopie dieses Folianten, wenn er die Chance dazu hat.\n\nDa wir gerade von ihm sprechen: während Ihr fort wart, habe ich eine Nachricht von ihm erhalten. Für Eure Aufgabe müsst Ihr drei Ruten des Kanalisierens beschaffen.\n\nWeil Ihr mir diesen Text gezeigt habt, weihe ich Euch in ein Geheimnis ein: Ihr findet die Ruten bei den Orcs des Drachenmalklans im Sumpfland.", sourceObjective = "Bringt den rekonstruierten Folianten und 3 Ruten des Kanalisierens zu Strahad Farsan in Ratschet.", progress = "Ja, {name}? Wie kann ich Euch behilflich sein?", completion = "Gut gemacht! Der Foliant der Kabale und drei makellose - vermutlich nur leicht zerkratzte - Kanalisierungsruten.\n\nDas wird interessant. Es ist eine Weile her, seit ein junger {class} sich einen Teufelsjäger zugelegt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[1806] = { id = 1806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung der Rechtschaffenheit", description = "Warum gehen wir nicht rüber zur Schmiede und fangen damit an? Ich treffe schon seit einiger Zeit Vorbereitungen für Eure Ankunft, daher dürfte es nicht allzu lange dauern.\n\nWenn wir fertig sind, werdet Ihr viel besser gerüstet sein, das Licht zu verteidigen, als bisher, das schwöre ich Euch.\n\nIch will ehrlich sein, {name}, wenn ich die Ergebnisse Eurer Taten sehe, erfüllt mich ein gewisser Neid. Doch das Wissen, dass ich auf meine bedeutende Weise zu Euren Abenteuern beitragen kann, erfüllt mich mit Freude.", sourceObjective = "Wartet, bis Jordan Stillbrunn eine Waffe für Euch geschmiedet hat.", completion = "Da ist sie, {name}. Eine Waffe, wie sie einem Helden des Lichts würdig ist. Ich benannte sie nach einem großen Zwergenpaladin, der ein Freund von mir war. Sein Name war Verigan... Bosch Verigan. Bitte nehmt sie in meinem Namen und dem meiner Frau. Wir stehen tief in Eurer Schuld. Die Welt ist sicherer, wenn einer mit Euren Fähigkeiten durch das Land zieht.", sourceObjectiveStatus = "unverified-source-field" }
quests[1818] = { id = 1818, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Dillinger", description = "Todeswache Dillinger sagte mir, er habe einen Job für jemanden wie Euch. Wenn Ihr bereit seid, den Streitkräften der Dunklen Fürstin Euren Wert zu beweisen, dann meldet Euch umgehend bei Dillinger.\n\nTodeswache Dillingers Posten liegt am Westende von Brill, nahe beim Friedhof.", sourceObjective = "Sprecht mit Todeswache Dillinger in Brill.", completion = "Seid Ihr wegen einer Mission hier? Gut. Ich habe eine wichtige, die Eure Fertigkeiten im Gefecht auf die Probe stellt... und Eure Entschlossenheit, die Verlassenen zu verteidigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1819] = { id = 1819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ulag der Spalter", description = "Als die Geißel durch Tirisfal zog, konnten wir einen ihrer Angehörigen einfangen, um ihn zu studieren. Er hatte einen freien Geist und nannte sich Ulag der Spalter. Doch obwohl er einen freien Willen besaß, stand er noch immer unter dem Bann des Lichkönigs.\n\nWir hofften, wir könnten den Einfluss des Königs auf Ulag brechen, doch es gelang uns nicht. Jetzt ist die Zeit gekommen, ihn zu befreien. \n\nBefreit und tötet ihn.\n\nAktiviert den Schädelsteinauslöser beim Mausoleum im Norden. Damit wird das magische Siegel entfernt, das ihn bindet.\n\nUnd dann... seid bereit, {name}.", sourceObjective = "Tötet Ulag den Spalter und sprecht dann mit Todeswache Dillinger.", completion = "Gut gemacht, {name}. Ulag war kein unmaßgeblicher Agent der Geißel. Ihr habt den Todeswachen, und damit der dunklen Fürstin, gezeigt, dass Ihr ein geschickter und entschlossener {class} seid, und Euch damit weitere Ausbildung verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[1820] = { id = 1820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Coleman", description = "Ihr habt Euren Wert für die dunkle Fürstin bewiesen, vielleicht könnt Ihr ihn nun an einem ihrer Untertanen beweisen.\n\nColeman Heller wartet auf einen Krieger, der bereit ist, sein Instrument der Rache gegen die Feinde der Verlassenen zu sein.\n\nIhr findet ihn in der Taverne Zur Galgenschlinge im Osten von Brill.", sourceObjective = "Sprecht mit Coleman Heller.", completion = "Ja, es stimmt. Ich brauche Eure Fertigkeiten im Gefecht. Meine Mittel sind bescheiden, doch meine Aufgabe hilft mir und der Sache der Verlassenen. Macht es, und Ihr werdet zweifache Belohnung erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1821] = { id = 1821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamanderbstücke", description = "Zu Lebzeiten war die Familie Agamand mein Arbeitgeber und sie war die Ursache für meinen Tod. Es ist nur recht und billig, dass die Agamands jetzt hirnlose Diener des Lichkönigs sind.\n\nUnd jetzt möchte ich ihnen den letzten Rest Ehre nehmen. Geht in ihre Familiengruft und stehlt ihnen die Familienerbstücke: ein Schwert, eine Axt, einen Dolch und einen Streitkolben. Bringt sie mir!\n\nDie Gruft der Familie Agamand liegt am nördlichen Ende von Agamands Mühlen. Der Ort wird durch lauernde Angehörige der Geißel und tote Agamands bewacht.", sourceObjective = "Bringt Coleman Heller die Axt, das Schwert, den Streitkolben und den Dolch der Familie Agamand.", progress = "Habt Ihr die Erbstücke, {name}?", completion = "Ah! Ihr habt sie genommen! Jetzt ist das letzte Restchen Ehre und Andenken vom verfluchten Land der Agamands entfernt. Die Familie existiert wahrlich nicht mehr!", sourceObjectiveStatus = "unverified-source-field" }
quests[1822] = { id = 1822, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erbstückwaffe", sourceObjective = "Ich behalte drei der Waffen, die Ihr mir gebracht habt, als Andenken an meinen Schmerz und Verlust. Aber bitte, {name}, wählt Euer Lieblingserbstück und behaltet es für Euch.\n\nMöge es Euch besser dienen als seinen verfluchten vorherigen Besitzern.", sourceObjectiveStatus = "unverified-source-field" }
quests[1823] = { id = 1823, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Ruga", description = "Ihr seid ein Krieger mit Fertigkeiten und wachsendem Ansehen. Vielleicht seid Ihr bereit für Ruga Rachtotems Prüfung. Wenn ja, findet Ihr Ruga im Camp Taurajo im Brachland.\n\nEr wartet auf Krieger, die seinem Ruf folgen.", sourceObjective = "Sprecht mit Ruga Rachtotem.", completion = "Seid Ihr wegen meiner Prüfung hier, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[1824] = { id = 1824, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung auf dem Feld der Riesen", description = "Um diese Prüfung zu bestehen, müsst Ihr nach Süden zum Feld der Riesen reisen. Dort findet Ihr einen Schwarm krabbelnder Insektenwesen. Sie sind neu im Brachland und mir gefällt nicht, was sie ankündigen.\n\nBringt mir ihre noch zuckenden Fühler und vergeudet keine Zeit, {name}, denn abgetrennte Fühler zucken nicht lange. Bringt mir die Fühler in der genannten Zeit und Ihr werdet die Prüfung bestehen.", sourceObjective = "Bringt 5 zuckende Fühler zu Ruga Rachtotem im Camp Taurajo.", progress = "Habt Ihr die Fühler? Wenn ja, gebt sie mir schnell, denn zuckende Fühler zucken nicht ewig...", completion = "Ordentlich gemacht, {name}! Mit der bestandenen Prüfung auf dem Feld der Riesen habt Ihr einen weiteren Schritt auf dem Weg des Kriegers getan.", sourceObjectiveStatus = "unverified-source-field" }
quests[1825] = { id = 1825, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Thun'grim", description = "Thun'grim Brandblick, ein berühmter orcischer Schmied, hat von Euren fortgesetzten Heldentaten im Dienst der Horde gehört. Er möchte eine Rüstung für Euch anfertigen und bittet, dass Ihr umgehend mit ihm sprecht.\n\nThun'grims Lager liegt östlich des Wegekreuzes im Brachland.", sourceObjective = "Sprecht mit Thun'grim Brandblick im Brachland.", completion = "Ja, Ihr seid gekommen. Das ist gut, denn wir haben viel zu besprechen, wir beide.", sourceObjectiveStatus = "unverified-source-field" }
quests[1838] = { id = 1838, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutale Rüstung", description = "Ich habe Geschichten über Eure Kraft und Tapferkeit gehört und möchte eine Rüstung für Euch anfertigen, eine Unterstützung für Euch, während die Geschichten über Eure Ruhmestaten wachsen.\n\nAber die Herstellung dieser Rüstung wird eine Aufgabe für sich sein, {name}. Ich werde Eure Hilfe benötigen und die Hilfe der anderen Schmiede der Horde.\n\nHier, nehmt diese Rolle. In vielen Nächten habe ich mit fast blinden Augen aufgeschrieben, was ich für die Rüstung benötige. Bringt mir die Gegenstände auf dieser Rolle und ich fertige das erste Teil der Rüstung für Euch an.", sourceObjective = "Bringt Thun'grim Brandblick 15 rauchige Eisenblöcke, 10 pulverisierte Azurite, 10 Eisenbarren und 1 Phiole mit Phlogiston.", progress = "Habt Ihr die Gegenstände auf meiner Rolle, {name}?", completion = "Ihr habt alles gebracht, worum ich Euch bat. Jetzt beginnt meine Arbeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[1839] = { id = 1839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ula'elek und die brutalen Stulpen", description = "Der Trollschmied Ula'elek wird die brutalen Stulpen für Euch anfertigen. Er wohnt mit seinen Dunkelspeerbrüdern in Durotar in Sen'jin und erwartet Eure Ankunft.", sourceObjective = "Sprecht mit Ula'elek in Durotar.", completion = "Seid gegrüßt, {name}. Der alte Thun'grim ließ mich wissen, dass Ihr kommt, doch hätte er geschwiegen, hätte mich Eure Anwesenheit hier nicht überrascht.\n\nDie Geister wachen über Eure Fortschritte, junger {class}, und sagen mir, dass Ihr viele Feinde beseitigt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[1840] = { id = 1840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orm Steinhuf und der brutale Helm", description = "Orm Steinhuf wird ob seiner Fertigkeiten hoch geachtet. Er wird den brutalen Helm für Euch machen.\n\nSucht ihn in Donnerfels beim Teich nahe dem großen, zentralen Totem der Stadt.", sourceObjective = "Sprecht mit Orm Steinhuf in Donnerfels.", completion = "Seid gegrüßt, {class}. Ich bin Orm. Thun'grim sagte mir, Ihr wünscht einen Helm?", sourceObjectiveStatus = "unverified-source-field" }
quests[1841] = { id = 1841, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Velora Nachtens und die brutalen Beinschützer", description = "Es heißt, vor ihrem Tod hätte Velora Nachtens zu den besten Rüstungsschmieden von Lordaeron gehört. Offenbar konnte der Tod ihrem Talent nichts anhaben. Sprecht mit Velora - sie wird die brutalen Beinschützer für Euch machen.\n\nVelora geht ihrem Gewerbe in Unterstadt unterhalb von Lordaeron nach, im Handwerksviertel.", sourceObjective = "Sprecht in Unterstadt mit Velora Nachtens.", completion = "Seid Ihr wegen der Beinrüstung hier? Großartig!\n\nHm... mache ich die Rüstung für Euch oder Ihr sie für mich?\n\nDas war ein Witz. War er komisch? Ich weiß es nicht... Ich habe meinen Sinn für Humor im selben Moment wie meinen Geruchssinn verloren. Das war auch der Moment, als ich aufhörte zu atmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1842] = { id = 1842, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyrhufe", description = "Ich kann Euch ein Paar brutale Stulpen machen, denen große Magie innewohnen wird. Doch vorher müsst Ihr diese Magie sammeln und mir bringen.\n\nDie Satyrn halten sich im nordöstlichen Teil des Eschentals auf wegen der Macht, die dem Wald innewohnt. Sie nähren sich an seiner Reinheit, saugen sie ab und verderben sie. An den geschwollenen, ungespaltenen Hufen erkennt man, welche Satyrn die meiste Magie des Eschentals aufgenommen haben.\n\nDiese Hufe besitzen große Macht. Ich brauche sie, um Eure Stulpen anzufertigen.", sourceObjective = "Bringt 7 ungespaltene Satyrhufe zu Ula'elek in Sen'jin in Durotar.", progress = "Habt Ihr die Hufe, {name}? Die Magie in ihnen ist stark.", completion = "Ah, Ihr habt sie! Jetzt werde ich die Macht in diesen Hufen absaugen und in meine Rüstung einfließen lassen, so wie die Satyrn die Stärke von Ashenvale absaugten.", sourceObjectiveStatus = "unverified-source-field" }
quests[1843] = { id = 1843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutale Stulpen", sourceObjective = "Danke, {name}. Diese Stulpen sind meine beste Arbeit. Nehmt sie. Wenn Ihr sie tragt, bringt es mir und meinen Vorfahren Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[1844] = { id = 1844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schimärenhorn", description = "Ich mache Euch den Helm, doch vorher müsst Ihr mir zeigen, dass Ihr würdig seid.\n\nEingebettet in die südwestlichen Ausläufer des Steinkrallengebirges liegt das Verbrannte Tal. Das war einst ein fruchtbarer Ort, ist aber heute besudelt und voll Asche. Die Kreaturen, die dort noch hausen, sind wahnsinnig vor Schmerz und Verzweiflung.\n\nAn diesen Ort schicke ich Euch, {name}.\n\nIhr müsst zum Verbrannten Tal reisen und eine Schimärenmatriarchin suchen. Tötet sie, erlöst sie von ihrem Elend. Bringt mir ihr galvanisiertes Horn als Beweis, dann mache ich den Helm für Euch.", sourceObjective = "Bringt ein galvanisiertes Horn zu Orm Steinhuf in Donnerfels.", progress = "Habt Ihr das Horn? Ist die Matriarchin von Schmerzen befreit?", completion = "Ihr habt Eure Aufgabe beendet, {name}, und Euch als würdig und entschlossen erwiesen. Der Helm wird Euch gehören...", sourceObjectiveStatus = "unverified-source-field" }
quests[1845] = { id = 1845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutaler Helm", sourceObjective = "Ich gebe Euch diesen Helm.\n\nGroße Taten brachten Euch zu mir, {name}, und wenn es der Erdenmutter gefällt... liegen noch größere vor Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[1846] = { id = 1846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schienbeinknochen der Drachenmalorcs", description = "Um brutale Beinschützer zu machen, brauche ich eine Stütze aus stabilem Schienbeinknochen. Die Orcs des Drachenmalklans im Sumpfland haben hübsche, dicke Schienbeinknochen. Die brauche ich.\n\nAber sie müssen stabil sein. Prüft die Schienbeinknochen unbedingt, wenn Ihr sie einsammelt. Wenn Ihr sie mit bloßen Händen zerbrechen könnt, sind sie nicht stabil genug für mich.", sourceObjective = "Bringt 8 stabile Schienbeinknochen eines Drachenmalorcs zu Velora Nachtens in Unterstadt.", progress = "Ich warte auf diese Schienbeinknochen, {name}. Sie werden ein prächtiges Gestell für Eure Beinschützer.", completion = "Gut gemacht! Die sehen robust genug aus. Ich glaube, sie sind genau richtig. Wie haben die Orcs reagiert, als Ihr ihnen an die Schienbeinknochen wolltet, {name}? Haben Sie viel Getue gemacht?\n\nDas war wieder ein Witz. Ihr lacht ja gar nicht.\n\nIch bin heutzutage nicht mehr sehr komisch, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[1847] = { id = 1847, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutale Beinschützer", sourceObjective = "Hier sind Eure Beinschützer, {name}. Lasst mich wissen, ob sie passen oder geändert werden müssen. Ich möchte zufriedene Kunden! Zumindest früher wollte ich das.\n\nHeutzutage liegt mir nicht mehr viel an meinem Handwerk. Aber immer noch besser, als eine hirnlose Dienerin der Geißel zu sein!\n\nDenke ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[1848] = { id = 1848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brutale Halsberge", sourceObjective = "Ich bin sicher, Ihr habt bei dieser Aufgabe viele Unannehmlichkeiten erduldet und viel Blut vergossen, {name}. Hier ist das Produkt Eurer Mühsal.\n\nMöge es Euch gute Dienste leisten und möget Ihr eines Tages wiederkommen und erzählen, wie nützlich sie Euch waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[1858] = { id = 1858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zerschmetterte Hand", description = "Ich überlasse es Euch, Tazans Ranzen zu öffnen und mir seinen Inhalt zu bringen. Der Schlossmechanismus ist komplex, daher wäre es wohl das Beste, wenn Ihr Euch den Schlüssel beschafft.\n\nDa Ihr ihn bei Tazans Leichnam nicht gefunden habt, kann ich nur annehmen, dass er ihn jemandem in Obhut gegeben hat. Ah, ja, ganz recht! Er hatte einen Assistenten namens Gamon. Ein Trunkenbold, vermutlich findet Ihr ihn in der Taverne. Vielleicht könnt Ihr ihm den Schlüssel heimlich abnehmen.", sourceObjective = "Stehlt Tazans Schlüssel, öffnet seinen Ranzen damit und bringt den Inhalt zu Therzok in der Kluft der Schatten in Orgrimmar.", progress = "Ist es nicht verflixt, das Objekt der Begierde in Reichweite zu haben und trotzdem nicht ranzukommen?.", completion = "Hmm, also das ist interessant. Ihr habt Euren Wert damit mehr als bewiesen, {name}. Ich bin recht beeindruckt. Betrachtet Euch als neuestes Mitglied der Shattered-Hand. Und nehmt dies; ich glaube, es wird Euch in Zukunft eine große Hilfe sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1859] = { id = 1859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Therzok", description = "Sprecht leiser, {name}. Ja, ich kenne Euren Namen. Mir wurde gesagt, ich soll nach einem Orc Ausschau halten, auf den Eure Beschreibung passt.\n\nSoweit wir gehört haben, könnt Ihr im Gefecht bestehen und habt nichts gegen ein wenig Heimlichtuerei von Zeit zu Zeit einzuwenden.\n\nHabe ich Recht?\n\nWie auch immer, Ihr solltet Therzok in Orgrimmar aufsuchen. Er hat ein Angebot, das Ihr Euch anhören solltet.", sourceObjective = "Sprecht mit Therzok in der Kluft der Schatten in Orgrimmar.", completion = "Ausgezeichnet, ich bin froh, dass Kaplak Euer habhaft wurde.\n\nWir haben einiges zu besprechen, darunter auch Eure Zukunft bei der Hand.", sourceObjectiveStatus = "unverified-source-field" }
quests[1860] = { id = 1860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Jennea", description = "Wir Magier haben eine Aufgabe, die erledigt werden muss. Sie ist für die Sicherheit von Sturmwind und dem Wald von Elwynn von entscheidender Bedeutung.\n\nJennea Haubitz kennt die Einzelheiten. Sie studiert im Magiersanktum im Magierviertel von Sturmwind. Ihr solltet Euch eiligst zu ihr begeben.", sourceObjective = "Sprecht in Sturmwind mit Jennea Haubitz.", completion = "Wurdet Ihr geschickt, um mich bei meiner Aufgabe zu unterstützen, {name}? Gut. Schön zu sehen, dass junge {class} darauf brennen, unsere Sache zu unterstützen...\n\nWas für eine Sache, fragt Ihr? Alles zu seiner Zeit. Zu gegebener Zeit werdet Ihr es erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[1861] = { id = 1861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiegelsee", description = "Diese Welt ist gewaltigen mystischen Kämpfen zum Opfer gefallen, die magische Ströme aus ihren einst stabilen Kanälen rissen. Wir haben Mühe, die Auswirkungen dieser Veränderungen herauszufinden. Einige von uns fürchten das Schlimmste.\n\nAber davon werde ich Euch später mehr erzählen. Im Augenblick müsst Ihr Informationen für uns sammeln.\n\nHier, nehmt dieses Fläschchen. Geht zum Wasserfall des Spiegelsees, südwestlich der Tore von Sturmwind, und holt dort eine Probe des Wassers. Bringt sie mir, damit ich die magische Besudelung messen kann.", sourceObjective = "Bringt eine Probe des Spiegelseewassers zu Jennea Haubitz in Sturmwind.", progress = "Habt Ihr die Probe, {name}? Der Fluss der Magie in Stormwind und Elwynn wurde verändert; ich muss wissen, ob sie in das Wasser sickert.", completion = "Danke, {name}. Ich werde das Wasser auf magische Eigenschaften hin prüfen. Hoffen wir, dass es keine enthält, sonst werden alle, die zu lange aus dem Spiegelsee trinken, negativ beeinflusst.\n\nHier, {name}. Nehmt diese Kugel oder diesen Stab als Zeichen dafür, dass Ihr mir gute Dienste geleistet habt. Was Ihr auch wählt, es möge Euch nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1878] = { id = 1878, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserbeutelkopfgeld", progress = "Ihr seid ja schon wieder da, {name}! Wenn Ihr noch fünf Wasserbeutel eines Wüstenläufers für mich habt, dann habe ich hier ein kleines Paket, das nur auf Euch wartet!", completion = "Hervorragend - je mehr Wasserbeutel wir wiederbeschaffen können, desto weiter sind wir von einer Katastrophe entfernt! Bringt mir mehr und ich werde Euch für jeweils fünf Wasserbeutel belohnen, die Ihr mir bringt." }
quests[1879] = { id = 1879, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Bink", description = "{name}! Bink, meine gnomische Kollegin in Eisenschmiede, hat sich gemeldet. Sie hat eine Aufgabe zu erledigen und will sich dabei nur auf einen Magier verlassen! Seid Ihr <ein Magier/eine Magierin>, {name}?\n\nWenn ja, sprecht mit Bink. Sie verbringt ihre Zeit in Eisenschmiede in der Halle der Mysterien im mystischen Krieg.", sourceObjective = "Sprecht mit Bink in Eisenschmiede.", completion = "Oh, ich sehe, dass Ihr viel versprechend seid, ja, so ist es! Aber das reicht nicht für einen guten {class}. Wenn man kein guter {class} ist, dann ist man ein schlechter {class}. Und schlechte {class} sind ein Teil des Problems, so ist es!\n\nUps, ich greife mal wieder vor. Eins nach dem anderen!", sourceObjectiveStatus = "unverified-source-field" }
quests[1880] = { id = 1880, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magitastischer Gizmonitor", description = "Wir Magier machen mehr als nur mit den Fingern schnippen und hübsche Funken regnen lassen. Wir kontrollieren die Magie, die Grundsubstanz unserer Welt! Das erfordert große Umsicht und Entschlossenheit. Und Wissen... viel, viel Wissen!\n\nEines meiner Geräte, der magitastische Gizmonitor, sammelt und speichert dieses Wissen in riesigen Mengen! Aber ich verlor ihn! Als wir aus unserer Heimat Gnomeregan flohen, ließ ich ihn in einer Truhe in einer unserer Hütten vor der Stadt, und jetzt wimmelt es dort von Lepragnomen!\n\nBitte, {name}, findet meinen Gizmonitor wieder!", sourceObjective = "Bringt Bink ihren magitastischen Gizmonitor.", progress = "Habt Ihr meinen Gizmonitor gefunden? Ich muss ihn haben, ehe sein Energievorrat aufgebraucht ist!", completion = "Na großartig! Als ich meinen Gizmonitor herstellte, hatte ich keine Ahnung, wie abhängig ich einmal davon werden würde. Jetzt kann ich mit meinen Studien von vorn beginnen!\n\nDanke, {name}! Und hier - das waren meine allerersten Magierwerkzeuge. Sie sind ein wenig zerkratzt, haben sich aber immer bewährt. Sucht Euch eines davon aus - ich bin sicher, Ihr werdet es nützlich finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[1881] = { id = 1881, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Anastasia", description = "{name}, Anastasia Hirschbrunn hat eine Aufgabe für jemanden mit Euren Talenten. Sprecht mit ihr im Magieviertel von Unterstadt und bereitet Euch auf den ersten Auftrag der Magier der Verlassenen vor.", sourceObjective = "Sprecht mit Anastasia Hirschbrunn.", completion = "Seid gegrüßt, {name}. Ihr wart weise, meinem Ruf zu folgen. Noch weiser wäre es, meine folgenden Worte zu beachten...", sourceObjectiveStatus = "unverified-source-field" }
quests[1882] = { id = 1882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balnirs Bauernhof", description = "Die Pestländer im Osten sind entartet. Der Lichkönig hat sie ersonnen, und jetzt breitet sich ihre Magie im Erdboden aus und verderbt und tötet alles Leben. Die zerstörerischen Kräfte der Seuche haben zwar eine gewisse Bezauberung, doch wir, die Magier der Verlassenen, sind der Meinung, sie ist ungehörig und muss ausgemerzt werden.\n\nDoch zuerst müssen wir herausfinden, wie weit sie sich nach Tirisfal ausgebreitet hat. Geht zu Balnirs Bauernhof im Osten von Tirisfal. Im Garten blühen Blumen – Löwenmäulchen. Sammelt sie und kehrt zurück.", sourceObjective = "Bringt Balnirlöwenmäulchen zu Anastasia Hirschbrunn im Magierviertel von Unterstadt.", progress = "Habt Ihr die Löwenmäulchen? Diese Pflanzenart ist höchst empfänglich für magische Energien. Das Studium der Löwenmäulchen aus der unmittelbaren Nähe der Pestländer kann uns sagen, ob die Seuche schon in Tirisfal eingedrungen ist.", completion = "Ah, das ist ein wunderbares Exemplar. Ich schicke es zu unseren Apothekern, damit sie das Ausmaß der Besudelung der Pestländer bestimmen können.\n\nGut gemacht, {name}. Als Dank für Eure Dienste, habt Ihr die Wahl: Wollt Ihr eine Kugel oder einen Stab? Was auch immer wählt, Ihr werdet es recht nützlich finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[1883] = { id = 1883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Un'thuwa", description = "Un'thuwa, Stammesmagier in Sen'jin, spürt eine Störung in den magischen Strömen von Durotar und bittet um Unterstützung. Sprecht mit Un'thuwa und tut, was Ihr könnt, um ihm zu helfen.\n\nGelingt Euch das, werden Euch zu gegebener Zeit weitere Geheimnisse enthüllt.", sourceObjective = "Sprecht mit Un'thuwa.", completion = "Grüße, {name}. Gelobet seid Ihr, denn meine Bitte um Unterstützung wurde erhört. Hoffen wir, dass Ihr der Aufgabe gewachsen seid...", sourceObjectiveStatus = "unverified-source-field" }
quests[1884] = { id = 1884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jujuhaufen", description = "Der Hexenmeister Zalazane von den Echoinseln hat den normalen Fluss der Magie in Durotar gestört. Das vollbringt er mit besudelten Fetischen, Jujuhaufen, die er auf der Echohauptinsel in seinen Hütten aufgeschichtet hat.\n\nDiese Haufen haben unser Ökosystem verdorben und Hexenmeistern und Höllenkreaturen, die in den dunklen Winkeln des Landes hausen, Macht gegeben.\n\nIhr müsst diese Jujuhaufen zerstören, {name}, bevor der Fluss der Magie für immer verändert ist.", sourceObjective = "Zerstört 4 Jujuhaufen und kehrt dann zu Un'thuwa in Sen'jin zurück.", progress = "Ihr müsst Euch beeilen, {name}. Zerstört die Jujuhaufen!", completion = "Ich spüre, dass Zalazanes Jujuhaufen zerstört wurden. Mit Zeit und etwas Glück wird sich der Fluss der Magie in Durotar wieder normalisieren.\n\nIhr habt eine Großtat für Euer Volk vollbracht, {name}. Und Ihr habt Euch unser, der {class} der Horde, als würdig erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[1885] = { id = 1885, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mennet Carkad", description = "{name}? Nicht ganz das, was ich erwartet hatte, wenn man bedenkt, dass Carkad selbst Interesse an Euch gezeigt hat. Aber das Aussehen kann täuschen, nicht?\n\nSo oder so, Ihr solltet ihn schnellstmöglich aufsuchen. Ihr könnt Euch nicht vorstellen, was aus den Letzten geworden ist, die seinem Ruf nicht Folge leisteten.", sourceObjective = "Sprecht mit Mennet Carkad im Schurkenviertel von Unterstadt.", completion = "Hm. Ihr seid zweifellos in dem Augenblick hierher gekommen, als Ihr meinen Ruf vernommen habt, nicht? Natürlich. Von einem angehenden Todespirscher hätte ich nichts anderes erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1886] = { id = 1886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Wenn Ihr Euch den Todespirschern anschließen möchtet, der Elitewache von Lord Varimathras, müsst Ihr Euren Wert beweisen.\n\nIch will Euch nichts vormachen, {name}, diese Aufgabe könnte Euren Tod bedeuten.\n\nIch habe ein paar Angelegenheiten, die geregelt werden müssen. Ich benötige die persönlichen Habseligkeiten von Astor Hadren, einem Boten, der zwischen Silberwald und Unterstadt pendelt. Die Beschaffungsmethode überlasse ich ganz Euch.\n\nJe weniger Ihr über diese Angelegenheit Bescheid wisst, desto besser. Wenn Ihr Erfolg habt, sage ich Euch mehr.", sourceObjective = "Beschafft Astors Vorstellungsschreiben und bringt es zu Mennet Carkad im Schurkenviertel.", progress = "Erfolgsmeldung?", completion = "Gut gemacht, {name}. Ihr habt den ersten Teil dieser Prüfung bestanden. Hoffentlich hat Andron keinen Wind von Euren Aktivitäten bekommen, sodass wir ihn davon überzeugen können, dass Ihr wirklich der Bote seid, den er erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[1898] = { id = 1898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Das Empfehlungsschreiben sollte Andron überzeugen, dass Ihr der Bote seid, auf den er gewartet hat. Ich kenne Andron, er ist nicht so helle im Kopf, dass er Verdacht schöpfen würde.\n\nLord Varimathras vermutet, dass Andron einer anderen Gruppe Unterstützung zuteilwerden ließ. Er möchte wissen, was das für eine Organisation ist, und braucht einen Beweis.\n\nIch möchte, dass Ihr mit Andron sprecht und diese Information bekommt. Ihr findet ihn in seinem Geschäft nahe des Apothekariums.", sourceObjective = "Sprecht mit Andron Gant in Unterstadt.", progress = "Hallo. Kann ich etwas für Euch tun?", completion = "Ah, ja, ich habe Euch erwartet. Ich darf davon ausgehen, dass unsere gemeinsamen Bekannten mit den Informationen, die ich bisher lieferte, zufrieden waren?\n\nVermutlich hat es keinen Sinn, Euch zu fragen. Ich bezweifle, dass sie Euch mit diesem Wissen belasten würden. Warum so viel Vertrauen in den Boten setzen, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[1899] = { id = 1899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Ihr findet das Geschäftsbuch mit den Informationen, die Eure Auftraggeber suchen, auf dem Bücherregal hinter mir. Überbringt es mit meinen besten Wünschen und sagt ihnen, dass ich es bevorzugen würde, wenn sie Euch schicken, sollte unsere Übereinkunft ihnen so lieb und teuer sein, dass sie sie fortsetzen möchten.", sourceObjective = "Bringt Androns Geschäftsbuch zu Mennet Carkad im Schurkenviertel von Unterstadt.", progress = "Erfolg, {name}?", completion = "Das sind eindeutig mehr Informationen, als ich mir je von Andron erhofft hätte. Lasst sie mich einen Moment studieren, bevor ich Euch Eure nächste Aufgabe nenne.", sourceObjectiveStatus = "unverified-source-field" }
quests[1918] = { id = 1918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das beschmutzte Element", description = "Der erschlagene Elementar hat eine intensiv glühende Kugel aus Wasser zurückgelassen. Der Inhalt dieser Kugel ist bestenfalls als abstoßend zu bezeichnen. Es ist eine sichere Annahme, dass was auch immer das Wasser des Mystralsees beschmutzt hat, höchstwahrscheinlich im Wasser dieser Kugel enthalten ist.\n\nEs ist nicht gerade allgemein bekannt, wer sich für solch einen Fund interessieren könnte; vielleicht hat ja Mastok Wutfauch im Splitterholzposten eine Idee.", sourceObjective = "Bringt die beschmutzte Wasserkugel zu Mastok Wutfauch im Splitterholzposten im Eschental.", progress = "Ja, was wollt Ihr?", completion = "Ihr findet eine eklige Kugel aus Wasser und beschließt, sie mir zu bringen? Wer bin ich denn, der Irdene Ring oder was?\n\nMoment mal, das bringt mich auf eine Idee... vielleicht braucht Ihr den Irdenen Ring dafür. Ich meine, wenn es dabei hilft, die Situation am See endgültig zu klären, dann bin ich absolut dafür.\n\nIhr wisst, wer der Irdene Ring ist, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[1919] = { id = 1919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung bei Jennea", description = "Euer Wissen über das Handwerk wächst, {name}. Seid Ihr jetzt bereit, die wahren Lektionen zu beginnen? Seid Ihr bereit, Euren Platz in dem geheimen Krieg einzunehmen, den wir führen?\n\nWenn ja, sprecht mit Jennea Haubitz im Magiersanktum im Magierviertel von Sturmwind. Sie hat eine Aufgabe für Euch, die Euer erstes Fenster in die Welt des Unsichtbaren öffnen wird.", sourceObjective = "Sprecht in Sturmwind mit Jennea Haubitz.", completion = "{name}, ich habe eine Mission für Euch hier im Magierviertel. Hört genau zu, denn es gilt, keine Zeit zu verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[1920] = { id = 1920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchungen im Blauen Eremiten", description = "Es wurde von einer Störung in der Taverne 'Zum blauen Eremiten' im Magierviertel berichtet. Jetzt wandern seltsame unsichtbare Kreaturen durch die Taverne. Ich fürchte, dort hat sich ein Manariss gebildet.\n\nIch möchte, dass Ihr die Taverne untersucht und diese Kreaturen fangt. Benutzt die Inkantation der Manifestation, um die Kreaturen in der Taverne sichtbar zu machen, überwältigt sie und fangt sie dann mit einem Verwahrungskasten ein. Wenn Ihr genug habt, kommt mit den gefüllten Kästen, den leeren Kästen und der Anrufung zu mir zurück.", sourceObjective = "Nehmt Euch die Inkantation der Manifestation und die Truhe mit Verwahrungskästen vom Tisch, hinter Jennea Haubitz. Bringt 3 gefüllte Verwahrungskästen zu Jennea im Magiersanktum.", progress = "Habt Ihr die Kreaturen gefangen, {name}? Sie müssen untersucht werden, damit wir den Grund für ihr Kommen herausfinden.", completion = "Sehr gut gemacht! Ich werde diese Kreaturen studieren und mit Geschick und Glück herausfinden, wie sie in unsere Welt gelangen konnten.\n\nEuer Wert für die Gesellschaft der {class} wächst, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[1921] = { id = 1921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Materialsammlung", description = "Ihr habt Euren Magierkollegen gut gedient, jetzt wird es Zeit, die Hexerrobe anzuziehen. Wynne Larson kann Eure Robe nähen, aber Ihr müsst ihr die erforderlichen Materialien bringen. \n\nEure Robe wird aus Leinen bestehen, das leicht zu beschaffen ist, aber Ihr müsst auch aufgeladene Rissedelsteine finden, die nur in der Silberbachmine vom Loch Modan zu finden sind, wo die Minenarbeiterliga der Zwerge sie in Kisten zurückgelassen hat.\n\nBeschafft das Leinen und die Edelsteine und bringt sie zu Wynne Larson in das Konfektionsgeschäft Larson im Magierviertel.", sourceObjective = "Bringt 10 Leinenstoff und 6 aufgeladene Rissedelsteine zu Wynne Larson in Sturmwind.", progress = "Hallo, {name}. Jennea sagte mir, dass Ihr kommt. Habt Ihr etwas für mich?", completion = "Ja, das sind großartige Leinentücher. Daraus kann ich eine prima Robe machen. Und sobald die Rissedelsteine hineingewoben sind, haben wir ein Gewand, das eines Magiers würdig ist!", sourceObjectiveStatus = "unverified-source-field" }
quests[1938] = { id = 1938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urs Abhandlung über Schattenmagie", description = "Vor langer Zeit studierten drei Magier in diesem Turm, bis einer den dunklen Künsten verfiel. Man bedrängte ihn, von dieser bösen Magie zu lassen, aber er konnte nicht widerstehen. Und so wurde er verbannt.\n\nDas neue Domizil des gefallenen Magiers ist der Turm von Ilgalar im Rotkammgebirge. Er hat ein mächtiges Buch dorthin mitgenommen -'Urs Abhandlung über Schattenmagie'.\n\nWir, die Magier von Sturmwind, möchten dieses Buch zurück. Begebt Euch in den Turm von Ilgalar, sucht den Folianten in seiner Bibliothek und bringt ihn mir.", sourceObjective = "Bringt 'Urs Abhandlung über Schattenmagie' zu Zaubermeister Andromath in Sturmwind.", progress = "Habt Ihr das Buch, {name}? Seine Geheimnisse sind nicht für die Ungeübten bestimmt, das Studium seines Inhalts kann zu Verdammnis und Ruin führen.", completion = "Ich hatte befürchtet, dass Morganth das Buch anderswo versteckt oder einen Weg gefunden haben könnte, es zu öffnen und den Inhalt zu lesen.\n\nEin Glück, dass ihm das nicht gelang und die Siegel, mit denen wir 'Urs Abhandlung über Schattenmagie' sicherten, unversehrt sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[1939] = { id = 1939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaubermeister Andromath", description = "Der Zaubermeister Andromath wünscht Euch zu sprechen, {name}. Er ist oben im Magiersanktum im Magierviertel von Sturmwind.\n\nEs wäre klug, mit ihm zu sprechen, denn Andromath ist einer der mächtigsten Magier, die nicht in Dalaran eingesperrt sind. Ein Rat von ihm ist in jedem Fall ein guter Rat.", sourceObjective = "Sprecht mit Zaubermeister Andromath.", completion = "Seid gegrüßt, {name}. Ich freue mich, Euch zu sehen, und hoffe, Ihr habt Zeit, den Worten eines alten Mannes zu lauschen...", sourceObjectiveStatus = "unverified-source-field" }
quests[1940] = { id = 1940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makellose Spinnenseide", description = "Eure Treue ist unerschütterlich, {name}. Ich glaube, es ist an der Zeit, dass Ihr ein besseres Kleidungsstück bekommt, das einem geschickten Magier von Eurem Rang angemessener ist. Wenn Ihr die erforderlichen Materialien sammeln könnt, werde ich veranlassen, dass die Robe angefertigt wird.\n\nIhr müsst in den Dämmerwald und Aaskrabblerspinnen jagen. Extrahiert ihre Seide, aber nur die feinste und makelloseste. Wenn Ihr genug davon habt, bringt sie zu Wynne Larson ins Konfektionsgeschäft Larson hier im Magierviertel. Sie wird Eure Robe anfertigen.", sourceObjective = "Bringt 8 Rollen makelloser Spinnenseide zu Wynne Larson in Sturmwind.", progress = "Ah, ja. Die {class} im Magiersanktum sagten, dass Ihr mit mir sprechen wollt. Habt Ihr die benötigte Seide?", completion = "Das sind herrliche Exemplare. Ich mach mich gleich an die Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[1941] = { id = 1941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Managewirkte Robe", sourceObjective = "Hier ist Eure Robe. Er ist eine meiner besten bisher! Tragt sie voller Stolz, und wenn die Leute Euch fragen... sagt ihnen, Ihr habt sie vom Konfektionsgeschäft Larson.", sourceObjectiveStatus = "unverified-source-field" }
quests[1942] = { id = 1942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Astralknotengewand", sourceObjective = "Euer Gewand ist fertig! Die Seide, die Ihr mir gebracht hattet, war so hübsch... es stört Euch doch nicht, dass ich es etwas kürzer gemacht habe, damit noch etwas Seide für mich übrig bleibt, oder?\n\nDas war nur ein Witz. Das Gewand wird sitzen wie angegossen und es eignet sich gleichermaßen gut, um damit in Abenteuer zu ziehen oder zu einem Empfang zu gehen. Viel Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[1943] = { id = 1943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gespräch mit Deino", description = "Die Trollmagierin Deino bedarf Eurer Unterstützung, {name}. Sie residiert in Orgrimmar im Dunkeldornenlodge.", sourceObjective = "Sprecht mit Deino.", completion = "Gut, Ihr seid gekommen. Meine Aufgabe ist nicht leicht, aber für die Gesellschaft der {class} von entscheidender Bedeutung. Wenn Ihr mich unterstützt, soll es Euer Schaden nicht sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[1944] = { id = 1944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasser von Xavian", description = "Die legendäre Stadt Xavian liegt tief im östlichen Teil des Eschentals. Die Geschichten über ihr Wissen aus längst vergangener Zeit sind den Gebildeten wohl bekannt. Man sagt, die Wasser von Xavian bergen enorme magische Kräfte.\n\nBringt mir eine Probe dieses Wassers direkt von der Quelle.\n\nNehmt dieses Fläschchen und reist nach Xavian. Füllt Wasser am höchsten Wasserfall ab und kehrt zu mir zurück. Aber seid vorsichtig in der uralten Stadt - heute hausen Satyrn in den Ruinen, die gar nicht mögen, wenn sich Magier in ihre Angelegenheiten einmischen.", sourceObjective = "Bringt die Wasserprobe von Xavian zu Deino in Orgrimmar.", progress = "Ich sehe mit Freuden, dass Ihr mit heiler Haut zurückgekehrt seid, {name}. Habt Ihr die Wasserprobe? Ich kann es kaum erwarten, ihre Eigenschaften zu studieren.", completion = "Ah, sehr gut. Die Satyrn von Xavian haben Euch doch hoffentlich nicht allzu viele Schwierigkeiten gemacht?\n\nDanke, {name}. Ich werde diese Wasserprobe aus Xavian unverzüglich untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
